import { identifyTelemetryAccount } from '@/utils/telemetryPolicy';
import { fetchLocalApi } from '@/utils/localApi';

import { useEffect, useState } from 'react';
import { createLogger } from '../utils/logger';
import { JUST_SIGNED_IN_STORAGE_KEY } from '../constants/auth';
import { PROXY_URL } from '../constants/proxy';
import { errorMessage } from '@rivet/core/utils/errorMessage';

const log = createLogger('useOAuthCallback');

type OAuthCallbackState = {
  isProcessing: boolean;
  isComplete: boolean;
  error: string | null;
};

export const useOAuthCallback = () => {
  const [state, setState] = useState<OAuthCallbackState>({
    isProcessing: false,
    isComplete: false,
    error: null,
  });

  useEffect(() => {
    const abortController = new AbortController();
    let isCancelled = false;

    const processOAuthCallback = async () => {
      const hash = window.location.hash;
      const search = window.location.search;

      if (!hash || !hash.includes('access_token')) {
        return;
      }

      if (isCancelled) return;
      setState({ isProcessing: true, isComplete: false, error: null });

      try {
        log.info('Processing OAuth callback...');

        const hashParams = new URLSearchParams(hash.substring(1));
        const accessToken = hashParams.get('access_token');
        const refreshToken = hashParams.get('refresh_token');

        const queryParams = new URLSearchParams(search);
        const sessionId = queryParams.get('session');

        if (!accessToken) {
          throw new Error('No access token found in URL');
        }

        if (!sessionId) {
          throw new Error('No session ID found in URL');
        }

        log.info(`Completing OAuth with session: ${sessionId}`);

        const response = await fetch(`${PROXY_URL}/api/auth/google/complete`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            sessionId,
            accessToken,
            refreshToken,
          }),
          signal: abortController.signal,
        });

        const result = await response.json();

        if (!response.ok || !result.success) {
          throw new Error(
            result.error ||
              result.message ||
              'Failed to complete authentication',
          );
        }

        log.info('OAuth authentication completed successfully');

        if (isCancelled) return;
        identifyTelemetryAccount({
          userId: result.user?.id,
          email: result.user?.email,
        });

        if (result.user?.email && accessToken) {
          try {
            const storeResponse = await fetchLocalApi('/api/auth/store', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                email: result.user.email,
                token: accessToken,
                refreshToken,
                userId: result.user.id,
              }),
              signal: abortController.signal,
            });
            if (!storeResponse.ok) {
              log.warn(`Local auth store returned ${storeResponse.status}`);
            }
          } catch (storeError) {
            if (isCancelled) return;
            log.warn('Failed to store auth locally:', storeError);
          }
        }

        if (isCancelled) return;

        window.sessionStorage.setItem(JUST_SIGNED_IN_STORAGE_KEY, '1');

        const newUrl = window.location.pathname;
        window.history.replaceState({}, document.title, newUrl);

        setState({ isProcessing: false, isComplete: true, error: null });
      } catch (error) {
        if (isCancelled) return;
        log.warn('OAuth callback error:', error);
        setState({
          isProcessing: false,
          isComplete: false,
          error: errorMessage(error, 'Unknown error occurred'),
        });
      }
    };

    processOAuthCallback();

    return () => {
      isCancelled = true;
      abortController.abort();
    };
  }, []);

  return state;
};
