type IframePreviewProps = {
  isInteractionDisabled?: boolean;
  framework: Framework;
  userPort?: number;
};

const STATIC_PREVIEW_PATH_SUFFIX = '/static/';

const isBaseStaticPreviewUrl = (url: string): boolean => {
  try {
    return new URL(url, 'http://localhost').pathname.endsWith(
      STATIC_PREVIEW_PATH_SUFFIX,
    );
  } catch {
    return url.endsWith(STATIC_PREVIEW_PATH_SUFFIX);
  }
};

type DirectionFailureState = Exclude<
  FailureReportIssueState,
  'preview_unavailable'
>;

type VariantIssueContent = {
  title: string;
  description: string;
  detail?: string;
  isDetailClamped?: boolean;
} & (
  | { state: FailureReportIssueState; agentPastePackage: AgentPastePackage }
  | { state: 'variant_cancelled' }
);

type DirectionFailureCopy = {
  description: string;
  failedStep: string;
};

const DIRECTION_FAILED_TITLE = 'Direction failed';

const DIRECTION_FAILED_ASK =
  'Find why this Rivet direction failed and what to change so it succeeds when I generate it again.';

const DIRECTION_FAILURE_COPY: Record<
  DirectionFailureState,
  DirectionFailureCopy
> = {
  variant_worker_failed: {
    description: 'The worker stopped before producing a usable result.',
    failedStep: 'Worker run',
  },
  variant_output_integrity_failed: {
    description:
      'The worker completed, but Rivet found a structural problem in the generated files.',
    failedStep: 'Output check',
  },
  variant_verification_unavailable: {
    description:
      'The worker completed, but Rivet couldn’t inspect its generated files.',
    failedStep: 'Output verification',
  },
};

const DIRECTION_FAILURE_LABELS: ReadonlyMap<string, string> = new Map([
  ['EXECUTOR_WORKER_FAILED', 'The coding agent exited with an error.'],
  [
    'EXECUTOR_RUNTIME_UNSUPPORTED',
    'The selected coding agent can’t build directions in the background.',
  ],
  [
    'EXECUTOR_UNSUPPORTED_ITEM',
    'The background worker can’t build this kind of direction.',
  ],
  [
    'EXECUTOR_ITEM_UNSEEN',
    'Rivet lost track of this direction while starting it.',
  ],
  [
    'EXECUTOR_ARTIFACT_INVALID',
    'The coding agent finished, but its result was incomplete.',
  ],
  [
    'EXECUTOR_REQUEUE_LOST',
    'Rivet couldn’t run this direction again after a failed check.',
  ],
  [
    'RUNTIME_VALIDATION_FAILED',
    'Rivet couldn’t prepare a workspace for this direction.',
  ],
  [
    'SCAFFOLD_FAILED',
    'Rivet couldn’t set up the starter project for this direction.',
  ],
  ['DEPENDENCY_FAILED', 'A direction this one builds on failed first.'],
  [
    'PREVIEW_ROUTE_CONTEXT_INVALID',
    'The coding agent listed preview pages that Rivet couldn’t open.',
  ],
  [
    'INTERNAL_ERROR',
    'Rivet hit an internal error while finishing this direction.',
  ],
]);

const directionFailureState = (errorCode?: string): DirectionFailureState => {
  switch (errorCode) {
    case 'VARIANT_VERIFICATION_UNAVAILABLE':
      return 'variant_verification_unavailable';
    case 'VARIANT_QA_FAILED':
      return 'variant_output_integrity_failed';
    default:
      return 'variant_worker_failed';
  }
};

const describeWorker = (
  runtime: AgentVariantSnapshot['runtime'],
): string | undefined =>
  runtime
    ? [
        runtime.vendor,
        runtime.model,
        runtime.effort ? `effort ${runtime.effort}` : undefined,
      ]
        .filter(Boolean)
        .join(' / ')
    : undefined;

type PreviewRetryTarget = { sessionId: string; variantId: string };

type PreviewUnavailableReason = NonNullable<
  AgentVariantSnapshot['previewUnavailable']
>['reason'];

type PreviewUnavailableCopy = {
  summary: string;
  nextStep?: string;
};

const PREVIEW_PREPARE_FAILED =
  'The direction is saved, but Rivet couldn’t prepare its preview.';

const PREVIEW_UNAVAILABLE_COPY: Record<
  PreviewUnavailableReason,
  PreviewUnavailableCopy
> = {
  spawn_error: {
    summary: 'The direction is saved, but its preview process didn’t start.',
  },
  exited: {
    summary:
      'The direction is saved, but its preview stopped before it was ready.',
  },
  timeout: {
    summary:
      'The direction is saved, but its preview took too long to become ready.',
  },
  dependency_install_failed: {
    summary:
      'The direction is saved, but its dependencies couldn’t be prepared.',
    nextStep: 'Fix the installation error, then retry the preview.',
  },
  compile_error: {
    summary: 'The direction is saved, but its app couldn’t compile.',
    nextStep: 'Fix the app error, then retry the preview.',
  },
  missing_dev_script: {
    summary:
      'The direction is saved, but Rivet couldn’t find a dev script to preview it.',
  },
  missing_static_entry: {
    summary:
      'The direction is saved, but Rivet couldn’t find an HTML entry to preview it.',
  },
  idle_timeout: {
    summary: PREVIEW_PREPARE_FAILED,
  },
  unknown: {
    summary: PREVIEW_PREPARE_FAILED,
  },
};

const describePreviewUnavailable = (copy: PreviewUnavailableCopy): string => {
  if (!copy.nextStep) return copy.summary;
  return `${copy.summary} ${copy.nextStep}`;
};

const copyForAgentAction = ({
  text,
  issueState,
}: {
  text: AgentPastePackage;
  issueState: FailureReportIssueState;
}): SurfaceAction => ({
  label: 'Copy for agent',
  onClick: () =>
    void copyVariantContext({ text, copyKind: 'failure_report', issueState }),
});

const getVariantIssueContent = (
  variant: AgentVariantSnapshot,
  sessionId: string,
): VariantIssueContent | null => {
  if (variant.status === 'failed') {
    const state = directionFailureState(variant.errorCode);
    const copy = DIRECTION_FAILURE_COPY[state];
    const friendlyLabel = variant.errorCode
      ? DIRECTION_FAILURE_LABELS.get(variant.errorCode)
      : undefined;
    return {
      state,
      title: DIRECTION_FAILED_TITLE,
      description: copy.description,
      detail: friendlyLabel ?? variant.errorMessage ?? variant.errorCode,
      isDetailClamped: true,
      agentPastePackage: formatAgentPastePackage({
        problem: `${DIRECTION_FAILED_TITLE}. ${copy.description}`,
        ask: DIRECTION_FAILED_ASK,
        errorCode: variant.errorCode,
        failedStep: copy.failedStep,
        worker: describeWorker(variant.runtime),
        rivetVersion: __RIVET_VERSION__,
        nodeVersion: variant.nodeVersion,
        directionLabel: variant.label,
        directionRef: variant.directionRef,
        sessionId,
        errorExcerpt: variant.errorMessage,
      }),
    };
  }
  if (variant.status === 'cancelled') {
    return {
      state: 'variant_cancelled',
      title: 'Direction was cancelled',
      description:
        'Rivet stopped before a preview was ready. Your other directions are unchanged.',
    };
  }
  if (
    variant.status === 'succeeded' &&
    variant.previewUnavailable &&
    variant.previewUnavailable.reason !== 'idle_timeout'
  ) {
    const unavailable = variant.previewUnavailable;
    const portDetail = unavailable.portInUse
      ? 'The preview port was already in use.'
      : undefined;
    const copy = PREVIEW_UNAVAILABLE_COPY[unavailable.reason];
    const title = 'Rivet couldn’t preview this direction';
    return {
      state: 'preview_unavailable',
      title,
      description: describePreviewUnavailable(copy),
      detail: unavailable.detail ?? portDetail,
      agentPastePackage: formatAgentPastePackage({
        problem: `${title}. ${copy.summary}`,
        reasonCode: unavailable.reasonCode,
        reasonDetail: unavailable.reasonDetail,
        nextStep: copy.nextStep,
        rivetVersion: __RIVET_VERSION__,
        nodeVersion: unavailable.nodeVersion,
        directionLabel: variant.label,
        directionRef: variant.directionRef,
        sessionId,
      }),
    };
  }
  return null;
};

const VariantIssueSurface = ({
  issue,
  retryTarget,
}: {
  issue: VariantIssueContent;
  retryTarget?: PreviewRetryTarget;
}) => {
  const posthog = usePostHog();
  const isRetryingRef = useRef(false);
  const [isRetrying, setIsRetrying] = useState(false);
  const [retryError, setRetryError] = useState<string | null>(null);

  const retryPreview = async () => {
    if (!retryTarget || isRetryingRef.current) return;
    isRetryingRef.current = true;
    setIsRetrying(true);
    setRetryError(null);
    posthog?.capture('preview_retry_clicked', {
      session_id: retryTarget.sessionId,
      variant_id: retryTarget.variantId,
    });
    try {
      const response = await fetchLocalApi(
        `/api/variants/${encodeURIComponent(retryTarget.sessionId)}/preview-port`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            variantId: retryTarget.variantId,
            retry: true,
          }),
        },
      );
      if (!response.ok) {
        const parsed = VariantsErrorResponseSchema.safeParse(
          await response.json().catch(() => ({})),
        );
        throw new Error(
          parsed.success
            ? parsed.data.message
            : 'The preview could not restart. Try again.',
        );
      }
    } catch (error) {
      setRetryError(
        errorMessage(error, 'The preview could not restart. Try again.'),
      );
    } finally {
      isRetryingRef.current = false;
      setIsRetrying(false);
    }
  };

  const actions: SurfaceAction[] = [
    ...(retryTarget && !isRetrying
      ? [{ label: 'Retry preview', onClick: () => void retryPreview() }]
      : []),
    ...(issue.state === 'variant_cancelled'
      ? []
      : [
          copyForAgentAction({
            text: issue.agentPastePackage,
            issueState: issue.state,
          }),
        ]),
  ];
  const isError = issue.state !== 'variant_cancelled';

  return (
    <StatusSurface
      fill="overlay"
      size="sm"
      state={issue.state}
      role={isError ? 'alert' : 'status'}
      tone={isError ? 'error' : 'neutral'}
      title={issue.title}
      description={issue.description}
      busy={isRetrying}
      actions={actions}
    >
      {isRetrying ? (
        <p className="text-muted-foreground text-xs">Starting preview…</p>
      ) : null}
      {retryError ? (
        <p className="text-muted-foreground text-xs">{retryError}</p>
      ) : null}
      {issue.detail ? (
        <p
          data-rivet-private
          className={cn(
            'ph-no-capture text-muted-foreground text-xs leading-relaxed break-words whitespace-pre-wrap',
            issue.isDetailClamped ? 'line-clamp-3' : 'max-h-40 overflow-auto',
          )}
        >
          {issue.detail}
        </p>
      ) : null}
    </StatusSurface>
  );
};

const IframePreview = ({
  isInteractionDisabled: _isInteractionDisabled = false,
  framework,
  userPort: _userPort,
}: IframePreviewProps) => {
  const projectPath = useAtomValue(projectPathAtom);
  const externalRemountKey = useAtomValue(iframeRemountKeyAtom);
  const setIframeRemountKey = useSetAtom(iframeRemountKeyAtom);
  const previewOverrideUrl = useAtomValue(iframePreviewOverrideUrlAtom);
  const setPreviewOverrideUrl = useSetAtom(iframePreviewOverrideUrlAtom);
  const variantsSnapshot = useAtomValue(agentVariantsSnapshotAtom);
  const agentApplyMode = useAtomValue(agentApplyModeAtom);
  const variantPreviewPreferDevServer = useAtomValue(
    variantPreviewPreferDevServerAtom,
  );
  const proxiedDevServerVariantId = useAtomValue(proxiedDevServerVariantIdAtom);
  const historyReplayActive = useAtomValue(historyReplayActiveAtom);
  const historyReplayBootPending = useAtomValue(historyReplayBootPendingAtom);
  const setProxiedDevServerVariantId = useSetAtom(
    proxiedDevServerVariantIdAtom,
  );
  const split = useAtomValue(variantSplitViewAtom);
  const selectedPastVariant = useAtomValue(selectedPastVariantAtom);
  const setVariantPreviewPreferDevServer = useSetAtom(
    variantPreviewPreferDevServerAtom,
  );
  const isFreshVariantSession =
    variantsSnapshot.active && variantsSnapshot.projectContext.kind === 'fresh';
  const selectedVariantId = useAtomValue(selectedVariantIdAtom);
  const armedVariant = variantsSnapshot.active
    ? (variantsSnapshot.variants.find(
        (v) =>
          v.workItemId === selectedVariantId &&
          (v.status === 'pending' ||
            v.status === 'running' ||
            (v.status === 'succeeded' &&
              !v.preview &&
              typeof v.port !== 'number' &&
              (!v.previewUnavailable ||
                v.previewUnavailable.reason === 'idle_timeout'))),
      ) ?? null)
    : null;
  const variantsGenerating =
    variantsSnapshot.active &&
    variantsSnapshot.variants.some(
      (v) => v.status === 'pending' || v.status === 'running',
    );
  const showVariantsPlaceholder = isFreshVariantSession || variantsGenerating;
  const selectedVariant = variantsSnapshot.active
    ? (variantsSnapshot.variants.find(
        (variant) => variant.workItemId === selectedVariantId,
      ) ?? null)
    : null;
  const variantIssue =
    variantsSnapshot.active && selectedVariant
      ? getVariantIssueContent(selectedVariant, variantsSnapshot.sessionId)
      : null;
  const isBaseStaticPreviewOverride =
    framework === 'static' &&
    previewOverrideUrl !== null &&
    isBaseStaticPreviewUrl(previewOverrideUrl);

  useEffect(() => {
    if (variantsSnapshot.active) return;
    setVariantPreviewPreferDevServer(false);
  }, [variantsSnapshot.active, setVariantPreviewPreferDevServer]);

  const wasInSplitRef = useRef(false);

  useEffect(() => {
    const inSplit = Boolean(split?.left || split?.right);
    const enteringSplit = inSplit && !wasInSplitRef.current;
    wasInSplitRef.current = inSplit;
    const sessionId = variantsSnapshot.active
      ? variantsSnapshot.sessionId
      : null;
    if (
      !sessionId ||
      !shouldResetProxyOnSplitEntry({
        enteringSplit,
        isExistingSession:
          variantsSnapshot.active &&
          variantsSnapshot.projectContext.kind === 'existing',
        hasActiveVariantProxy:
          variantPreviewPreferDevServer && proxiedDevServerVariantId !== null,
      })
    ) {
      return;
    }
    setVariantPreviewPreferDevServer(false);
    setProxiedDevServerVariantId(null);
    setIframeRemountKey((n) => n + 1);
    void fetchLocalApi(
      `/api/variants/${encodeURIComponent(sessionId)}/preview-port`,
      {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ variantId: null }),
      },
    ).catch(() => {});
  }, [
    split,
    variantsSnapshot,
    variantPreviewPreferDevServer,
    proxiedDevServerVariantId,
    setVariantPreviewPreferDevServer,
    setProxiedDevServerVariantId,
    setIframeRemountKey,
  ]);

  const autoPreviewUrl = useMemo(() => {
    if (variantPreviewPreferDevServer) return null;
    if (previewOverrideUrl && !isBaseStaticPreviewOverride) return null;
    if (!variantsSnapshot.active) return null;
    const { stage, variants } = variantsSnapshot;
    const isTerminalStage = stage === 'ready' || stage === 'degraded';
    const hasActiveRefinement = variants.some(
      (v) =>
        v.refinement?.status === 'pending' ||
        v.refinement?.status === 'running',
    );
    if (!isTerminalStage && !hasActiveRefinement) return null;

    const first = variants.find(
      (v) => v.status === 'succeeded' && v.preview?.kind === 'static_artifact',
    );
    return first?.preview?.kind === 'static_artifact'
      ? resolveVariantPreviewUrl({
          sessionId: variantsSnapshot.sessionId,
          variant: first,
          projectContext: variantsSnapshot.projectContext,
        })
      : null;
  }, [
    isBaseStaticPreviewOverride,
    previewOverrideUrl,
    variantPreviewPreferDevServer,
    variantsSnapshot,
  ]);

  const effectivePreviewUrl = autoPreviewUrl ?? previewOverrideUrl;
  const selectedStaticVariant = useMemo(() => {
    if (!variantsSnapshot.active || !effectivePreviewUrl) return null;
    return (
      variantsSnapshot.variants.find(
        (candidate) =>
          candidate.preview?.kind === 'static_artifact' &&
          effectivePreviewUrl.startsWith(candidate.preview.url),
      ) ?? null
    );
  }, [effectivePreviewUrl, variantsSnapshot]);
  const previewTarget = useMemo<PreviewTarget>(() => {
    if (
      selectedPastVariant?.previewKind === 'static' ||
      (selectedPastVariant?.previewKind === 'dev_server' &&
        selectedPastVariant.previewError) ||
      (selectedPastVariant?.previewKind === 'dev_server' &&
        effectivePreviewUrl &&
        isTargetAddressedDevServerPreviewUrl(effectivePreviewUrl))
    ) {
      return {
        kind: 'variant',
        sessionId: selectedPastVariant.sessionId,
        variantId: selectedPastVariant.variantId,
      };
    }
    if (!variantsSnapshot.active) return BASE_TARGET;
    if (selectedStaticVariant) {
      return {
        kind: 'variant',
        sessionId: variantsSnapshot.sessionId,
        variantId: selectedStaticVariant.workItemId,
      };
    }
    if (effectivePreviewUrl) {
      const devServerMatch = effectivePreviewUrl.match(
        /\/__rivet\/preview\/variant\/([^/]+)\/([^/?#]+)/,
      );
      const urlSessionId = devServerMatch?.[1]
        ? decodeURIComponent(devServerMatch[1])
        : null;
      const devServerVariantId = devServerMatch?.[2]
        ? decodeURIComponent(devServerMatch[2])
        : null;
      if (
        urlSessionId === variantsSnapshot.sessionId &&
        devServerVariantId &&
        variantsSnapshot.variants.some(
          (v) => v.workItemId === devServerVariantId,
        )
      ) {
        return {
          kind: 'variant',
          sessionId: variantsSnapshot.sessionId,
          variantId: devServerVariantId,
        };
      }
      const staticMatch = effectivePreviewUrl.match(
        /\/api\/variants\/[^/]+\/static\/([^/?#]+)/,
      );
      const urlVariantId = staticMatch?.[1]
        ? decodeURIComponent(staticMatch[1])
        : null;
      if (
        urlVariantId &&
        variantsSnapshot.variants.some((v) => v.workItemId === urlVariantId)
      ) {
        return {
          kind: 'variant',
          sessionId: variantsSnapshot.sessionId,
          variantId: urlVariantId,
        };
      }
    }
    const inSplit = Boolean(split?.left || split?.right);
    if (
      (!inSplit || isFreshVariantSession) &&
      !effectivePreviewUrl &&
      variantPreviewPreferDevServer &&
      proxiedDevServerVariantId &&
      variantsSnapshot.variants.some(
        (v) => v.workItemId === proxiedDevServerVariantId,
      )
    ) {
      return {
        kind: 'variant',
        sessionId: variantsSnapshot.sessionId,
        variantId: proxiedDevServerVariantId,
      };
    }
    if (
      (!inSplit || isFreshVariantSession) &&
      !effectivePreviewUrl &&
      selectedVariantId &&
      variantsSnapshot.variants.some((v) => v.workItemId === selectedVariantId)
    ) {
      return {
        kind: 'variant',
        sessionId: variantsSnapshot.sessionId,
        variantId: selectedVariantId,
      };
    }
    return BASE_TARGET;
  }, [
    selectedPastVariant,
    selectedStaticVariant,
    variantsSnapshot,
    variantPreviewPreferDevServer,
    proxiedDevServerVariantId,
    effectivePreviewUrl,
    split,
    isFreshVariantSession,
    selectedVariantId,
  ]);
  const refreshedStaticPreviewRef = useRef<string | null>(null);

  useEffect(() => {
    if (
      !selectedStaticVariant ||
      selectedStaticVariant.preview?.kind !== 'static_artifact' ||
      selectedStaticVariant.refinement?.status !== 'succeeded'
    ) {
      return;
    }
    const refreshKey = `${selectedStaticVariant.workItemId}:${selectedStaticVariant.refinement.workItemId}`;
    if (refreshedStaticPreviewRef.current === refreshKey) return;
    refreshedStaticPreviewRef.current = refreshKey;
    if (selectedStaticVariant.previewRoutes?.length) {
      setIframeRemountKey((value) => value + 1);
      return;
    }
    const separator = selectedStaticVariant.preview.url.includes('?')
      ? '&'
      : '?';
    const refinedPreviewUrl = `${selectedStaticVariant.preview.url}${separator}refinement=${encodeURIComponent(
      selectedStaticVariant.refinement.workItemId,
    )}`;
    if (effectivePreviewUrl === refinedPreviewUrl) return;
    setPreviewOverrideUrl(refinedPreviewUrl);
    setIframeRemountKey((n) => n + 1);
  }, [
    effectivePreviewUrl,
    selectedStaticVariant,
    setIframeRemountKey,
    setPreviewOverrideUrl,
    variantsSnapshot,
  ]);

  const isTargetAddressedPreview =
    effectivePreviewUrl !== null &&
    isTargetAddressedDevServerPreviewUrl(effectivePreviewUrl);
  const suppressUpstreamProbe =
    (effectivePreviewUrl !== null && !isTargetAddressedPreview) ||
    (isFreshVariantSession &&
      !variantPreviewPreferDevServer &&
      !isTargetAddressedPreview);
  const {
    isUpstreamReady: upstreamHealthReady,
    iframeRemountKey: localRemountKey,
    probeAttemptCount,
    initialProbeComplete,
  } = usePreviewUpstreamHealth(framework, {
    rerunProbeImmediatelyOnVersion: externalRemountKey,
    probePath: isTargetAddressedPreview ? effectivePreviewUrl : null,
    skip: suppressUpstreamProbe,
  });
  const [confirmedReplayRemountKey, setConfirmedReplayRemountKey] = useState<
    number | null
  >(() =>
    historyReplayActive && upstreamHealthReady ? externalRemountKey : null,
  );
  const [replayProbeStart, setReplayProbeStart] = useState<{
    remountKey: number;
    probeAttemptCount: number;
  } | null>(null);
  if (!historyReplayActive) {
    if (replayProbeStart !== null) setReplayProbeStart(null);
    if (confirmedReplayRemountKey !== null) setConfirmedReplayRemountKey(null);
  } else if (confirmedReplayRemountKey !== externalRemountKey) {
    if (replayProbeStart?.remountKey !== externalRemountKey) {
      setReplayProbeStart({
        remountKey: externalRemountKey,
        probeAttemptCount,
      });
    } else if (
      upstreamHealthReady &&
      probeAttemptCount > replayProbeStart.probeAttemptCount
    ) {
      setConfirmedReplayRemountKey(externalRemountKey);
    }
  }

  const isSelfContainedPreview =
    effectivePreviewUrl !== null && !isTargetAddressedPreview;
  const isUpstreamReady = isSelfContainedPreview || upstreamHealthReady;
  const isReplayAwaitingHealthProbe =
    historyReplayActive &&
    !isTargetAddressedPreview &&
    confirmedReplayRemountKey !== externalRemountKey;
  const replayBooting =
    historyReplayBootPending ||
    isReplayAwaitingHealthProbe ||
    (historyReplayActive && !isUpstreamReady);
  const iframeRemountKey = `${localRemountKey}:${externalRemountKey}`;

  const nestedPreviewPath = extractPreviewPathFromLocation(
    window.location.pathname,
  );
  const devServerPath =
    framework === 'static'
      ? `/static${nestedPreviewPath ?? '/'}`
      : (nestedPreviewPath ?? '/');
  const previewOrigin = getPreviewOrigin(agentApplyMode);
  let overridePreviewSrc: string | null = null;
  if (effectivePreviewUrl) {
    overridePreviewSrc = resolvePreviewSrc({
      agentApplyMode,
      url: effectivePreviewUrl,
    });
  }
  const gatedOverridePreviewSrc =
    isTargetAddressedPreview && !isUpstreamReady
      ? 'about:blank'
      : overridePreviewSrc;
  const iframeSrc =
    armedVariant ||
    variantIssue ||
    selectedPastVariant?.previewError ||
    replayBooting
      ? 'about:blank'
      : (gatedOverridePreviewSrc ??
        (!isUpstreamReady
          ? 'about:blank'
          : `${previewOrigin}${devServerPath}`));

  const showOverlay =
    Boolean(armedVariant) ||
    Boolean(variantIssue) ||
    (!isUpstreamReady && initialProbeComplete);
  let overlayLayer: ReactNode = null;
  if (selectedPastVariant?.previewError) {
    overlayLayer = (
      <StatusSurface
        fill="overlay"
        size="sm"
        state="preview_replay_failed"
        role="alert"
        tone="error"
        title="Rivet couldn’t preview this direction"
        description="Select the direction again to retry."
      >
        <p className="text-muted-foreground text-xs leading-relaxed break-words">
          {selectedPastVariant.previewError}
        </p>
      </StatusSurface>
    );
  } else if (replayBooting) {
    overlayLayer = (
      <LoadingSurface
        fill="overlay"
        loader="coalesce"
        trackGlobalLoaderCount={false}
        state="preview_replay_boot"
      />
    );
  } else if (armedVariant) {
    overlayLayer = (
      <LoadingSurface
        fill="overlay"
        loader="coalesce"
        trackGlobalLoaderCount={false}
        state="variant_building"
      >
        <span className="sr-only">Building your direction</span>
      </LoadingSurface>
    );
  } else if (variantIssue) {
    const retryTarget =
      variantsSnapshot.active &&
      selectedVariant &&
      variantIssue.state === 'preview_unavailable' &&
      selectedVariant.previewUnavailable?.reason !== 'missing_static_entry'
        ? {
            sessionId: variantsSnapshot.sessionId,
            variantId: selectedVariant.workItemId,
          }
        : undefined;
    overlayLayer = (
      <VariantIssueSurface
        key={selectedVariant?.workItemId}
        issue={variantIssue}
        retryTarget={retryTarget}
      />
    );
  } else if (showOverlay) {
    overlayLayer = showVariantsPlaceholder ? (
      <EmptyState
        fill="overlay"
        state="preview_no_selection"
        title="Nothing to preview yet"
        description="Pick a direction from the panel."
      />
    ) : (
      <ErrorState
        fill="overlay"
        state="preview_offline"
        title="Preview isn't connected"
        description="Rivet lost connection to your project."
        actions={[{ label: 'Reload', onClick: () => window.location.reload() }]}
      />
    );
  }

  return (
    <div className="relative flex h-full min-h-0 w-full flex-col">
      <div className="relative min-h-0 flex-1">
        {overlayLayer}
        <RetainedPreviewSurface
          key={projectPath}
          target={previewTarget}
          src={iframeSrc}
          framework={framework}
          remountKey={iframeRemountKey}
        />
      </div>
    </div>
  );
};

export default IframePreview;
