'use client';

import {
  useRef,
  useState,
  useCallback,
  useEffect,
  type Dispatch,
  type RefObject,
  type SetStateAction,
} from 'react';

export interface ItemRect {
  top: number;
  height: number;
  left: number;
  width: number;
}

interface UseProximityHoverOptions {
  axis?: 'x' | 'y';
  /** Maximum distance (px) from an item's nearest EDGE at which the overlay
   *  still snaps to it. Cursor positions farther than this from every item
   *  highlight nothing. Default Infinity preserves the classic behavior
   *  (always snap to the nearest item); pass roughly half the list's
   *  inter-item gap to keep gap-crossing fluid while stopping the overlay
   *  from jumping across section/folder chrome the cursor isn't actually
   *  near. */
  snapTolerancePx?: number;
}

interface UseProximityHoverReturn {
  activeIndex: number | null;
  setActiveIndex: Dispatch<SetStateAction<number | null>>;
  itemRects: ItemRect[];
  sessionRef: RefObject<number>;
  handlers: {
    onMouseMove: (e: React.MouseEvent) => void;
    onMouseEnter: () => void;
    onMouseLeave: () => void;
  };
  registerItem: (index: number, element: HTMLElement | null) => void;
  measureItems: () => void;
}

/** Elements carrying this attribute (or inside one) are hover dead zones:
 *  while the cursor is over them the overlay hides instead of
 *  proximity-snapping to the nearest item. */
export const PROXIMITY_DEAD_ZONE_ATTR = 'data-hover-dead-zone';

export function useProximityHover<T extends HTMLElement>(
  containerRef: RefObject<T | null>,
  options: UseProximityHoverOptions = {},
): UseProximityHoverReturn {
  const { axis = 'y', snapTolerancePx = Infinity } = options;
  const itemsRef = useRef(new Map<number, HTMLElement>());
  const [activeIndex, setActiveIndex] = useState<number | null>(null);
  const [itemRects, setItemRects] = useState<ItemRect[]>([]);
  const itemRectsRef = useRef<ItemRect[]>([]);
  const sessionRef = useRef(0);
  const rafIdRef = useRef<number | null>(null);
  const remeasureRafIdRef = useRef<number | null>(null);

  const collectRects = useCallback((): ItemRect[] => {
    const rects: ItemRect[] = [];
    itemsRef.current.forEach((element, index) => {
      // Use offset* instead of getBoundingClientRect so measurements are
      // unaffected by CSS transforms (e.g. scaleY animation on the parent
      // motion.div). offsetTop/offsetLeft are layout values relative to the
      // offsetParent (the scroll container), matching the coordinate space
      // used by `position: absolute` children.
      rects[index] = {
        top: element.offsetTop,
        height: element.offsetHeight,
        left: element.offsetLeft,
        width: element.offsetWidth,
      };
    });
    return rects;
  }, []);

  const measureItems = useCallback(() => {
    const container = containerRef.current;
    if (!container) return;
    const rects = collectRects();
    itemRectsRef.current = rects;
    setItemRects(rects);
  }, [containerRef, collectRects]);

  const registerItem = useCallback(
    (index: number, element: HTMLElement | null) => {
      if (element) {
        itemsRef.current.set(index, element);
      } else {
        itemsRef.current.delete(index);
      }
      // Coalesce rapid register/unregister calls (e.g. when an AnimatePresence
      // remounts a list of rows) into a single remeasure on the next frame,
      // so consumers don't have to manually call measureItems after the
      // container's children swap.
      if (remeasureRafIdRef.current !== null) {
        cancelAnimationFrame(remeasureRafIdRef.current);
      }
      remeasureRafIdRef.current = requestAnimationFrame(() => {
        remeasureRafIdRef.current = null;
        measureItems();
      });
    },
    [measureItems],
  );

  const handleMouseMove = useCallback(
    (e: React.MouseEvent) => {
      const mouseX = e.clientX;
      const mouseY = e.clientY;
      // Dead zones (e.g. folder headers) are their own interactive surfaces:
      // while the cursor is over one, hide the overlay entirely rather than
      // proximity-snapping to the nearest item. The event target already
      // reflects the browser's hit-testing, so no geometry bookkeeping needed.
      const overDeadZone =
        e.target instanceof Element &&
        e.target.closest(`[${PROXIMITY_DEAD_ZONE_ATTR}]`) !== null;

      if (rafIdRef.current !== null) {
        cancelAnimationFrame(rafIdRef.current);
      }

      rafIdRef.current = requestAnimationFrame(() => {
        rafIdRef.current = null;
        const container = containerRef.current;
        if (!container) return;

        if (overDeadZone) {
          setActiveIndex(null);
          return;
        }

        // Re-measure on every (rAF-throttled) move instead of trusting the
        // registration-time snapshot: folds/expands animate row positions,
        // and pin/reorder drops move rows, all while the cursor is already
        // inside the container — mouseenter never refires, so a cached
        // measurement would hit-test against stale geometry and highlight
        // the wrong row. Reading offset* for a few dozen rows is cheap; the
        // state (which re-renders the consumer) only commits when the
        // geometry actually changed.
        const fresh = collectRects();
        const prev = itemRectsRef.current;
        const changed =
          fresh.length !== prev.length ||
          fresh.some((r, i) => {
            const p = prev[i];
            return (
              !p ||
              !r ||
              r.top !== p.top ||
              r.height !== p.height ||
              r.left !== p.left ||
              r.width !== p.width
            );
          });
        if (changed) {
          itemRectsRef.current = fresh;
          setItemRects(fresh);
        }

        const containerRect = container.getBoundingClientRect();
        const mousePos = axis === 'x' ? mouseX : mouseY;

        let closestIndex: number | null = null;
        let closestDistance = Infinity;
        let containingIndex: number | null = null;

        const rects = itemRectsRef.current;
        // Convert content-relative rects to viewport coords using live scroll
        const scrollOffset =
          axis === 'x' ? container.scrollLeft : container.scrollTop;
        const borderOffset =
          axis === 'x' ? container.clientLeft : container.clientTop;
        const containerEdge =
          axis === 'x' ? containerRect.left : containerRect.top;
        // Item rects are layout values (offset*); the container's bounding rect
        // reflects any cumulative ancestor transform: scale. Compute the scale
        // factor so we can map layout coords into the same visual viewport
        // space the mouse cursor lives in.
        const layoutSize =
          axis === 'x' ? container.offsetWidth : container.offsetHeight;
        const visualSize =
          axis === 'x' ? containerRect.width : containerRect.height;
        const scale = layoutSize > 0 ? visualSize / layoutSize : 1;

        for (let index = 0; index < rects.length; index++) {
          const r = rects[index];
          if (!r) continue;

          const contentPos = axis === 'x' ? r.left : r.top;
          const itemStart =
            containerEdge + (borderOffset + contentPos - scrollOffset) * scale;
          const itemSize = (axis === 'x' ? r.width : r.height) * scale;
          const itemEnd = itemStart + itemSize;

          if (mousePos >= itemStart && mousePos <= itemEnd) {
            containingIndex = index;
          }

          // Distance to the item's nearest EDGE (0 when contained), not its
          // center: a tall item's center can be far from a cursor sitting
          // right at its boundary, and the snap tolerance below must measure
          // "how far past the item is the cursor", not item height.
          let distance = 0;
          if (mousePos < itemStart) distance = itemStart - mousePos;
          else if (mousePos > itemEnd) distance = mousePos - itemEnd;

          if (distance < closestDistance) {
            closestDistance = distance;
            closestIndex = index;
          }
        }

        setActiveIndex(
          containingIndex ??
            (closestDistance <= snapTolerancePx ? closestIndex : null),
        );
      });
    },
    [axis, containerRef, snapTolerancePx, collectRects],
  );

  const handleMouseEnter = useCallback(() => {
    sessionRef.current += 1;
    // Measure on enter so the overlay/rects are fresh for this hover session
    // without consumers needing a separate measuring effect — covers rows that
    // changed (filter/reorder) since the last registration-driven remeasure.
    measureItems();
  }, [measureItems]);

  const handleMouseLeave = useCallback(() => {
    if (rafIdRef.current !== null) {
      cancelAnimationFrame(rafIdRef.current);
      rafIdRef.current = null;
    }
    setActiveIndex(null);
  }, []);

  // Clean up rAF on unmount
  useEffect(() => {
    return () => {
      if (rafIdRef.current !== null) {
        cancelAnimationFrame(rafIdRef.current);
      }
      if (remeasureRafIdRef.current !== null) {
        cancelAnimationFrame(remeasureRafIdRef.current);
      }
    };
  }, []);

  return {
    activeIndex,
    setActiveIndex,
    itemRects,
    sessionRef,
    handlers: {
      onMouseMove: handleMouseMove,
      onMouseEnter: handleMouseEnter,
      onMouseLeave: handleMouseLeave,
    },
    registerItem,
    measureItems,
  };
}

/**
 * Hook for child items to register themselves with the proximity hover system.
 * Call in useEffect with the item's ref and index.
 */
export function useRegisterProximityItem(
  registerItem: (index: number, element: HTMLElement | null) => void,
  index: number,
  ref: RefObject<HTMLElement | null>,
) {
  useEffect(() => {
    registerItem(index, ref.current);
    return () => registerItem(index, null);
  }, [index, registerItem, ref]);
}
