import { fetchLocalApi } from '@/utils/localApi';
import { toast } from 'sonner';
import { SidebarSimple } from '@phosphor-icons/react';
import { useAtomValue } from 'jotai';
import { usePostHog } from 'posthog-js/react';
import { CLOSE_RIVET_LABEL } from '@/constants/rivetPanel';
import { panelTitleAtom, projectPathAtom, mcpEditorAtom } from '@/store/atoms';
import { withLaunchRuntime } from '@rivet/core/utils/launchRuntime';
import { readToggleRivetShortcut } from '@/utils/toggleRivetShortcut';
import {
  readLibraryOrigin,
  SHOW_PROJECTS_MESSAGE,
} from '@/library/workspaceNavigation';
import { LibraryViewLaunchResponseSchema } from '@rivet/core/types/api-responses';
import Button from '@/components/Button';
import Breadcrumb from '@/components/Breadcrumb';
import Tooltip from './Tooltip';

type RivetPanelHeaderProps = {
  onUndo?: (
    showToast: (
      type: 'success' | 'error' | 'info',
      title: string,
      description?: string,
    ) => void,
  ) => Promise<boolean>;
  isUndoing?: boolean;
  onClose?: () => void;
  libraryOrigin?: string | null;
};

const RivetPanelHeader = ({
  onClose,
  libraryOrigin,
}: RivetPanelHeaderProps) => {
  const posthog = usePostHog();
  const title = useAtomValue(panelTitleAtom);
  const projectPath = useAtomValue(projectPathAtom);
  const callerAgent = useAtomValue(mcpEditorAtom);
  const embeddedOrigin = readLibraryOrigin(window.location.search);
  const isEmbedded = window.parent !== window && embeddedOrigin !== null;
  const projectName =
    projectPath?.split(/[\\/]/).filter(Boolean).pop() ?? 'Project';

  if (!onClose) {
    return null;
  }

  let heading = title ? (
    <span
      className="text-foreground min-w-0 truncate text-sm font-medium"
      title={title}
    >
      {title}
    </span>
  ) : (
    <span />
  );
  if (isEmbedded || libraryOrigin) {
    const showProjects = async () => {
      if (isEmbedded && embeddedOrigin) {
        window.parent.postMessage(SHOW_PROJECTS_MESSAGE, embeddedOrigin);
        return;
      }
      try {
        const response = await fetchLocalApi('/api/library/browser-launches', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ view: 'projects' }),
        });
        if (!response.ok)
          throw new Error('The project library could not be opened.');
        const { url } = LibraryViewLaunchResponseSchema.parse(
          await response.json(),
        );
        window.location.assign(withLaunchRuntime(url, callerAgent));
      } catch {
        toast.error('Could not open the project library. Please try again.');
        return;
      }
      posthog?.capture('library_view_changed', {
        view: 'projects',
      });
    };
    heading = (
      <Breadcrumb
        label="Project breadcrumb"
        steps={[{ label: 'Projects', onSelect: showProjects }]}
        current={projectName}
        isPrivate
        className="min-w-0 flex-1"
      />
    );
  }

  const toggleShortcut = readToggleRivetShortcut();

  return (
    <div className="border-separator bg-card z-10 flex flex-shrink-0 items-center justify-between gap-2 border-b px-2.5 py-2.5">
      {heading}
      <Tooltip label={CLOSE_RIVET_LABEL} side="bottom">
        <Button
          variant="ghost"
          size="icon-compact"
          onClick={onClose}
          aria-label={CLOSE_RIVET_LABEL}
          aria-keyshortcuts={toggleShortcut.ariaKeyShortcuts}
          className="shrink-0"
        >
          <SidebarSimple weight="bold" />
        </Button>
      </Tooltip>
    </div>
  );
};

export default RivetPanelHeader;
