import { z } from 'zod';

export const SOURCE_FAMILIES = ['context', 'references'] as const;
export type SourceFamily = (typeof SOURCE_FAMILIES)[number];

export const SOURCE_SYNC_MODES = ['daily', 'manual', 'off'] as const;
export const SourceSyncModeSchema = z.enum(SOURCE_SYNC_MODES);
export type SourceSyncMode = z.infer<typeof SourceSyncModeSchema>;

export type SourceSyncTrigger = 'automatic' | 'explicit';

export const isSourceSyncAllowed = ({
  syncMode,
  trigger,
}: {
  syncMode: SourceSyncMode;
  trigger: SourceSyncTrigger;
}): boolean =>
  trigger === 'automatic' ? syncMode === 'daily' : syncMode !== 'off';

export class SourceSyncOffError extends Error {
  readonly code = 'source_sync_off';
  constructor() {
    super(
      'This source is turned off. Change its sync mode to Daily or Manual before refreshing it.',
    );
    this.name = 'SourceSyncOffError';
  }
}

export class SourceNotFoundError extends Error {
  readonly code = 'source_not_found';
  constructor() {
    super(
      'No imported reference source has this ID. Check the ID, or import the source first.',
    );
    this.name = 'SourceNotFoundError';
  }
}

export const assertExplicitSourceSync = (syncMode: SourceSyncMode): void => {
  if (!isSourceSyncAllowed({ syncMode, trigger: 'explicit' }))
    throw new SourceSyncOffError();
};

export const SOURCE_SYNC_STALE_MS = 24 * 60 * 60 * 1000;
export const SOURCE_SYNC_JITTER_MS = 10 * 60 * 1000;
export const LOCAL_SOURCE_POLL_MS = 60_000;

export interface SourceSyncCheck {
  family: SourceFamily;
  sourceId: string;
  dueAt: number;
}

export interface SourceSyncChecks {
  accountId: string;
  checks: readonly SourceSyncCheck[];
}

export const SourceFamilySchema = z.enum(SOURCE_FAMILIES);

export const SourceRefreshRequestSchema = z.union([
  z
    .object({ family: SourceFamilySchema, sourceId: z.string().min(1) })
    .strict(),
  z
    .object({ all: z.literal(true), family: SourceFamilySchema.optional() })
    .strict(),
]);
export type SourceRefreshRequest = z.infer<typeof SourceRefreshRequestSchema>;

export type SourceRefreshStatus =
  'queued' | 'skipped_off' | 'skipped_in_progress' | 'profile_disabled';

export interface SourceRefreshResult {
  family: SourceFamily;
  sourceId: string;
  status: SourceRefreshStatus;
  jobId?: string;
}

export interface SourceSyncState {
  family: SourceFamily;
  sourceId: string;
  title: string;
  syncMode: SourceSyncMode;
  lastSyncedAt: string | null;
  checkedAt: string | null;
  lastError: string | null;
  isDue: boolean;
  isInProgress: boolean;
  needsReconnect: boolean;
}
