'use client';

import { forwardRef, type ButtonHTMLAttributes } from 'react';
import type { Icon } from '@phosphor-icons/react';
import { cva, type VariantProps } from 'class-variance-authority';
import { cn } from '@/lib/utils';

const buttonVariants = cva(
  [
    'group/button relative isolate inline-flex cursor-pointer items-center justify-center focus-visible:outline-hidden',
    'transition-colors duration-80 motion-reduce:transition-none',
    'disabled:pointer-events-none disabled:opacity-50',
  ],
  {
    variants: {
      variant: {
        primary: 'text-background',
        secondary: 'text-foreground',
        tertiary: 'text-foreground',
        ghost:
          'text-muted-foreground hover:text-foreground focus-visible:text-foreground aria-expanded:text-foreground aria-pressed:text-foreground',
      },
      size: {
        default: 'h-9 gap-1.5 px-4 text-[13px]',
        compact: 'h-7 gap-1 px-3 text-[12px]',
        icon: 'h-9 w-9 p-0 [&_svg]:h-4 [&_svg]:w-4',
        'icon-compact': 'h-7 w-7 p-0 [&_svg]:h-3.5 [&_svg]:w-3.5',
      },
      iconLeft: { true: '' },
      iconRight: { true: '' },
    },
    compoundVariants: [
      { size: 'compact', iconLeft: true, className: 'pl-2' },
      { size: 'default', iconLeft: true, className: 'pl-3' },
      { size: 'compact', iconRight: true, className: 'pr-2' },
      { size: 'default', iconRight: true, className: 'pr-3' },
    ],
    defaultVariants: { variant: 'secondary', size: 'default' },
  },
);

interface ButtonProps
  extends
    ButtonHTMLAttributes<HTMLButtonElement>,
    Omit<VariantProps<typeof buttonVariants>, 'iconLeft' | 'iconRight'> {
  isLoading?: boolean;
  leadingIcon?: Icon;
  trailingIcon?: Icon;
}

const ICON_SIZE = { default: 16, compact: 14 };

/* The inset surface and matching shadow fill the button's bounds at rest.
   Pressing removes the shadow spread to inset the surface by one pixel. */
const backgroundVariants = {
  primary:
    '[--btn-bg:var(--foreground)] group-hover/button:[--btn-bg:color-mix(in_oklab,var(--foreground)_90%,var(--background))] group-focus-visible/button:[--btn-bg:color-mix(in_oklab,var(--foreground)_80%,var(--background))] group-active/button:[--btn-bg:color-mix(in_oklab,var(--foreground)_80%,var(--background))] bg-[var(--btn-bg)] shadow-[0_0_0_1px_var(--btn-bg)] group-active/button:shadow-[0_0_0_0px_var(--btn-bg)]',
  secondary:
    '[--btn-bg:var(--accent)] group-hover/button:[--btn-bg:color-mix(in_oklab,var(--accent)_80%,var(--background))] group-focus-visible/button:[--btn-bg:var(--selected)] group-active/button:[--btn-bg:var(--accent)] bg-[var(--btn-bg)] shadow-[0_0_0_1px_var(--btn-bg)] group-active/button:shadow-[0_0_0_0px_var(--btn-bg)]',
  tertiary:
    'bg-transparent shadow-[0_0_0_1px_var(--border),inset_0_0_0_0px_var(--border)] group-hover/button:bg-hover group-focus-visible/button:bg-active group-active/button:bg-active group-active/button:shadow-[0_0_0_0px_var(--border),inset_0_0_0_1px_var(--border)]',
  ghost:
    'bg-transparent shadow-[0_0_0_1px_transparent] group-hover/button:bg-hover group-hover/button:shadow-[0_0_0_1px_var(--hover)] group-focus-visible/button:bg-active group-focus-visible/button:shadow-[0_0_0_1px_var(--active)] group-active/button:bg-active group-active/button:shadow-[0_0_0_0px_var(--active)] group-aria-expanded/button:bg-active group-aria-expanded/button:shadow-[0_0_0_0px_var(--active)] group-aria-pressed/button:bg-active group-aria-pressed/button:shadow-[0_0_0_0px_var(--active)] group-aria-expanded/button:group-focus-visible/button:bg-selected group-aria-pressed/button:group-focus-visible/button:bg-selected',
};

/**
 * Fluid Functionalism's button surface, variants, size ladder, and press treatment.
 * Source: https://www.fluidfunctionalism.com/r/button.json
 * Uses Rivet's shape and color tokens with native button semantics and reduced motion.
 */
const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className,
      variant,
      size,
      isLoading = false,
      leadingIcon: LeadingIcon,
      trailingIcon: TrailingIcon,
      disabled,
      children,
      type = 'button',
      ...props
    },
    ref,
  ) => {
    const resolvedVariant = variant ?? 'secondary';
    const resolvedSize = size ?? 'default';
    const isIconOnly =
      resolvedSize === 'icon' || resolvedSize === 'icon-compact';
    const isCompact =
      resolvedSize === 'compact' || resolvedSize === 'icon-compact';
    const iconSize = isCompact ? ICON_SIZE.compact : ICON_SIZE.default;

    return (
      <button
        {...props}
        ref={ref}
        type={type}
        disabled={disabled || isLoading}
        aria-busy={isLoading || props['aria-busy']}
        className={cn(
          buttonVariants({
            variant: resolvedVariant,
            size: resolvedSize,
            iconLeft: !isIconOnly && Boolean(LeadingIcon),
            iconRight: !isIconOnly && Boolean(TrailingIcon),
          }),
          'rounded-lg',
          className,
        )}
      >
        <span
          aria-hidden
          className={cn(
            'absolute inset-px rounded-[inherit] transition-[box-shadow,background-color] [transition-duration:180ms,80ms] [transition-timing-function:cubic-bezier(0.23,1,0.32,1),ease] group-active/button:[transition-duration:80ms,80ms] motion-reduce:transition-none',
            backgroundVariants[resolvedVariant],
          )}
        />
        <span className="relative inline-flex items-center justify-center gap-[inherit]">
          <span
            className={cn(
              'inline-flex items-center justify-center gap-[inherit]',
              isLoading && 'opacity-0',
            )}
          >
            {LeadingIcon && !isIconOnly ? (
              <LeadingIcon size={iconSize} weight="regular" aria-hidden />
            ) : null}
            <span className="[text-box:trim-both_cap_alphabetic]">
              {children}
            </span>
            {TrailingIcon && !isIconOnly ? (
              <TrailingIcon size={iconSize} weight="regular" aria-hidden />
            ) : null}
          </span>
          {isLoading ? (
            <span
              aria-hidden
              className="absolute inset-0 flex items-center justify-center"
            >
              <svg
                className={isCompact ? 'h-7 w-7' : 'h-9 w-9'}
                viewBox="0 0 24 24"
                fill="none"
              >
                <path
                  d="M 12 12 C 14 8.5 19 8.5 19 12 C 19 15.5 14 15.5 12 12 C 10 8.5 5 8.5 5 12 C 5 15.5 10 15.5 12 12 Z"
                  stroke="currentColor"
                  strokeWidth="1.125"
                  strokeLinecap="round"
                  pathLength="100"
                  className="motion-safe:animate-[spinner-move_2s_linear_infinite,spinner-dash_4s_ease-in-out_infinite]"
                  style={{ strokeDasharray: '15 85' }}
                />
              </svg>
            </span>
          ) : null}
        </span>
      </button>
    );
  },
);
Button.displayName = 'Button';

export { Button, buttonVariants };
export type { ButtonProps };
