const RIVET_PATH_PREFIX = '/rivet/';

export const extractPreviewPathFromLocation = (
  pathname: string,
): string | null => {
  if (!pathname.startsWith(RIVET_PATH_PREFIX)) {
    return null;
  }

  const nested = pathname.slice(RIVET_PATH_PREFIX.length);
  if (!nested || nested === '/') {
    return null;
  }

  return `/${nested}`;
};
