import posthog from 'posthog-js';
import type { Account } from '@rivet/core/types/account';

type EditorTelemetryMode = 'full' | 'metrics' | 'off';

export type TelemetryAccount = Pick<Account, 'userId' | 'email'>;

let mode: EditorTelemetryMode = 'off';

export const setEditorTelemetryMode = (value: EditorTelemetryMode): void => {
  mode = value;
};

export const isTelemetryIdentityEnabled = (): boolean => mode === 'full';

export const identifyTelemetryAccount = ({
  userId,
  email,
}: TelemetryAccount): void => {
  if (!isTelemetryIdentityEnabled()) return;
  if (userId) {
    posthog.identify(userId, email ? { email } : {});
    if (email) posthog.alias(email, userId);
  } else if (email) {
    posthog.identify(email, { email });
  }
};
