import { useCallback, useState, type RefObject } from 'react';

export interface ReorderDragged {
  container: string;
  key: string;
}

export interface ReorderDropTarget {
  container: string;
  index: number;
  top: number;
}

export const useReorderDrop = (args: {
  containerRef: RefObject<HTMLDivElement | null>;
  dragged: ReorderDragged | null;
  yieldToSelector?: string;
  restrictToSelector?: string;
  onReorder: (containerId: string, orderedKeys: string[]) => void;
}): {
  dropTarget: ReorderDropTarget | null;
  onPointerMove: (event: React.PointerEvent<HTMLElement>) => void;
  onPointerUp: () => void;
} => {
  const {
    containerRef,
    dragged,
    yieldToSelector,
    restrictToSelector,
    onReorder,
  } = args;
  const [dropTarget, setDropTarget] = useState<ReorderDropTarget | null>(null);

  const itemsOf = useCallback(
    (container: string): HTMLElement[] => {
      const root = containerRef.current;
      if (!root) return [];
      return Array.from(
        root.querySelectorAll<HTMLElement>(
          `[data-reorder-container="${CSS.escape(container)}"]`,
        ),
      );
    },
    [containerRef],
  );

  const onPointerMove = useCallback(
    (event: React.PointerEvent<HTMLElement>) => {
      if (!dragged) {
        if (dropTarget) setDropTarget(null);
        return;
      }
      const root = containerRef.current;
      if (!root) return;
      if (yieldToSelector) {
        const zone = root.querySelector(yieldToSelector);
        if (zone) {
          const rect = zone.getBoundingClientRect();
          if (event.clientY >= rect.top && event.clientY <= rect.bottom) {
            if (dropTarget) setDropTarget(null);
            return;
          }
        }
      }
      if (restrictToSelector) {
        const zone = root.querySelector(restrictToSelector);
        const rect = zone?.getBoundingClientRect();
        if (!rect || event.clientY < rect.top || event.clientY > rect.bottom) {
          if (dropTarget) setDropTarget(null);
          return;
        }
      }
      const items = itemsOf(dragged.container);
      if (items.length === 0) {
        if (dropTarget) setDropTarget(null);
        return;
      }
      const rootTop = root.getBoundingClientRect().top;
      let index = items.length;
      for (let i = 0; i < items.length; i++) {
        const rect = items[i].getBoundingClientRect();
        if (event.clientY < rect.top + rect.height / 2) {
          index = i;
          break;
        }
      }
      let top: number;
      if (index === 0) {
        top = items[0].getBoundingClientRect().top - rootTop - 1;
      } else if (index === items.length) {
        top = items[items.length - 1].getBoundingClientRect().bottom - rootTop;
      } else {
        top =
          (items[index - 1].getBoundingClientRect().bottom +
            items[index].getBoundingClientRect().top) /
            2 -
          rootTop;
      }
      if (
        !dropTarget ||
        dropTarget.index !== index ||
        dropTarget.container !== dragged.container
      ) {
        setDropTarget({ container: dragged.container, index, top });
      }
    },
    [
      containerRef,
      dragged,
      dropTarget,
      itemsOf,
      yieldToSelector,
      restrictToSelector,
    ],
  );

  const onPointerUp = useCallback(() => {
    if (!dragged || !dropTarget) return;
    setDropTarget(null);
    const keys = itemsOf(dropTarget.container)
      .map((item) => item.dataset.reorderKey)
      .filter((key): key is string => Boolean(key));
    const from = keys.indexOf(dragged.key);
    if (from === -1) return;
    keys.splice(from, 1);
    const insertAt =
      dropTarget.index > from ? dropTarget.index - 1 : dropTarget.index;
    keys.splice(insertAt, 0, dragged.key);
    onReorder(dropTarget.container, keys);
  }, [dragged, dropTarget, itemsOf, onReorder]);

  return { dropTarget, onPointerMove, onPointerUp };
};
