import { captureEditorToken } from '@/utils/editorSession';
import * as Sentry from '@sentry/react';
import posthog from 'posthog-js';
import { initializeTelemetry } from '@/utils/telemetry';
import { isTelemetryIdentityEnabled } from '@/utils/telemetryPolicy';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { MotionConfig } from 'motion/react';
import { PostHogErrorBoundary, PostHogProvider } from 'posthog-js/react';
import React, { lazy, Suspense } from 'react';
import { captureLibraryToken } from '@/library/api';
import { forwardPreviewShortcutKeys } from '@/utils/editorShortcutKeys';
import { readLibraryOrigin } from '@/library/workspaceNavigation';
import { startThemeSync } from '@/utils/themePreference';
import { fetchLocalApi } from '@/utils/localApi';
import ReactDOM from 'react-dom/client';
import App from './App.tsx';
import './index.css';

captureEditorToken();

const LibraryEntry = lazy(() => import('@/library/LibraryEntry'));
const isLibrary = window.location.pathname.startsWith('/rivet/library');
if (!isLibrary) forwardPreviewShortcutKeys();

const queryClient = new QueryClient();

const ErrorFallback = () => (
  <div
    style={{
      display: 'flex',
      height: '100vh',
      alignItems: 'center',
      justifyContent: 'center',
    }}
  >
    <p style={{ fontSize: '14px', color: 'var(--foreground)' }}>
      Something went wrong. Please reload the page.
    </p>
  </div>
);
const SENTRY_DSN = import.meta.env.VITE_SENTRY_DSN as string | undefined;
const root = document.getElementById('root');
if (!root) throw new Error('Rivet root element is missing');

const render = () =>
  ReactDOM.createRoot(root).render(
    <React.StrictMode>
      <MotionConfig reducedMotion="user">
        <PostHogProvider client={posthog}>
          <PostHogErrorBoundary fallback={<ErrorFallback />}>
            <QueryClientProvider client={queryClient}>
              {isLibrary ? (
                <Suspense fallback={<div className="bg-background h-screen" />}>
                  <LibraryEntry />
                </Suspense>
              ) : (
                <App />
              )}
            </QueryClientProvider>
          </PostHogErrorBoundary>
        </PostHogProvider>
      </MotionConfig>
    </React.StrictMode>,
  );

const start = async (): Promise<void> => {
  if (isLibrary) await captureLibraryToken();
  startThemeSync({
    libraryOrigin: isLibrary ? null : readLibraryOrigin(window.location.search),
    fetchApi: fetchLocalApi,
  });
  await initializeTelemetry();
  if (SENTRY_DSN && isTelemetryIdentityEnabled()) {
    Sentry.init({ dsn: SENTRY_DSN, environment: import.meta.env.MODE });
  }
  render();
};
void start();
