import { useQuery } from '@tanstack/react-query';
import type { Account } from '@rivet/core/types/account';
import { AccountResponseSchema } from '@rivet/core/types/api-responses';
import { fetchLocalApi } from '@/utils/localApi';
import { queryKeys } from '@/utils/queryKeys';
import { fetchRivetConfig, type RivetConfig } from '@/utils/rivetConfig';

const ACCOUNT_REFRESH_MS = 5_000;

const fetchLibraryAccount = async ({
  signal,
}: {
  signal: AbortSignal;
}): Promise<Account> => {
  const response = await fetchLocalApi('/api/account', { signal });
  if (!response.ok) throw new Error('Could not load your account.');
  return AccountResponseSchema.parse(await response.json());
};

const accountFromConfig = (config: RivetConfig): Account => ({
  isAuthenticated: config.agentModeAvailable,
  name: config.name,
  email: config.email,
  userId: config.userId,
});

const useLibraryAccount = (isEnabled: boolean) =>
  useQuery({
    queryKey: queryKeys.account,
    queryFn: fetchLibraryAccount,
    enabled: isEnabled,
    refetchInterval: ACCOUNT_REFRESH_MS,
    retry: false,
  });

const useEditorAccount = (isEnabled: boolean) =>
  useQuery({
    queryKey: queryKeys.rivetConfig,
    queryFn: fetchRivetConfig,
    select: accountFromConfig,
    enabled: isEnabled,
    refetchInterval: ACCOUNT_REFRESH_MS,
    retry: false,
  });

export const useAccount = () => {
  const isLibrary = window.location.pathname.startsWith('/rivet/library');
  const libraryAccount = useLibraryAccount(isLibrary);
  const editorAccount = useEditorAccount(!isLibrary);
  return isLibrary ? libraryAccount : editorAccount;
};
