import { useCallback } from 'react';
import { keepPreviousData, useQuery } from '@tanstack/react-query';
import type { VariantHistoryRow } from '@rivet/core/types/variant-history';
import { useImmediateQueryData } from '@/hooks/useImmediateQueryData';
import { useLatestRef } from '@/hooks/useLatestRef';
import { fetchLocalApi } from '@/utils/localApi';
import { queryKeys } from '@/utils/queryKeys';
import { createLogger } from '../utils/logger';

const log = createLogger('useVariantsHistory');

const EMPTY_HISTORY: VariantHistoryRow[] = [];

type VariantsHistoryBody = { variants?: VariantHistoryRow[] };

const areHistoryRowsEqual = (
  first: readonly VariantHistoryRow[],
  second: readonly VariantHistoryRow[],
): boolean =>
  first.length === second.length &&
  first.every((entry, index) => {
    const next = second[index];
    return (
      entry.sessionId === next.sessionId &&
      entry.variantId === next.variantId &&
      entry.requestId === next.requestId &&
      entry.label === next.label &&
      entry.brief === next.brief &&
      JSON.stringify(entry.references) === JSON.stringify(next.references) &&
      entry.runLabel === next.runLabel &&
      entry.createdAt === next.createdAt &&
      entry.serve?.kind === next.serve?.kind &&
      entry.hasTree === next.hasTree
    );
  });

export const useVariantsHistory = ({
  historyQuery,
  snapshotKey,
  isEnabled,
  isListed,
  onLoaded,
}: {
  historyQuery: string;
  snapshotKey: string;
  isEnabled: boolean;
  isListed: (entry: VariantHistoryRow) => boolean;
  onLoaded: (rows: VariantHistoryRow[]) => void;
}) => {
  const queryKey = queryKeys.variantsHistory.list({
    historyQuery,
    snapshotKey,
  });
  const onLoadedRef = useLatestRef(onLoaded);

  const query = useQuery({
    queryKey,
    queryFn: async ({ signal }): Promise<VariantHistoryRow[]> => {
      let rows: VariantHistoryRow[];
      try {
        const res = await fetchLocalApi(
          `/api/variants/history${historyQuery}`,
          { credentials: 'same-origin', signal },
        );
        if (!res.ok) return visibleRowsRef.current;
        const body = (await res.json()) as VariantsHistoryBody;
        rows = (body.variants ?? []).filter(isListed);
      } catch (err) {
        if (!signal.aborted) log.warn('Failed to load past variants', err);
        return visibleRowsRef.current;
      }
      if (signal.aborted) return visibleRowsRef.current;
      onLoadedRef.current(rows);
      const visibleRows = visibleRowsRef.current;
      return areHistoryRowsEqual(visibleRows, rows) ? visibleRows : rows;
    },
    enabled: isEnabled,
    placeholderData: keepPreviousData,
    gcTime: 0,
    retry: false,
    refetchOnWindowFocus: false,
    refetchOnReconnect: false,
    networkMode: 'always',
  });
  const { data, updateData } = useImmediateQueryData({
    queryKey,
    data: query.data,
  });
  const pastVariants = data ?? EMPTY_HISTORY;
  const visibleRowsRef = useLatestRef(pastVariants);

  const setPastVariants = useCallback(
    (update: (rows: VariantHistoryRow[]) => VariantHistoryRow[]) => {
      updateData((rows) => update(rows ?? EMPTY_HISTORY));
    },
    [updateData],
  );

  return { pastVariants, setPastVariants };
};
