import * as DialogPrimitive from '@radix-ui/react-dialog';
import { X } from '@phosphor-icons/react';
import {
  createContext,
  useContext,
  useState,
  type ComponentPropsWithoutRef,
  type FocusEvent,
  type ReactNode,
} from 'react';
import Button from '@/components/Button';
import { TooltipPortalContainer } from '@/components/ui/tooltip';
import { cn } from '@/lib/utils';

type DialogProps = ComponentPropsWithoutRef<typeof DialogPrimitive.Root>;

type DialogOpening = { isOpen: boolean; opener: Element | null };

type CenteredDialogSurface = 'editor' | 'library';

type DialogSurface = CenteredDialogSurface | 'librarySheet';

type DialogSize = 'sm' | 'md';

type DialogContentProps = ComponentPropsWithoutRef<
  typeof DialogPrimitive.Content
> &
  (
    | { surface?: CenteredDialogSurface; size?: DialogSize }
    | { surface: 'librarySheet'; size?: never }
  );

type DialogHeaderProps = {
  children: ReactNode;
  onClose: () => void;
  isCloseDisabled?: boolean;
};

const DIALOG_OVERLAY = 'bg-scrim fixed inset-0 z-max';

const CENTERED =
  'fixed top-1/2 left-1/2 z-max -translate-x-1/2 -translate-y-1/2 rounded-lg shadow-dialog';

const DIALOG_SURFACES: Record<DialogSurface, string> = {
  editor: `border-separator bg-background font-main ${CENTERED} border outline-none`,
  library: `bg-surface-2 text-foreground ${CENTERED} p-6 forced-colors:border`,
  librarySheet:
    'bg-background text-foreground shadow-dialog fixed inset-y-0 right-0 z-max flex w-full max-w-2xl flex-col border-l border-border outline-none',
};

const DIALOG_SIZES: Record<DialogSize, string> = {
  sm: 'w-[min(24rem,calc(100vw-2rem))]',
  md: 'w-[min(440px,calc(100vw-32px))]',
};

const DialogOpenerContext = createContext<Element | null>(null);

const FOCUS_TARGET_HISTORY_LIMIT = 4;

const focusTargetsLeavingDialogs: HTMLElement[] = [];

const focusedElement = () =>
  document.activeElement === document.body ? null : document.activeElement;

const Dialog = (props: DialogProps) => {
  const isOpen = props.open === true;
  const [opening, setOpening] = useState<DialogOpening>(() => ({
    isOpen,
    opener: isOpen ? focusedElement() : null,
  }));
  if (opening.isOpen !== isOpen) {
    setOpening({
      isOpen,
      opener: isOpen ? focusedElement() : opening.opener,
    });
  }
  return (
    <DialogOpenerContext.Provider value={opening.opener}>
      <DialogPrimitive.Root {...props} />
    </DialogOpenerContext.Provider>
  );
};

const DialogTrigger = DialogPrimitive.Trigger;
const DialogClose = DialogPrimitive.Close;
const DialogTitle = DialogPrimitive.Title;
const DialogDescription = DialogPrimitive.Description;

const DialogContent = ({
  surface = 'editor',
  size = 'md',
  className,
  children,
  onCloseAutoFocus,
  onOpenAutoFocus,
  onEscapeKeyDown,
  onBlur,
  ...props
}: DialogContentProps) => {
  const [contentElement, setContentElement] = useState<HTMLDivElement | null>(
    null,
  );
  const opener = useContext(DialogOpenerContext);
  const sizeClass = surface === 'librarySheet' ? null : DIALOG_SIZES[size];
  const returnFocus = (event: Event) => {
    onCloseAutoFocus?.(event);
    if (event.defaultPrevented) return;
    if (!(opener instanceof HTMLElement) || !opener.isConnected) return;
    event.preventDefault();
    opener.focus();
  };
  const rememberFocusLeavingDialog = (event: FocusEvent<HTMLDivElement>) => {
    onBlur?.(event);
    const target = event.relatedTarget;
    if (!(target instanceof HTMLElement)) return;
    if (event.currentTarget.contains(target)) return;
    focusTargetsLeavingDialogs.push(target);
    if (focusTargetsLeavingDialogs.length > FOCUS_TARGET_HISTORY_LIMIT)
      focusTargetsLeavingDialogs.shift();
  };
  const restoreFocusFromLowerDialog = (event: Event) => {
    onOpenAutoFocus?.(event);
    const container = event.currentTarget;
    if (event.defaultPrevented || !(container instanceof Element)) return;
    const target = [...focusTargetsLeavingDialogs]
      .reverse()
      .find(
        (candidate) => candidate.isConnected && container.contains(candidate),
      );
    if (!target) return;
    event.preventDefault();
    target.focus();
  };
  const ignoreEscapeFromHigherLayer = (event: KeyboardEvent) => {
    onEscapeKeyDown?.(event);
    const target = event.target;
    if (event.defaultPrevented || !(target instanceof Element)) return;
    if (!contentElement || target === target.ownerDocument.body) return;
    if (!contentElement.contains(target)) event.preventDefault();
  };
  return (
    <DialogPrimitive.Portal>
      <DialogPrimitive.Overlay className={DIALOG_OVERLAY} />
      <DialogPrimitive.Content
        {...props}
        onCloseAutoFocus={returnFocus}
        onOpenAutoFocus={restoreFocusFromLowerDialog}
        onEscapeKeyDown={ignoreEscapeFromHigherLayer}
        onBlur={rememberFocusLeavingDialog}
        ref={setContentElement}
        className={cn(DIALOG_SURFACES[surface], sizeClass, className)}
      >
        <TooltipPortalContainer value={contentElement}>
          {children}
        </TooltipPortalContainer>
      </DialogPrimitive.Content>
    </DialogPrimitive.Portal>
  );
};

const DialogHeader = ({
  children,
  onClose,
  isCloseDisabled = false,
}: DialogHeaderProps) => (
  <div className="border-separator bg-card flex items-center justify-between rounded-t-lg border-b px-4 py-2">
    <DialogPrimitive.Title className="text-foreground text-base font-medium">
      {children}
    </DialogPrimitive.Title>
    <Button
      onClick={onClose}
      disabled={isCloseDisabled}
      aria-label="Close"
      variant="ghost"
      size="icon-compact"
    >
      <X className="h-4 w-4" weight="bold" />
    </Button>
  </div>
);

export {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
};
