import { useMemo } from 'react';
import { useAtomValue } from 'jotai';
import posthog from 'posthog-js';
import { useServerConfig } from '@/hooks/useServerConfig';
import {
  agentVariantsSnapshotAtom,
  draggedVariantAtom,
  iframePreviewOverrideUrlAtom,
  variantSplitViewAtom,
  type AgentVariantsSnapshot,
  type VariantSplitSlot,
} from '@/store/atoms';
import type { Framework } from '@/types';
import CoalesceLoader from './CoalesceLoader';
import IframePreview from './IframePreview';
import { ErrorState } from './StatusSurface';
import SecondaryVariantIframe from './SecondaryVariantIframe';
import VariantDragGhost from './VariantDragGhost';
import VariantSplitDropZones from './VariantSplitDropZones';
import { resolveVariantPreviewUrl } from '@/utils/variantPreviewUrl';

type PreviewFrameProps = {
  isLoading?: boolean;
  isInteractionDisabled?: boolean;
};

const getStaticVariantUrl = (
  snapshot: AgentVariantsSnapshot,
  sessionId: string,
  variantId: string,
): string | null => {
  if (!snapshot.active || snapshot.sessionId !== sessionId) return null;
  const variant = snapshot.variants.find(
    (candidate) => candidate.workItemId === variantId,
  );
  if (variant?.preview?.kind !== 'static_artifact') return null;
  if (variant.previewRoutes?.length)
    return resolveVariantPreviewUrl({
      sessionId,
      variant,
      projectContext: snapshot.projectContext,
    });
  if (variant.refinement?.status !== 'succeeded') return variant.preview.url;
  const separator = variant.preview.url.includes('?') ? '&' : '?';
  return `${variant.preview.url}${separator}refinement=${encodeURIComponent(
    variant.refinement.workItemId,
  )}`;
};

const refreshSplitSlotUrl = (
  slot: VariantSplitSlot | undefined,
  snapshot: AgentVariantsSnapshot,
): VariantSplitSlot | undefined => {
  if (!slot) return undefined;
  const url = getStaticVariantUrl(snapshot, slot.sessionId, slot.variantId);
  if (!url || url === slot.url) return slot;
  return { ...slot, url };
};

const PreviewBootSkeleton = () => (
  <div
    data-testid="preview-boot-skeleton"
    role="status"
    aria-busy="true"
    aria-label="Loading preview"
    className="bg-background flex h-full min-h-0 w-full flex-1 flex-col p-3"
  >
    <div className="border-separator relative min-h-0 flex-1 overflow-hidden rounded-lg border">
      <CoalesceLoader trackGlobalLoaderCount={false} />
    </div>
  </div>
);

const PreviewFrame = ({
  isLoading = false,
  isInteractionDisabled = false,
}: PreviewFrameProps) => {
  const {
    config,
    retry: retryConfig,
    isLoading: isConfigLoading,
    error: configError,
  } = useServerConfig();

  if (isConfigLoading) {
    return <PreviewBootSkeleton />;
  }

  if (configError || !config) {
    return (
      <ErrorState
        fill="surface"
        size="sm"
        state="preview_config_error"
        title="Couldn't load preview"
        description="We couldn't load the preview configuration."
        actions={[
          {
            label: 'Retry',
            onClick: () => {
              posthog?.capture('preview_config_retry_clicked');
              retryConfig();
            },
          },
        ]}
      />
    );
  }

  return (
    <PreviewFrameInner
      isLoading={isLoading}
      isInteractionDisabled={isInteractionDisabled}
      framework={config.framework}
      userPort={config.userPort}
    />
  );
};

function PreviewFrameInner(props: {
  isLoading: boolean;
  isInteractionDisabled: boolean;
  framework: Framework;
  userPort: number;
}) {
  const split = useAtomValue(variantSplitViewAtom);
  const dragged = useAtomValue(draggedVariantAtom);
  const variantsSnapshot = useAtomValue(agentVariantsSnapshotAtom);
  const selectedStaticPreviewUrl = useAtomValue(iframePreviewOverrideUrlAtom);
  const leftSlot = split?.left;
  const rightSlot = split?.right;

  const fallbackVariantSlot = useMemo((): VariantSplitSlot | undefined => {
    if (!variantsSnapshot.active) return undefined;
    if (variantsSnapshot.projectContext.kind !== 'fresh') return undefined;
    const exactlyOneBound = Boolean(leftSlot) !== Boolean(rightSlot);
    if (!exactlyOneBound) return undefined;
    const boundId = (leftSlot ?? rightSlot)?.variantId;
    const staticCandidates = variantsSnapshot.variants.filter(
      (v) =>
        v.status === 'succeeded' &&
        v.preview?.kind === 'static_artifact' &&
        v.workItemId !== boundId,
    );
    const baseSelectedUrl = selectedStaticPreviewUrl?.replace(
      /[?&]refinement=[^&]*$/,
      '',
    );
    const selectedCandidate = staticCandidates.find(
      (v) =>
        v.preview?.kind === 'static_artifact' &&
        (v.preview.url === baseSelectedUrl ||
          resolveVariantPreviewUrl({
            sessionId: variantsSnapshot.sessionId,
            variant: v,
            projectContext: variantsSnapshot.projectContext,
          }) === selectedStaticPreviewUrl),
    );
    const candidate = selectedCandidate ?? staticCandidates[0];
    if (candidate?.preview?.kind !== 'static_artifact') return undefined;
    const url = getStaticVariantUrl(
      variantsSnapshot,
      variantsSnapshot.sessionId,
      candidate.workItemId,
    );
    if (!url) return undefined;
    return {
      sessionId: variantsSnapshot.sessionId,
      variantId: candidate.workItemId,
      label: candidate.label,
      url,
      source: 'live',
    };
  }, [variantsSnapshot, leftSlot, rightSlot, selectedStaticPreviewUrl]);

  const effLeft =
    refreshSplitSlotUrl(leftSlot, variantsSnapshot) ??
    (rightSlot ? fallbackVariantSlot : undefined);
  const effRight =
    refreshSplitSlotUrl(rightSlot, variantsSnapshot) ??
    (leftSlot ? fallbackVariantSlot : undefined);
  const leftIsFallback = !leftSlot && Boolean(effLeft);
  const rightIsFallback = !rightSlot && Boolean(effRight);
  const hasSplit = Boolean(effLeft || effRight);

  const primary = (
    <IframePreview
      isInteractionDisabled={props.isInteractionDisabled}
      framework={props.framework}
      userPort={props.userPort}
    />
  );
  return (
    <div className="relative flex h-full min-h-0 w-full flex-1 flex-col">
      <div
        className={`variant-preview-region relative flex h-full min-h-0 w-full flex-1 flex-col ${
          dragged ? 'is-dragging' : ''
        } ${hasSplit ? 'is-split' : ''}`}
      >
        <div className="variant-preview-row flex h-full min-h-0 w-full flex-1">
          {effLeft && (
            <SecondaryVariantIframe
              key={`left-${effLeft.sessionId}:${effLeft.variantId}:${effLeft.url}`}
              side="left"
              sessionId={effLeft.sessionId}
              variantId={effLeft.variantId}
              url={effLeft.url}
              label={effLeft.label}
              source={effLeft.source}
              isFallback={leftIsFallback}
            />
          )}
          <div
            className="variant-preview-primary flex h-full min-h-0 flex-1 flex-col"
            style={{ display: effLeft && effRight ? 'none' : undefined }}
            aria-hidden={Boolean(effLeft && effRight)}
          >
            {primary}
          </div>
          {effRight && (
            <SecondaryVariantIframe
              key={`right-${effRight.sessionId}:${effRight.variantId}:${effRight.url}`}
              side="right"
              sessionId={effRight.sessionId}
              variantId={effRight.variantId}
              url={effRight.url}
              label={effRight.label}
              source={effRight.source}
              isFallback={rightIsFallback}
            />
          )}
        </div>
        <div className="variant-preview-atmosphere" aria-hidden="true" />
        <VariantSplitDropZones />
        <VariantDragGhost />
      </div>
    </div>
  );
}

export default PreviewFrame;
