import {
  ChatCircle,
  SignIn,
  SignOut,
  Swatches,
  User,
} from '@phosphor-icons/react';
import { useId, useRef, useState } from 'react';
import { flushSync } from 'react-dom';
import { usePostHog } from 'posthog-js/react';
import { useAccount } from '@/hooks/useAccount';
import { useLogin } from '@/hooks/useLogin';
import { fetchLocalApi } from '@/utils/localApi';
import { clearLibrarySession } from '@/library/api';
import { toast } from 'sonner';
import { createLogger } from '../utils/logger';
import {
  Menu,
  MenuContent,
  MenuControl,
  MenuItem,
  MenuTrigger,
} from '@/components/Menu';
import Select, { type SelectOption } from '@/components/Select';
import { useThemePreference } from '@/hooks/useThemePreference';
import type { ThemePreference } from '@/utils/themeBootstrap';
import { setThemePreference } from '@/utils/themePreference';
import AuthorizationLinkNotice from './AuthorizationLinkNotice';
import ConnectorsModal from './ConnectorsModal';
import Skeleton from './Skeleton';
import SupportTicketModal from './SupportTicketModal';

const log = createLogger('ProfileAvatar');

type AccountDialog = 'connectors' | 'support';

const THEME_OPTIONS: SelectOption<ThemePreference>[] = [
  { value: 'system', label: 'Use system setting' },
  { value: 'light', label: 'Light' },
  { value: 'dark', label: 'Dark' },
];

export const deriveFirstName = (
  name: string | null,
  email: string | null,
): string => {
  const fromName = (name ?? '').trim();
  if (fromName) {
    return fromName.split(/\s+/).filter(Boolean)[0] ?? '';
  }

  const local = (email ?? '').split('@')[0] ?? '';
  const segment = local.split(/[._\-+]/).filter(Boolean)[0] ?? '';
  if (segment) {
    return segment[0].toUpperCase() + segment.slice(1);
  }

  return '';
};

export const deriveInitial = (
  name: string | null,
  email: string | null,
): string => deriveFirstName(name, email).charAt(0).toUpperCase();

const ProfileAvatar = ({
  className = '',
  side = 'bottom',
  align = 'end',
}: {
  className?: string;
  side?: 'top' | 'bottom';
  align?: 'start' | 'center' | 'end';
}) => {
  const account = useAccount();
  const name = account.data?.name ?? null;
  const email = account.data?.email ?? null;
  const isAuthenticated = account.data?.isAuthenticated === true;
  const posthog = usePostHog();
  const { startLogin, isStartingLogin, loginError, signInUrl } =
    useLogin('account_menu');
  const [isOpen, setIsOpen] = useState(false);
  const [openDialog, setOpenDialog] = useState<AccountDialog | null>(null);
  const pendingDialog = useRef<AccountDialog | null>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const [isLoggingOut, setIsLoggingOut] = useState(false);
  const theme = useThemePreference();
  const themeLabelId = useId();
  const initial = deriveInitial(name, email);
  if (account.isPending) {
    return (
      <span
        data-testid="profile-avatar-skeleton"
        aria-hidden="true"
        className={`flex shrink-0 items-center gap-2 ${className}`.trim()}
      >
        <Skeleton className="h-8 w-8 rounded-full" />
        <Skeleton className="h-3.5 w-16" />
      </span>
    );
  }

  const firstName = deriveFirstName(name, email);
  const displayName = name?.trim() || null;
  const displayEmail = email?.trim() || null;

  const handleLogout = async () => {
    setIsLoggingOut(true);
    try {
      const res = await fetchLocalApi('/api/auth/logout', {
        method: 'POST',
        credentials: 'same-origin',
      });
      if (!res.ok) {
        throw new Error(`Logout failed: ${res.status}`);
      }
      if (window.location.pathname.startsWith('/rivet/library'))
        clearLibrarySession();
    } catch (err) {
      log.warn('Logout request failed', err);
      toast.error('Could not log out. Please try again.');
      setIsLoggingOut(false);
      return;
    }
    window.location.reload();
  };

  let accountLabel = 'Log in';
  if (isAuthenticated) accountLabel = firstName || 'Account';
  if (account.error && !account.data) accountLabel = 'Account unavailable';

  const closeDialog = () => {
    flushSync(() => setOpenDialog(null));
    trigger.current?.focus();
  };

  const chooseTheme = (preference: ThemePreference) => {
    if (preference === theme.preference) return;
    setThemePreference(preference);
    posthog?.capture('visual_editor_theme_changed', {
      preference,
      previous_preference: theme.preference,
    });
  };

  const changeMenuOpen = (isOpen: boolean) => {
    setIsOpen(isOpen);
    posthog?.capture(
      `visual_editor_account_menu_${isOpen ? 'opened' : 'closed'}`,
      { is_authenticated: isAuthenticated },
    );
  };

  return (
    <>
      <Menu isOpen={isOpen} onOpenChange={changeMenuOpen}>
        <MenuTrigger asChild>
          <button
            ref={trigger}
            type="button"
            aria-label="Account"
            data-rivet-private
            className={`group/account ph-no-capture text-soft-foreground hover:text-foreground focus-visible:text-foreground flex shrink-0 items-center gap-2 transition-colors select-none focus-visible:outline-hidden ${className}`}
          >
            <span className="border-separator bg-muted group-focus-visible/account:border-foreground flex h-8 w-8 items-center justify-center rounded-full border text-xs leading-none font-semibold">
              {initial || <User className="h-4 w-4" weight="bold" />}
            </span>
            <span className="max-w-[8rem] truncate text-sm font-medium">
              {accountLabel}
            </span>
          </button>
        </MenuTrigger>
        <MenuContent
          data-rivet-private
          className="ph-no-capture min-w-44"
          side={side}
          align={align}
          onCloseAutoFocus={(event) => {
            const dialog = pendingDialog.current;
            if (!dialog) return;
            pendingDialog.current = null;
            event.preventDefault();
            trigger.current?.focus();
            setOpenDialog(dialog);
          }}
        >
          {displayName || displayEmail ? (
            <div className="border-separator mb-1 border-b px-3 py-2">
              {displayName ? (
                <div className="text-foreground truncate text-sm font-medium">
                  {displayName}
                </div>
              ) : null}
              {displayEmail ? (
                <div className="text-soft-foreground truncate text-xs">
                  {displayEmail}
                </div>
              ) : null}
            </div>
          ) : null}
          <MenuItem
            onSelect={() => {
              pendingDialog.current = 'connectors';
            }}
            disabled={!isAuthenticated}
          >
            <Swatches className="h-3.5 w-3.5" weight="bold" />
            Add references
          </MenuItem>
          <MenuItem
            onSelect={() => {
              pendingDialog.current = 'support';
            }}
          >
            <ChatCircle className="h-3.5 w-3.5" weight="bold" />
            Share feedback
          </MenuItem>
          <MenuControl className="border-separator my-1 flex items-center justify-between gap-3 border-y px-3 py-1.5">
            <span id={themeLabelId} className="text-soft-foreground text-xs">
              Theme
            </span>
            <Select
              labelledBy={themeLabelId}
              size="compact"
              options={THEME_OPTIONS}
              value={theme.preference}
              onValueChange={chooseTheme}
            />
          </MenuControl>
          {isAuthenticated ? (
            <MenuItem onClick={handleLogout} disabled={isLoggingOut}>
              <SignOut className="h-3.5 w-3.5" weight="bold" />
              {isLoggingOut ? 'Logging out…' : 'Log out'}
            </MenuItem>
          ) : null}
          {!isAuthenticated && !account.error ? (
            <MenuItem
              onClick={() => {
                void startLogin();
              }}
              disabled={isStartingLogin}
            >
              <SignIn className="h-3.5 w-3.5" weight="bold" />
              {isStartingLogin ? 'Logging in…' : 'Log in'}
            </MenuItem>
          ) : null}
          {account.error ? (
            <MenuItem
              onClick={() => {
                void account.refetch();
              }}
            >
              Retry account
            </MenuItem>
          ) : null}
          {signInUrl ? (
            <div className="max-w-64 px-3 py-2">
              <AuthorizationLinkNotice authUrl={signInUrl} />
            </div>
          ) : null}
          {loginError ? (
            <p
              role="alert"
              className="text-muted-foreground max-w-64 px-3 py-2 text-xs"
            >
              {loginError}
            </p>
          ) : null}
        </MenuContent>
      </Menu>
      {openDialog === 'connectors' ? (
        <ConnectorsModal isOpen onClose={closeDialog} />
      ) : null}
      <SupportTicketModal
        isOpen={openDialog === 'support'}
        onClose={closeDialog}
        contactEmail={email ?? undefined}
      />
    </>
  );
};

export default ProfileAvatar;
