import {
  DESIGN_LIBRARY_PATH,
  designLibraryEntryPath,
} from '@rivet/core/types/design-library';

export interface Selection {
  kind: 'library' | 'references' | 'workspace' | 'preview';
  projectId?: string;
  sessionId?: string;
  variantId?: string;
  referenceId?: string;
}
export const readLibrarySelection = (url: URL): Selection => {
  const segments = url.pathname
    .split('/')
    .filter(Boolean)
    .map(decodeURIComponent);
  const projectId = segments[3];
  if (segments[2] === 'references')
    return segments[3]
      ? { kind: 'references', referenceId: segments[3] }
      : { kind: 'references' };
  if (segments[2] !== 'projects' || !projectId) return { kind: 'library' };
  const sessionId = segments[4] === 'variants' ? segments[5] : undefined;
  const variantId = segments[4] === 'variants' ? segments[6] : undefined;
  const params = new URLSearchParams(url.search);
  if (sessionId && variantId && params.get('edit') !== '1')
    return { kind: 'preview', projectId, sessionId, variantId };
  return { kind: 'workspace', projectId, sessionId, variantId };
};

export const librarySelectionPath = (selection: Selection): string => {
  if (selection.kind === 'references')
    return selection.referenceId
      ? designLibraryEntryPath(selection.referenceId)
      : DESIGN_LIBRARY_PATH;
  if (selection.kind === 'library' || !selection.projectId)
    return '/rivet/library';
  const project = `/rivet/library/projects/${encodeURIComponent(selection.projectId)}`;
  if (selection.sessionId && selection.variantId)
    return `${project}/variants/${encodeURIComponent(selection.sessionId)}/${encodeURIComponent(selection.variantId)}${selection.kind === 'workspace' ? '?edit=1' : ''}`;
  return project;
};

export const readHistoryTarget = (
  search: string,
): { sessionId: string; variantId: string } | null => {
  const params = new URLSearchParams(search);
  const sessionId = params.get('historySession');
  const variantId = params.get('historyVariant');
  return sessionId && variantId ? { sessionId, variantId } : null;
};
