import { z } from 'zod';

export const PROJECT_NAME_MAX_LENGTH = 200;

export const LibraryProjectSchema = z.object({
  id: z.string(),
  name: z.string(),
  pinnedAt: z.string().nullable().optional(),
  lastOpenedAt: z.string(),
  projectPath: z.string(),
  isAvailable: z.boolean(),
  storageKind: z.enum(['project', 'bundle']),
  issue: z.string().optional(),
  historyIssue: z.string().optional(),
});
export type LibraryProject = z.infer<typeof LibraryProjectSchema>;

export const LibraryProjectPreviewSchema = z.object({
  dataUrl: z.string(),
  label: z.string(),
  capturedAt: z.string(),
});
export type LibraryProjectPreview = z.infer<typeof LibraryProjectPreviewSchema>;

export const LibraryDirectionSchema = z.object({
  projectId: z.string(),
  sessionId: z.string(),
  variantId: z.string(),
  label: z.string(),
  brief: z.string(),
  createdAt: z.string(),
  hasStaticPreview: z.boolean(),
  hasInteractivePreview: z.boolean(),
});
export type LibraryDirection = z.infer<typeof LibraryDirectionSchema>;

export const ProjectLibrarySnapshotSchema = z.object({
  projects: z.array(LibraryProjectSchema),
  variants: z.array(LibraryDirectionSchema),
});
export type ProjectLibrarySnapshot = z.infer<
  typeof ProjectLibrarySnapshotSchema
>;
