import posthog from 'posthog-js';
import { toast } from 'sonner';

export type FailureReportIssueState =
  | 'preview_unavailable'
  | 'variant_worker_failed'
  | 'variant_output_integrity_failed'
  | 'variant_verification_unavailable';

export type VariantCopy =
  | {
      readonly text: string;
      readonly copyKind:
        'reference' | 'description' | 'direction_ref' | 'import_failure_report';
    }
  | {
      readonly text: string;
      readonly copyKind: 'failure_report';
      readonly issueState: FailureReportIssueState;
    };

export interface VariantClipboardContext {
  readonly label: string;
  readonly description?: string;
}

export const formatVariantContextForClipboard = (
  args: VariantClipboardContext,
): string =>
  [args.label.trim(), args.description?.trim()]
    .filter((line): line is string => Boolean(line))
    .join('\n');

const copyEventProperties = (copy: VariantCopy) =>
  copy.copyKind === 'failure_report'
    ? { copyKind: copy.copyKind, issueState: copy.issueState }
    : { copyKind: copy.copyKind };

export const copyVariantContext = async (copy: VariantCopy): Promise<void> => {
  const trimmed = copy.text.trim();
  if (!trimmed) return;
  try {
    await navigator.clipboard.writeText(trimmed);
    posthog.capture('variants_panel.copy_completed', {
      outcome: 'success',
      ...copyEventProperties(copy),
    });
    toast.success('Copied');
  } catch (err) {
    posthog.capture('variants_panel.copy_failed', {
      outcome: 'failure',
      ...copyEventProperties(copy),
      errorName: err instanceof Error ? err.name : 'UnknownError',
    });
    toast.error("Couldn't copy");
  }
};
