import { cn } from '@/lib/utils';
import {
  Breadcrumb as FluidBreadcrumb,
  BreadcrumbButton as FluidBreadcrumbButton,
  BreadcrumbItem as FluidBreadcrumbItem,
  BreadcrumbList as FluidBreadcrumbList,
  BreadcrumbPage as FluidBreadcrumbPage,
} from '@/components/ui/breadcrumb';

type BreadcrumbStep = {
  label: string;
  onSelect: () => void;
};

type BreadcrumbProps = {
  label: string;
  steps: BreadcrumbStep[];
  current: string;
  isPrivate?: boolean;
  className?: string;
};

const RIVET_FONT_VARIATION = { fontVariationSettings: 'normal' };

const LABEL_GLYPH_OVERHANG_CLASS = '[&_[data-slot=breadcrumb-label]]:pr-0.5';

const TRAIL_CLASS = '[&>[data-slot=fluid-hover-highlight]]:hidden';

const STEP_CLASS = cn(
  LABEL_GLYPH_OVERHANG_CLASS,
  'rounded text-muted-foreground hover:bg-hover hover:text-foreground focus-visible:bg-active focus-visible:text-foreground focus-visible:outline-hidden focus-visible:[box-shadow:none]!',
);

const CURRENT_CLASS = cn(
  LABEL_GLYPH_OVERHANG_CLASS,
  'rounded text-foreground font-medium',
);

const Breadcrumb = ({
  label,
  steps,
  current,
  isPrivate = false,
  className,
}: BreadcrumbProps) => (
  <FluidBreadcrumb
    size="compact"
    aria-label={label}
    className={cn(TRAIL_CLASS, isPrivate ? 'ph-no-capture' : null, className)}
    data-rivet-private={isPrivate ? '' : undefined}
  >
    <FluidBreadcrumbList className="text-xs">
      {steps.map((step) => (
        <FluidBreadcrumbItem key={step.label}>
          <FluidBreadcrumbButton
            onClick={step.onSelect}
            className={STEP_CLASS}
            style={RIVET_FONT_VARIATION}
          >
            {step.label}
          </FluidBreadcrumbButton>
        </FluidBreadcrumbItem>
      ))}
      <FluidBreadcrumbItem>
        <FluidBreadcrumbPage
          className={CURRENT_CLASS}
          style={RIVET_FONT_VARIATION}
        >
          {current}
        </FluidBreadcrumbPage>
      </FluidBreadcrumbItem>
    </FluidBreadcrumbList>
  </FluidBreadcrumb>
);

export type { BreadcrumbProps, BreadcrumbStep };
export default Breadcrumb;
