import {
  variantReferenceSchema,
  type VariantReference,
} from './variant-reference';
import { z } from 'zod';

export const PROFILE_CANDIDATE_IMAGE_LIMIT = 6;
export const PROFILE_UPLOAD_COUNT = 100;
const DATA_URL_HEADER_LENGTH = 100;
const PREPARATION_METADATA_BYTES = 256 * 1024;
export const PROFILE_UPLOAD_BYTES = 35 * 1024 * 1024;
export const PROFILE_UPLOAD_ENCODED_BYTES =
  Math.ceil(PROFILE_UPLOAD_BYTES / 3) * 4;
export const PROFILE_PREPARATION_BODY_BYTES =
  PROFILE_UPLOAD_ENCODED_BYTES + PREPARATION_METADATA_BYTES;

export const RemoteProfileProviderSchema = z.enum([
  'pinterest',
  'arena',
  'x',
  'cosmos',
]);
export interface ProfileCollectionProgress {
  id: string;
  total: number;
  isComplete: boolean;
}
export const isRemoteProfileProvider = (
  value: string,
): value is z.infer<typeof RemoteProfileProviderSchema> =>
  RemoteProfileProviderSchema.safeParse(value).success;

export const ProfileProviderSchema = z.enum([
  'image',
  ...RemoteProfileProviderSchema.options,
  'text',
  'pdf',
  'variant',
]);
export const PROFILE_IMPORT_TRIGGERS = {
  connect: 'manual',
  refresh: 'manual',
  retry: 'manual',
  upload: 'manual',
  attachment: 'auto',
  resume: 'auto',
  cooldown_retry: 'auto',
  auto_refresh: 'auto',
} as const;
export type ProfileImportKind = keyof typeof PROFILE_IMPORT_TRIGGERS;
export const PROFILE_IMPORT_STEPS = [
  'memory_start',
  'enumerate',
  'download',
  'analysis',
  'index',
] as const;
export type ProfileImportStep = (typeof PROFILE_IMPORT_STEPS)[number];
export type ProfilePreparationOffReason =
  'request_mode_off' | 'profile_disabled' | 'no_uploads';
export const ProfileRuntimeSchema = z.enum(['codex', 'claude', 'cursor']);
export const ProfileSettingsSchema = z.union([
  z
    .object({
      isEnabled: z.literal(true),
      runtime: ProfileRuntimeSchema,
      autonomousReferences: z.boolean().optional(),
    })
    .strict(),
  z
    .object({
      isEnabled: z.literal(false).optional(),
      runtime: ProfileRuntimeSchema.optional(),
      autonomousReferences: z.boolean().optional(),
    })
    .strict()
    .refine(
      (input) =>
        input.isEnabled !== undefined ||
        input.autonomousReferences !== undefined,
      'Set isEnabled or autonomousReferences',
    ),
]);
export type ProfileSettings = z.infer<typeof ProfileSettingsSchema>;
export const ProfileVariantIdentitySchema = z
  .object({
    projectId: z.string().min(1).max(200),
    sessionId: z.string().min(1).max(200),
    variantId: z.string().min(1).max(200),
  })
  .strict();
export const ProfileVariantInputSchema = ProfileVariantIdentitySchema.extend({
  runtime: ProfileRuntimeSchema,
  note: z.string().trim().max(500).optional(),
  imageFile: z.string().min(1).max(2048).optional(),
});
export type ProfileVariantInput = z.infer<typeof ProfileVariantInputSchema>;
const ProfileVariantProvenanceSchema = ProfileVariantIdentitySchema.extend({
  treeSha: z.string().max(100).optional(),
});
export const ProfileMediaSchema = z.object({
  hash: z.string().regex(/^[a-f0-9]{64}$/),
  mimeType: z.enum(['image/png', 'image/jpeg', 'image/webp', 'image/gif']),
  bytes: z.number().int().positive(),
  representation: z
    .enum(['image', 'video-cover', 'page', 'variant'])
    .default('image'),
  page: z.number().int().positive().optional(),
});
export const ProfileSourceInputSchema = z.object({
  provider: ProfileProviderSchema,
  remoteId: z.string().trim().min(1).max(2048),
  title: z.string().trim().min(1).max(500),
  url: z.string().url().optional(),
});
export const ProfileReferenceInputSchema = z.object({
  provider: ProfileProviderSchema,
  remoteId: z.string().trim().min(1).max(2048),
  title: z.string().max(1000),
  text: z.string().max(100_000),
  url: z.string().url().optional(),
  media: z.array(ProfileMediaSchema).max(100),
  remoteImages: z.array(z.string().url()).max(100).optional(),
  remoteImageRepresentations: z
    .array(z.enum(['image', 'video-cover']))
    .max(100)
    .optional(),
  unsupportedReason: z.string().max(1000).optional(),
  variant: ProfileVariantProvenanceSchema.optional(),
  note: z.string().max(500).optional(),
});
export const ProfileUsageSchema = z.object({
  inputTokens: z.number().nonnegative().optional(),
  outputTokens: z.number().nonnegative().optional(),
  cachedInputTokens: z.number().nonnegative().optional(),
  allocation: z.literal('equal-share').optional(),
});
export type ProfileUsage = z.infer<typeof ProfileUsageSchema>;
export const ProfileObservationSchema = z.object({
  referenceId: z.string().min(1),
  revision: z.number().int().positive(),
  description: z.string().trim().min(1).max(8000),
  runtime: z.union([ProfileRuntimeSchema, z.literal('user')]),
  evidence: z.enum(['observation', 'preference', 'provisional']),
  usage: ProfileUsageSchema.optional(),
});
export type ProfileProvider = z.infer<typeof ProfileProviderSchema>;
export type ProfileRuntime = z.infer<typeof ProfileRuntimeSchema>;
export type ProfileMedia = z.infer<typeof ProfileMediaSchema>;
export type ProfileSourceInput = z.infer<typeof ProfileSourceInputSchema>;
export type ProfileReferenceInput = z.infer<typeof ProfileReferenceInputSchema>;
export type ProfileObservation = z.infer<typeof ProfileObservationSchema>;
export const hasCompletedAnalysis = (
  observation: Pick<ProfileObservation, 'evidence'> | null,
): boolean => observation !== null && observation.evidence !== 'provisional';
export const ProfileReferenceSchema = ProfileReferenceInputSchema.extend({
  id: z.string(),
  revision: z.number(),
});
export type ProfileReference = z.infer<typeof ProfileReferenceSchema>;
export interface ProfileCandidate {
  reference: ProfileReference;
  observation: ProfileObservation;
  sources: Array<ProfileSourceInput & { id: string }>;
}

export interface ProfileIndexWork {
  id: string;
  referenceId: string;
  revision: number;
  operation: 'upsert' | 'delete';
  engineId: string | null;
  state: 'pending' | 'indexed';
}

export const ReferenceAutonomySchema = z.enum(['on', 'off']);
export type ReferenceAutonomy = z.infer<typeof ReferenceAutonomySchema>;
export const PickTriggerSchema = z.enum(['autonomous', 'user_requested']);
export type PickTrigger = z.infer<typeof PickTriggerSchema>;
export const REFERENCE_PICK_LIMIT = 3;
export const REFERENCE_PICK_REASON_CHARACTERS = 500;
export const ReferencePicksSchema = z
  .object({
    profileId: z.string().uuid(),
    picks: z
      .array(
        z
          .object({
            key: z.string().trim().min(1).max(200),
            reason: z
              .string()
              .trim()
              .min(1)
              .max(REFERENCE_PICK_REASON_CHARACTERS),
          })
          .strict(),
      )
      .min(1)
      .max(REFERENCE_PICK_LIMIT),
  })
  .strict();
export type ReferencePicks = z.infer<typeof ReferencePicksSchema>;
export const ProfilePreparationSchema = z.object({
  requestId: z.string().min(1).max(200),
  instruction: z.string().min(1).max(30_000),
  runtime: ProfileRuntimeSchema,
  mode: z.enum(['auto', 'off', 'uploads']).default('off'),
  excludedSourceIds: z.array(z.string()).max(100).default([]),
  excludedReferenceIds: z.array(z.string()).max(100).default([]),
  excludedMediaHashes: z.array(z.string()).max(100).default([]),
  suppliedInputHashes: z
    .array(z.string().regex(/^[a-f0-9]{64}$/))
    .max(PROFILE_UPLOAD_COUNT)
    .optional(),
  referencePicks: ReferencePicksSchema.optional(),
  pickTrigger: PickTriggerSchema.optional(),
});
export type ProfilePreparation = z.infer<typeof ProfilePreparationSchema>;
export const ProfilePreparationRequestSchema = ProfilePreparationSchema.extend({
  mode: z.enum(['auto', 'off', 'uploads']).default('uploads'),
  uploads: z
    .array(
      z.string().max(PROFILE_UPLOAD_ENCODED_BYTES + DATA_URL_HEADER_LENGTH),
    )
    .max(PROFILE_UPLOAD_COUNT)
    .optional(),
}).refine(
  (input) =>
    (input.uploads ?? []).reduce((size, image) => size + image.length, 0) <=
    PROFILE_UPLOAD_ENCODED_BYTES +
      PROFILE_UPLOAD_COUNT * DATA_URL_HEADER_LENGTH,
  'Supplied images exceed the profile upload budget',
);
export type ProfilePreparationRequest = z.infer<
  typeof ProfilePreparationRequestSchema
>;
const suppliedReferenceSchema = z
  .unknown()
  .transform((value, context): VariantReference => {
    const parsed = variantReferenceSchema.safeParse(value);
    if (parsed.success) return parsed.data;
    context.addIssue({
      code: z.ZodIssueCode.custom,
      message: 'Invalid supplied image reference',
    });
    return z.NEVER;
  });
export const ProfilePacketSchema = z.object({
  suppliedReferences: z
    .array(suppliedReferenceSchema)
    .max(PROFILE_UPLOAD_COUNT)
    .optional(),
  failedUploadCount: z
    .number()
    .int()
    .min(0)
    .max(PROFILE_UPLOAD_COUNT)
    .optional(),
  usage: ProfileUsageSchema.optional(),
  requestId: z.string(),
  status: z.enum(['selected', 'empty', 'off', 'unavailable', 'timeout']),
  queries: z.array(z.string()),
  candidateIds: z.array(z.string()),
  selected: z.array(
    z.object({
      id: z.string(),
      revision: z.number(),
      title: z.string().optional(),
      url: z.string().url().optional(),
      mediaHashes: z.array(z.string().regex(/^[a-f0-9]{64}$/)).optional(),
      reason: z.string(),
      sourceTitles: z.array(z.string()),
      variant: ProfileVariantProvenanceSchema.optional(),
      selectedBy: z.enum(['rivet', 'host']).optional(),
    }),
  ),
  contextText: z.string().max(6000),
  images: z
    .array(
      z.object({
        path: z.string(),
        hash: z.string().regex(/^[a-f0-9]{64}$/),
        mimeType: z.enum([
          'image/png',
          'image/jpeg',
          'image/webp',
          'image/gif',
        ]),
      }),
    )
    .max(PROFILE_CANDIDATE_IMAGE_LIMIT),
  durationMs: z.number(),
});
export type ProfilePacket = z.infer<typeof ProfilePacketSchema>;

export const ProfileContextSchema = ProfilePacketSchema.pick({
  requestId: true,
  suppliedReferences: true,
  failedUploadCount: true,
  status: true,
  selected: true,
  images: true,
  durationMs: true,
}).extend({
  requestId: z.string().min(1).max(200),
  selected: ProfilePacketSchema.shape.selected.max(3),
  inheritedReferences: z.array(suppliedReferenceSchema).optional(),
});
export type ProfileContext = z.infer<typeof ProfileContextSchema>;
export interface ProfileContextResult extends ProfileContext {
  isRecorded: boolean;
}
