import { fetchLocalApi } from './localApi';

type EventStream = {
  onmessage: ((event: { data: string }) => void) | null;
  onerror: ((error: unknown) => void) | null;
  close: () => void;
};

const RECONNECT_DELAY_MS = 3_000;

export const createEventStream = (
  path: `/api/${string}`,
  fetcher = fetchLocalApi,
): EventStream => {
  const controller = new AbortController();
  let reconnectTimer: ReturnType<typeof setTimeout> | undefined;
  const stream: EventStream = {
    onmessage: null,
    onerror: null,
    close: () => {
      controller.abort();
      clearTimeout(reconnectTimer);
    },
  };
  const connect = async (): Promise<void> => {
    let isAuthorizationFailure = false;
    try {
      const response = await fetcher(path, {
        signal: controller.signal,
        headers: { Accept: 'text/event-stream' },
      });
      isAuthorizationFailure =
        response.status === 401 || response.status === 403;
      if (!response.ok || !response.body) {
        await response.body?.cancel();
        throw new Error(`Event stream request failed (${response.status}).`);
      }
      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';
      let data: string[] = [];
      try {
        while (!controller.signal.aborted) {
          const chunk = await reader.read();
          if (chunk.done) break;
          buffer += decoder.decode(chunk.value, { stream: true });
          let boundary = buffer.indexOf('\n');
          while (boundary !== -1) {
            const line = buffer.slice(0, boundary).replace(/\r$/, '');
            buffer = buffer.slice(boundary + 1);
            if (line === '') {
              if (data.length > 0 && !controller.signal.aborted) {
                stream.onmessage?.({ data: data.join('\n') });
              }
              data = [];
            } else if (line.startsWith('data:')) {
              data.push(line.slice('data:'.length).replace(/^ /, ''));
            }
            boundary = buffer.indexOf('\n');
          }
        }
      } finally {
        await reader.cancel().catch(() => undefined);
        reader.releaseLock();
      }
    } catch (error) {
      if (!controller.signal.aborted) stream.onerror?.(error);
    }
    if (!controller.signal.aborted && !isAuthorizationFailure) {
      reconnectTimer = setTimeout(() => void connect(), RECONNECT_DELAY_MS);
    }
  };
  void connect();
  return stream;
};
