import {
  PREVIEW_BRIDGE_CHANNEL,
  PREVIEW_BRIDGE_FORWARDED_KEYS,
  type PreviewBridgeForwardedKey,
} from '@rivet/core/types/preview-bridge';
import { isTextEntryTarget } from './textEntryTarget';

type KeyDownListener = (event: KeyboardEvent) => void;

const readForwardedKey = (data: unknown): PreviewBridgeForwardedKey | null => {
  if (
    typeof data !== 'object' ||
    data === null ||
    !('channel' in data) ||
    data.channel !== PREVIEW_BRIDGE_CHANNEL ||
    !('direction' in data) ||
    data.direction !== 'event' ||
    !('type' in data) ||
    data.type !== 'keydown' ||
    !('key' in data)
  ) {
    return null;
  }
  return PREVIEW_BRIDGE_FORWARDED_KEYS.find((key) => key === data.key) ?? null;
};

const readFrameOrigin = (frame: HTMLIFrameElement): string | null => {
  try {
    return new URL(frame.src, window.location.href).origin;
  } catch {
    return null;
  }
};

const findSendingFrame = (event: MessageEvent): HTMLIFrameElement | null =>
  event.source === null
    ? null
    : (Array.from(document.querySelectorAll('iframe')).find(
        (frame) =>
          frame.contentWindow === event.source &&
          readFrameOrigin(frame) === event.origin,
      ) ?? null);

export const listenForEditorShortcutKeys = (
  listener: KeyDownListener,
): (() => void) => {
  const handleKeyDown = (event: KeyboardEvent) => {
    if (isTextEntryTarget(event.target)) return;
    listener(event);
  };
  window.addEventListener('keydown', handleKeyDown);
  return () => window.removeEventListener('keydown', handleKeyDown);
};

export const forwardPreviewShortcutKeys = (): (() => void) => {
  const handleMessage = (event: MessageEvent) => {
    const key = readForwardedKey(event.data);
    const frame = key ? findSendingFrame(event) : null;
    if (!key || !frame) return;
    frame.dispatchEvent(
      new KeyboardEvent('keydown', { key, bubbles: true, cancelable: true }),
    );
  };
  window.addEventListener('message', handleMessage);
  return () => window.removeEventListener('message', handleMessage);
};
