import { useCallback, useRef } from 'react';
import { usePostHog } from 'posthog-js/react';
import { useAtomValue } from 'jotai';
import { agentApplyModeAtom } from '@/store/atoms';
import { getPreviewIframeSandbox } from '@/utils/previewSandbox';
import { createLogger } from '@/utils/logger';
import type { Framework, PreviewTarget } from '@/types';

const log = createLogger('PreviewSurface');

const iframeSrcKind = (
  src: string,
  target: PreviewTarget,
): 'blank' | 'static_artifact' | 'dev_server' | 'original' => {
  if (src === 'about:blank') return 'blank';
  if (src.includes('/api/variants/')) return 'static_artifact';
  if (target.kind === 'variant') return 'dev_server';
  return 'original';
};

export type PreviewSurfaceProps = {
  target: PreviewTarget;
  src: string;
  framework: Framework;
  remountKey?: string | number;
  isActive?: boolean;
};

const PreviewSurface = ({
  target,
  src,
  framework,
  remountKey,
  isActive = true,
}: PreviewSurfaceProps) => {
  const agentApplyMode = useAtomValue(agentApplyModeAtom);
  const posthog = usePostHog();
  const isLoaded = useRef(false);
  const wasActive = useRef(isActive);
  const captureDisplay = useCallback(
    (isReused: boolean) => {
      if (target.kind !== 'variant') return;
      posthog?.capture('variants_panel.preview_displayed', {
        sessionId: target.sessionId,
        variantId: target.variantId,
        renderedTarget: 'variant',
        iframeSrcKind: iframeSrcKind(src, target),
        framework,
        isReused,
      });
    },
    [framework, posthog, src, target],
  );

  const captureVisibility = useCallback(
    (surface: HTMLDivElement | null) => {
      if (!surface) return;
      if (isActive && !wasActive.current && isLoaded.current)
        captureDisplay(true);
      wasActive.current = isActive;
    },
    [captureDisplay, isActive],
  );

  return (
    <div ref={captureVisibility} className="relative h-full w-full">
      <iframe
        key={remountKey}
        src={src}
        className="h-full w-full border-none"
        title={isActive ? 'Project Preview' : 'Retained Project Preview'}
        tabIndex={isActive ? undefined : -1}
        sandbox={getPreviewIframeSandbox(agentApplyMode)}
        onLoad={() => {
          isLoaded.current = true;
          posthog?.capture('preview_iframe_loaded', {
            framework,
            src_kind: iframeSrcKind(src, target),
          });
          if (isActive) captureDisplay(false);
        }}
        onError={() => {
          posthog?.capture('preview_iframe_load_failed', {
            framework,
            src_kind: iframeSrcKind(src, target),
          });
          if (isActive && target.kind === 'variant') {
            posthog?.capture('variants_panel.preview_display_failed', {
              sessionId: target.sessionId,
              variantId: target.variantId,
              renderedTarget: 'variant',
              iframeSrcKind: iframeSrcKind(src, target),
              framework,
            });
          }
          log.warn('Preview iframe failed to load', {
            framework,
            src_kind: iframeSrcKind(src, target),
          });
        }}
      />
    </div>
  );
};

export default PreviewSurface;
