import { z } from 'zod';
import { fetchLocalApi } from '@/utils/localApi';

export type RivetConfig = {
  agentModeAvailable: boolean;
  email?: string;
  userId?: string;
  name?: string;
  isMCPSession: boolean;
  mcpEditor: string | null;
  agentApplyMode?: 'embedded' | 'external' | null;
  queueAccessToken?: string | null;
  projectPath: string;
  projectName?: string;
  projectId?: string | null;
  libraryOrigin: string | null;
};

const RivetConfigSchema: z.ZodType<RivetConfig> = z.object({
  agentModeAvailable: z.boolean(),
  email: z.string().optional(),
  userId: z.string().optional(),
  name: z.string().optional(),
  isMCPSession: z.boolean(),
  mcpEditor: z.string().nullable(),
  agentApplyMode: z.enum(['embedded', 'external']).nullable().optional(),
  queueAccessToken: z.string().nullable().optional(),
  projectPath: z.string(),
  projectName: z.string().optional(),
  projectId: z.string().uuid().nullable().optional(),
  libraryOrigin: z.string().url().nullable(),
});

export const fetchRivetConfig = async ({
  signal,
}: {
  signal?: AbortSignal;
}): Promise<RivetConfig> => {
  const response = await fetchLocalApi('/api/config', { signal });
  if (!response.ok) {
    throw new Error(`Failed to fetch config: ${response.statusText}`);
  }
  return RivetConfigSchema.parse(await response.json());
};
