import { ReactElement, ReactNode } from 'react';
import { Tooltip as FluidTooltip } from '@/components/ui/tooltip';

type TooltipProps = {
  label: ReactNode;
  children: ReactNode;
  side?: 'top' | 'right' | 'bottom' | 'left';
  sideOffset?: number;
  delayDuration?: number;
  disabled?: boolean;
  forceOpen?: boolean;
};

export const TOOLTIP_SURFACE_CLASSES =
  'bg-tooltip text-tooltip-foreground border-tooltip-border shadow-floating';

const Tooltip = ({
  label,
  children,
  side = 'top',
  sideOffset = 8,
  delayDuration = 300,
  disabled = false,
  forceOpen,
}: TooltipProps) => {
  if (disabled) return <>{children}</>;
  return (
    <FluidTooltip
      content={label}
      className={TOOLTIP_SURFACE_CLASSES}
      side={side}
      sideOffset={sideOffset}
      delayDuration={delayDuration}
      forceOpen={forceOpen}
    >
      {children as ReactElement}
    </FluidTooltip>
  );
};

export default Tooltip;
