import { redactSensitiveText } from '@rivet/core/utils/hostedLogPrivacy';

export type AgentPastePackage = string & {
  readonly __brand: 'AgentPastePackage';
};

export type AgentPasteFacts = {
  problem: string;
  ask?: string;
  reasonCode?: string;
  errorCode?: string;
  failedStep?: string;
  reasonDetail?: string;
  nextStep?: string;
  worker?: string;
  rivetVersion: string;
  nodeVersion?: string;
  platform?: string;
  directionLabel?: string;
  directionRef?: string;
  sessionId?: string;
  importProvider?: string;
  importJobId?: string;
  analyzedReferences?: string;
  errorExcerpt?: string;
};

const AGENT_PASTE_FIELDS = [
  ['Problem', 'problem'],
  ['Ask', 'ask'],
  ['Reason code', 'reasonCode'],
  ['Error code', 'errorCode'],
  ['Failed step', 'failedStep'],
  ['Rivet detail', 'reasonDetail'],
  ['Next step', 'nextStep'],
  ['Worker', 'worker'],
  ['Rivet version', 'rivetVersion'],
  ['Node.js version (Rivet runtime)', 'nodeVersion'],
  ['Platform', 'platform'],
  ['Direction', 'directionLabel'],
  ['Direction ref', 'directionRef'],
  ['Rivet session', 'sessionId'],
  ['Import provider', 'importProvider'],
  ['Import job', 'importJobId'],
  ['References analyzed', 'analyzedReferences'],
] as const satisfies ReadonlyArray<
  readonly [string, Exclude<keyof AgentPasteFacts, 'errorExcerpt'>]
>;

const ERROR_EXCERPT_LINE_LIMIT = 20;
const ERROR_EXCERPT_CHAR_LIMIT = 2_000;

const boundErrorExcerpt = (error: string): string => {
  const lines = error.split(/\r?\n/);
  const keptLines = redactSensitiveText(
    lines.slice(0, ERROR_EXCERPT_LINE_LIMIT).join('\n'),
  );
  const excerpt = keptLines.slice(0, ERROR_EXCERPT_CHAR_LIMIT);
  const omittedLineCount = lines.length - ERROR_EXCERPT_LINE_LIMIT;
  return [
    excerpt,
    ...(excerpt.length < keptLines.length ? ['[truncated]'] : []),
    ...(omittedLineCount > 0
      ? [`[${omittedLineCount} more lines omitted]`]
      : []),
  ].join('\n');
};

export const formatAgentPastePackage = (
  facts: AgentPasteFacts,
): AgentPastePackage => {
  const lines: string[] = [];
  for (const [label, key] of AGENT_PASTE_FIELDS) {
    const value = facts[key]?.trim();
    if (!value) continue;
    lines.push(`${label}: ${value}`);
  }
  const errorExcerpt = facts.errorExcerpt?.trim();
  if (errorExcerpt) {
    lines.push(
      'Error excerpt:',
      '```text',
      boundErrorExcerpt(errorExcerpt),
      '```',
    );
  }
  return lines.join('\n') as AgentPastePackage;
};
