import { z } from 'zod';
import {
  ReferenceCollectionSchema,
  ReferenceProfileSchema,
  ReferenceIdSchema,
  ReferenceProviderSchema,
  referenceProvider,
  referenceScopeDisclosure,
} from './reference-connectors';
import {
  ProfileReferenceInputSchema,
  ProfileRuntimeSchema,
} from './design-profile';

export const REFERENCE_COLLECTION_LIMIT = 1000;
export const REFERENCE_PLAN_LIMIT = 10_000;
export const REFERENCE_PLAN_BYTES = 20 * 1024 * 1024;
export const REFERENCE_PLAN_LIFETIME_MS = 24 * 60 * 60 * 1000;
export const REFERENCE_REMINDER_DELAY_MS = 7 * 24 * 60 * 60 * 1000;
export const REFERENCE_USAGE_DISCLOSURE =
  'Rivet will download the approved references and use the selected agent runtime to analyze them. Analysis sends reference content to that runtime’s model service and consumes its usage allowance. References and searchable descriptions are stored locally for reuse across projects. Future reference selection can also consume agent usage. Token and duration estimates are unavailable.';

export const ReferenceDiscoveryInputSchema = z.object({
  profile: ReferenceProfileSchema,
  collections: z
    .array(ReferenceCollectionSchema)
    .max(REFERENCE_COLLECTION_LIMIT),
  total: z.number().int().nonnegative().max(REFERENCE_COLLECTION_LIMIT),
});
export const ReferenceDiscoverySchema = ReferenceDiscoveryInputSchema.extend({
  id: z.string().uuid(),
  createdAt: z.string().datetime(),
});
export const ReferencePlanSourceSchema = z.object({
  collection: ReferenceCollectionSchema,
  collectionIds: z
    .array(ReferenceIdSchema)
    .min(1)
    .max(REFERENCE_COLLECTION_LIMIT),
  references: z
    .array(
      ProfileReferenceInputSchema.extend({ provider: ReferenceProviderSchema }),
    )
    .max(REFERENCE_PLAN_LIMIT),
});
export const ReferencePlanInputSchema = z.object({
  discoveryId: z.string().uuid(),
  runtime: ProfileRuntimeSchema,
  sources: z
    .array(ReferencePlanSourceSchema)
    .min(1)
    .max(REFERENCE_COLLECTION_LIMIT),
  reusableCount: z.number().int().nonnegative(),
});
export const ReferencePlanSchema = ReferencePlanInputSchema.extend({
  id: z.string().uuid(),
  profile: ReferenceProfileSchema,
  revision: z.string().regex(/^[a-f0-9]{64}$/),
  createdAt: z.string().datetime(),
  expiresAt: z.string().datetime(),
  approvedAt: z.string().datetime().nullable(),
  jobIds: z.array(z.string().uuid()),
});
export const ReferencePlanRequestSchema = z
  .object({
    discoveryId: z.string().uuid(),
    collectionIds: z
      .array(ReferenceIdSchema)
      .min(1)
      .max(REFERENCE_COLLECTION_LIMIT),
    runtime: ProfileRuntimeSchema,
  })
  .strict();
export const ReferenceApprovalSchema = z
  .object({
    id: z.string().uuid(),
    revision: z.string().regex(/^[a-f0-9]{64}$/),
    isApproved: z.literal(true),
  })
  .strict();
export const ReferenceOnboardingActionSchema = z.enum([
  'later',
  'dismiss',
  'reset',
]);
export type ReferenceDiscovery = z.infer<typeof ReferenceDiscoverySchema>;
export type ReferenceImportPlan = z.infer<typeof ReferencePlanSchema>;
export type ReferencePlanSource = z.infer<typeof ReferencePlanSourceSchema>;
export type ReferencePlanRequest = z.infer<typeof ReferencePlanRequestSchema>;
export type ReferenceOnboardingAction = z.infer<
  typeof ReferenceOnboardingActionSchema
>;

export const referencePlanSummary = (plan: ReferenceImportPlan) => {
  const references = new Map(
    plan.sources.flatMap((source) =>
      source.references.map(
        (reference) => [reference.remoteId, reference] as const,
      ),
    ),
  );
  const referenceCount = references.size;
  const imageCount = [...references.values()].reduce(
    (count, reference) => count + (reference.remoteImages?.length ?? 0),
    0,
  );
  return {
    id: plan.id,
    revision: plan.revision,
    discoveryId: plan.discoveryId,
    profile: plan.profile,
    provider: referenceProvider(plan.profile),
    runtime: plan.runtime,
    createdAt: plan.createdAt,
    expiresAt: plan.expiresAt,
    approvedAt: plan.approvedAt,
    jobIds: plan.jobIds,
    collections: plan.sources.map(
      ({ collection, collectionIds, references: items }) => ({
        ...collection,
        includedCollectionIds: collectionIds,
        referenceCount: items.length,
      }),
    ),
    collectionCount: new Set(
      plan.sources.flatMap((source) => source.collectionIds),
    ).size,
    referenceCount,
    imageCount,
    reusableCount: plan.reusableCount,
    analysisCount: Math.max(
      0,
      [...references.values()].filter(
        (reference) => !reference.unsupportedReason,
      ).length - plan.reusableCount,
    ),
    tokenEstimate: null,
    durationEstimateMs: null,
    scopeDisclosure: referenceScopeDisclosure[referenceProvider(plan.profile)],
    unsupportedCount: [...references.values()].filter(
      (reference) => reference.unsupportedReason,
    ).length,
    usageDisclosure: REFERENCE_USAGE_DISCLOSURE,
    approvalRequired: plan.approvedAt === null,
  };
};
