import { z } from 'zod';
import {
  CosmosCursorSchema,
  CosmosIdSchema,
  parseCosmosProfileUrl,
  parseCosmosUrl,
} from './cosmos';

export const CosmosProfileSchema = z.object({
  id: CosmosIdSchema,
  username: z.string().min(1).max(100),
  title: z.string().max(500),
  url: z.string().transform((url) => parseCosmosProfileUrl(url).url),
});
export const CosmosProfileCollectionSchema = z.object({
  id: CosmosIdSchema,
  title: z.string().min(1).max(500),
  description: z.string().max(10_000).nullable(),
  url: z.string().transform((url) => parseCosmosUrl(url).url),
  total: z.number().int().nonnegative(),
  parentId: CosmosIdSchema.nullable(),
  children: z.array(CosmosIdSchema).max(10_000),
});
export const CosmosProfilePageSchema = z.object({
  profile: CosmosProfileSchema,
  collections: z.array(CosmosProfileCollectionSchema),
  total: z.number().int().nonnegative(),
  nextCursor: CosmosCursorSchema.nullable(),
});
export type CosmosProfilePage = z.infer<typeof CosmosProfilePageSchema>;
export interface CosmosDiscoveryInput {
  url: string;
  cursor?: string;
  signal?: AbortSignal;
}
