const TEXT_ENTRY_TAG_NAMES = new Set(['INPUT', 'TEXTAREA', 'SELECT']);

export const isTextEntryTarget = (target: EventTarget | null): boolean => {
  if (!target || !('tagName' in target) || typeof target.tagName !== 'string') {
    return false;
  }
  return (
    TEXT_ENTRY_TAG_NAMES.has(target.tagName.toUpperCase()) ||
    ('isContentEditable' in target && target.isContentEditable === true)
  );
};
