import { useAtomValue, useSetAtom } from 'jotai';
import { useEffect, useRef, useState } from 'react';
import { usePostHog } from 'posthog-js/react';
import {
  draggedVariantAtom,
  draggedVariantPointerAtom,
  variantSplitViewAtom,
} from '@/store/atoms';
import { stopHistoryReplayTarget } from '@/utils/historyReplayCleanup';
import { buildVariantComparisonTelemetryEvent } from '@/utils/variantComparisonTelemetry';

type Side = 'left' | 'right';

const zoneAtPoint = (
  container: HTMLElement | null,
  point: { x: number; y: number },
): Side | null => {
  if (!container) return null;
  const r = container.getBoundingClientRect();
  const { x, y } = point;
  if (x < r.left || x > r.right || y < r.top || y > r.bottom) return null;
  return x < (r.left + r.right) / 2 ? 'left' : 'right';
};

export function VariantSplitDropZones() {
  const dragged = useAtomValue(draggedVariantAtom);
  const pointer = useAtomValue(draggedVariantPointerAtom);
  const split = useAtomValue(variantSplitViewAtom);
  const setDragged = useSetAtom(draggedVariantAtom);
  const setSplit = useSetAtom(variantSplitViewAtom);
  const posthog = usePostHog();
  const containerRef = useRef<HTMLDivElement | null>(null);
  const [hovered, setHovered] = useState<Side | null>(null);
  const [phase, setPhase] = useState<'hidden' | 'visible' | 'exiting'>(
    'hidden',
  );

  if (!dragged && (phase !== 'hidden' || hovered !== null)) {
    setPhase('hidden');
    setHovered(null);
  }

  useEffect(() => {
    if (!dragged || !pointer) return;
    const z = zoneAtPoint(containerRef.current, pointer);
    setHovered((prev) => (prev === z ? prev : z));
    setPhase((prev) => {
      if (prev === 'exiting') return prev;
      const next = z !== null ? 'visible' : 'hidden';
      return prev === next ? prev : next;
    });
  }, [dragged, pointer]);

  useEffect(() => {
    if (!dragged) return;
    const onUp = (e: PointerEvent) => {
      const z = zoneAtPoint(containerRef.current, {
        x: e.clientX,
        y: e.clientY,
      });
      if (z && dragged.url) {
        const slot = {
          sessionId: dragged.sessionId,
          variantId: dragged.variantId,
          label: dragged.label,
          url: dragged.url,
          source: dragged.source,
        };
        const replacedSlot = split?.[z];
        if (
          replacedSlot &&
          (replacedSlot.sessionId !== slot.sessionId ||
            replacedSlot.variantId !== slot.variantId)
        ) {
          stopHistoryReplayTarget(replacedSlot);
        }
        const nextSplit = { ...(split ?? {}), [z]: slot };
        setSplit(nextSplit);
        const telemetryEvent = buildVariantComparisonTelemetryEvent(
          split ? 'updated' : 'started',
          nextSplit,
        );
        posthog?.capture(telemetryEvent.event, telemetryEvent.properties);
        setPhase('exiting');
        window.setTimeout(() => setDragged(null), 220);
      } else {
        stopHistoryReplayTarget(dragged);
        setPhase('exiting');
        window.setTimeout(() => setDragged(null), 220);
      }
    };
    window.addEventListener('pointerup', onUp);
    window.addEventListener('pointercancel', onUp);
    return () => {
      window.removeEventListener('pointerup', onUp);
      window.removeEventListener('pointercancel', onUp);
    };
  }, [dragged, posthog, setDragged, setSplit, split]);

  if (!dragged) return null;

  const zonesClass = [
    'variant-drop-zones',
    phase === 'visible' && 'is-visible',
    phase === 'exiting' && 'is-exiting',
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <div ref={containerRef} className={zonesClass} aria-hidden="true">
      <Zone
        side="left"
        hovered={hovered === 'left'}
        canDrop={Boolean(dragged.url)}
        label={dragged.label}
      />
      <Zone
        side="right"
        hovered={hovered === 'right'}
        canDrop={Boolean(dragged.url)}
        label={dragged.label}
      />
    </div>
  );
}

function Zone({
  side,
  hovered,
  canDrop,
  label,
}: {
  side: Side;
  hovered: boolean;
  canDrop: boolean;
  label: string;
}) {
  return (
    <div
      className={[
        'variant-drop-zone',
        `is-${side}`,
        hovered && 'is-hover',
        !canDrop && 'is-disabled',
      ]
        .filter(Boolean)
        .join(' ')}
    >
      <div className="variant-drop-zone-inner">
        <div className={`variant-drop-zone-icon is-${side}`} />
        <div className="variant-drop-zone-caption">
          {canDrop
            ? `Add ${side} split`
            : 'Split unavailable for this direction'}
        </div>
      </div>
      <div className="variant-drop-zone-preview" aria-hidden="true">
        <div className="variant-drop-zone-preview-label">{label}</div>
      </div>
      <div className="variant-drop-zone-border" />
    </div>
  );
}

export default VariantSplitDropZones;
