
import { useId, useRef, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import posthog from 'posthog-js';
import { useLatestRef } from '@/hooks/useLatestRef';
import { fetchLocalApi } from '@/utils/localApi';
import { queryKeys } from '@/utils/queryKeys';
import { createLogger } from '../utils/logger';
import type { Framework } from '../types';

type UnavailableReason = 'upstream_unreachable' | 'rivet_unreachable';

type DevServerHealthSnapshot = {
  ownership: 'rivet_owned' | 'external' | 'none';
  isReachable: boolean | null;
  reason:
    | 'healthy'
    | 'upstream_unreachable'
    | 'rivet_unreachable'
    | 'unknown';
};

type MCPStatusBody = {
  devServerHealth?: DevServerHealthSnapshot;
};

type ProbeOutcome = {
  isOk: boolean;
  unavailableReason: UnavailableReason;
  upstreamStatus: number | null;
};

const probeUpstreamHealth = async (
  probePath: string | null = null,
): Promise<ProbeOutcome> => {
  if (probePath) {
    return probePreviewPath(probePath);
  }

  let mcpResponse: Response;
  try {
    mcpResponse = await fetchLocalApi('/api/mcp/status');
  } catch {
    return {
      isOk: false,
      unavailableReason: 'rivet_unreachable',
      upstreamStatus: null,
    };
  }

  if (mcpResponse.status === 404) {
    return probeRootFallback();
  }
  const contentType = mcpResponse.headers.get('content-type') ?? '';
  if (!contentType.toLowerCase().includes('application/json')) {
    return probeRootFallback();
  }
  if (!mcpResponse.ok) {
    return {
      isOk: false,
      unavailableReason: 'rivet_unreachable',
      upstreamStatus: null,
    };
  }

  let body: MCPStatusBody;
  try {
    body = (await mcpResponse.json()) as MCPStatusBody;
  } catch {
    return probeRootFallback();
  }

  const dsh = body.devServerHealth;
  if (!dsh) {
    return probeRootFallback();
  }
  if (dsh.ownership === 'none') {
    return {
      isOk: false,
      unavailableReason: 'upstream_unreachable',
      upstreamStatus: null,
    };
  }
  if (dsh.isReachable === true) {
    return {
      isOk: true,
      unavailableReason: 'upstream_unreachable',
      upstreamStatus: null,
    };
  }
  return {
    isOk: false,
    unavailableReason:
      dsh.reason === 'rivet_unreachable'
        ? 'rivet_unreachable'
        : 'upstream_unreachable',
    upstreamStatus: null,
  };
};

const probeDirect = async (path: string): Promise<ProbeOutcome> => {
  try {
    const response = await fetch(path);
    const isOk = response.status !== 502 && response.status !== 503;
    return {
      isOk,
      unavailableReason: 'upstream_unreachable',
      upstreamStatus: response.status,
    };
  } catch {
    return {
      isOk: false,
      unavailableReason: 'rivet_unreachable',
      upstreamStatus: null,
    };
  }
};

const probePreviewPath = (probePath: string): Promise<ProbeOutcome> =>
  probeDirect(probePath);

const probeRootFallback = (): Promise<ProbeOutcome> => probeDirect('/');

const log = createLogger('usePreviewUpstreamHealth');

export const DEFAULT_PROBE_MS_WHILE_DOWN = 500;
export const DEFAULT_PROBE_MS_WHILE_UP = 4000;
const DEFAULT_FIRST_UNREACHABLE_AFTER_MS = 15_000;
export const PERSISTENT_UPSTREAM_ERROR_THRESHOLD = 3;

export type PreviewUpstreamHealthOptions = {
  probeMsWhileDown?: number;
  probeMsWhileUp?: number;
  firstUnreachableCaptureAfterMs?: number;
  rerunProbeImmediatelyOnVersion?: number;
  probePath?: string | null;
  skip?: boolean;
  onPersistentUpstreamServerErrors?: (info: {
    upstreamStatus: number;
    consecutiveCount: number;
  }) => void;
};

export type PreviewUpstreamHealth = {
  isUpstreamReady: boolean;
  iframeRemountKey: number;
  probeStartedAt: number | null;
  probeAttemptCount: number;
  isFirstUnreachableWindowExceeded: boolean;
  initialProbeComplete: boolean;
  unavailableReason: UnavailableReason | null;
};

type ProbeHistory = {
  completedProbeCount: number;
  isUpstreamReady: boolean;
  unavailableReason: UnavailableReason | null;
  isFirstUnreachableWindowExceeded: boolean;
  hasCapturedFirstReady: boolean;
  hasCapturedUnreachable: boolean;
  downSince: number | null;
  everReady: boolean;
  consecutiveServerErrors: number;
  hasFiredPersistentErrorHook: boolean;
  lastUpstreamStatus: number | null;
};

type ProbeEvent =
  | {
      kind: 'persistent_server_errors';
      upstreamStatus: number;
      consecutiveCount: number;
    }
  | { kind: 'first_ready'; readyAfterMs: number }
  | { kind: 'restored' }
  | { kind: 'lost'; upstreamStatus: number | null }
  | {
      kind: 'first_unreachable';
      elapsedMs: number;
      upstreamStatus: number | null;
    };

type ProbeSession = {
  id: number;
  identity: string | null;
  startedAt: number;
};

const INITIAL_PROBE_HISTORY: ProbeHistory = {
  completedProbeCount: 0,
  isUpstreamReady: false,
  unavailableReason: 'upstream_unreachable',
  isFirstUnreachableWindowExceeded: false,
  hasCapturedFirstReady: false,
  hasCapturedUnreachable: false,
  downSince: null,
  everReady: false,
  consecutiveServerErrors: 0,
  hasFiredPersistentErrorHook: false,
  lastUpstreamStatus: null,
};

const advanceProbeHistory = ({
  history,
  outcome,
  now,
  startedAt,
  firstUnreachableCaptureAfterMs,
}: {
  history: ProbeHistory;
  outcome: ProbeOutcome;
  now: number;
  startedAt: number;
  firstUnreachableCaptureAfterMs: number;
}): { history: ProbeHistory; events: ProbeEvent[] } => {
  const events: ProbeEvent[] = [];
  const { upstreamStatus } = outcome;
  const isServerErrorResponse =
    outcome.isOk && upstreamStatus !== null && upstreamStatus >= 500;

  let consecutiveServerErrors = history.consecutiveServerErrors;
  if (isServerErrorResponse && history.everReady) {
    consecutiveServerErrors += 1;
  } else if (outcome.isOk && !isServerErrorResponse) {
    consecutiveServerErrors = 0;
  }
  const hasPersistentServerErrors =
    consecutiveServerErrors >= PERSISTENT_UPSTREAM_ERROR_THRESHOLD;

  let hasFiredPersistentErrorHook = history.hasFiredPersistentErrorHook;
  if (
    hasPersistentServerErrors &&
    !hasFiredPersistentErrorHook &&
    upstreamStatus !== null
  ) {
    hasFiredPersistentErrorHook = true;
    events.push({
      kind: 'persistent_server_errors',
      upstreamStatus,
      consecutiveCount: consecutiveServerErrors,
    });
  }

  const probed = {
    ...history,
    completedProbeCount: history.completedProbeCount + 1,
    lastUpstreamStatus: upstreamStatus,
    consecutiveServerErrors,
    hasFiredPersistentErrorHook,
  };

  if (outcome.isOk && !hasPersistentServerErrors) {
    if (!history.hasCapturedFirstReady) {
      events.push({ kind: 'first_ready', readyAfterMs: now - startedAt });
    } else if (!history.isUpstreamReady) {
      events.push({ kind: 'restored' });
    }
    return {
      history: {
        ...probed,
        everReady: probed.everReady || !isServerErrorResponse,
        hasFiredPersistentErrorHook:
          probed.hasFiredPersistentErrorHook && isServerErrorResponse,
        isUpstreamReady: true,
        unavailableReason: null,
        downSince: null,
        hasCapturedUnreachable: false,
        isFirstUnreachableWindowExceeded: false,
        hasCapturedFirstReady: true,
      },
      events,
    };
  }

  const isNewOutage = history.downSince === null;
  const downSince = history.downSince ?? now;
  let hasCapturedUnreachable = isNewOutage
    ? false
    : history.hasCapturedUnreachable;
  let isFirstUnreachableWindowExceeded = isNewOutage
    ? false
    : history.isFirstUnreachableWindowExceeded;

  if (history.isUpstreamReady) {
    events.push({ kind: 'lost', upstreamStatus });
  }

  const elapsedMs = now - downSince;
  if (elapsedMs >= firstUnreachableCaptureAfterMs && !hasCapturedUnreachable) {
    hasCapturedUnreachable = true;
    isFirstUnreachableWindowExceeded = true;
    events.push({ kind: 'first_unreachable', elapsedMs, upstreamStatus });
  }

  return {
    history: {
      ...probed,
      isUpstreamReady: false,
      unavailableReason: outcome.unavailableReason,
      downSince,
      hasCapturedUnreachable,
      isFirstUnreachableWindowExceeded,
    },
    events,
  };
};

const startProbeSession = (
  identity: string | null,
  id: number,
): ProbeSession => ({ id, identity, startedAt: Date.now() });

export const usePreviewUpstreamHealth = (
  framework: Framework,
  options: PreviewUpstreamHealthOptions = {},
): PreviewUpstreamHealth => {
  const instanceId = useId();
  const probeMsWhileDown =
    options.probeMsWhileDown ?? DEFAULT_PROBE_MS_WHILE_DOWN;
  const probeMsWhileUp = options.probeMsWhileUp ?? DEFAULT_PROBE_MS_WHILE_UP;
  const firstUnreachableCaptureAfterMs =
    options.firstUnreachableCaptureAfterMs ??
    DEFAULT_FIRST_UNREACHABLE_AFTER_MS;
  const probePath = options.probePath ?? null;
  const skip = options.skip ?? false;
  const isProbing = framework !== 'static' && !skip;
  const onPersistentUpstreamServerErrorsRef = useLatestRef(
    options.onPersistentUpstreamServerErrors,
  );

  const probeIdentity = isProbing
    ? JSON.stringify([
        framework,
        probePath,
        probeMsWhileDown,
        probeMsWhileUp,
        firstUnreachableCaptureAfterMs,
      ])
    : null;
  const [storedSession, setStoredSession] = useState(() =>
    startProbeSession(probeIdentity, 0),
  );
  const session =
    storedSession.identity === probeIdentity
      ? storedSession
      : startProbeSession(probeIdentity, storedSession.id + 1);
  if (session !== storedSession) setStoredSession(session);

  const [iframeRemountKey, setIframeRemountKey] = useState(0);
  const historyRef = useRef<{
    sessionId: number;
    history: ProbeHistory;
  } | null>(null);

  const reportProbeEvent = (event: ProbeEvent) => {
    switch (event.kind) {
      case 'persistent_server_errors':
        posthog?.capture('preview_upstream_error_responses', {
          framework,
          upstream_status: event.upstreamStatus,
          consecutive_count: event.consecutiveCount,
        });
        log.warn(
          `Preview upstream is listening but has served ${event.consecutiveCount} consecutive ${event.upstreamStatus} responses`,
        );
        onPersistentUpstreamServerErrorsRef.current?.({
          upstreamStatus: event.upstreamStatus,
          consecutiveCount: event.consecutiveCount,
        });
        return;
      case 'first_ready':
        posthog?.capture('preview_dev_server_ready', {
          framework,
          ready_after_ms: event.readyAfterMs,
        });
        return;
      case 'restored':
        posthog?.capture('preview_upstream_restored', { framework });
        return;
      case 'lost':
        posthog?.capture('preview_upstream_lost', {
          framework,
          upstream_status: event.upstreamStatus,
        });
        setIframeRemountKey((key) => key + 1);
        log.warn('Preview upstream became unavailable after it was ready');
        return;
      case 'first_unreachable':
        posthog?.capture('preview_dev_server_unreachable', {
          framework,
          elapsed_ms: event.elapsedMs,
          upstream_status: event.upstreamStatus,
        });
        log.warn('Dev server did not become ready within timeout window');
        return;
      default: {
        const unhandled: never = event;
        throw new Error(`Unhandled probe event: ${String(unhandled)}`);
      }
    }
  };

  const query = useQuery({
    queryKey: queryKeys.previewUpstreamHealth({
      instanceId,
      sessionId: session.id,
      rerunVersion: options.rerunProbeImmediatelyOnVersion ?? null,
    }),
    queryFn: async ({ signal }) => {
      const outcome = await probeUpstreamHealth(probePath);
      const previous =
        historyRef.current?.sessionId === session.id
          ? historyRef.current.history
          : INITIAL_PROBE_HISTORY;
      if (signal.aborted) return previous;
      const { history, events } = advanceProbeHistory({
        history: previous,
        outcome,
        now: Date.now(),
        startedAt: session.startedAt,
        firstUnreachableCaptureAfterMs,
      });
      historyRef.current = { sessionId: session.id, history };
      events.forEach(reportProbeEvent);
      return history;
    },
    enabled: isProbing,
    placeholderData: (previousHistory, previousQuery) =>
      previousQuery?.queryKey[1].sessionId === session.id
        ? previousHistory
        : undefined,
    refetchInterval: (probe) =>
      probe.state.data?.isUpstreamReady ? probeMsWhileUp : probeMsWhileDown,
    refetchIntervalInBackground: true,
    refetchOnWindowFocus: false,
    refetchOnReconnect: false,
    retry: false,
    gcTime: 0,
    networkMode: 'always',
  });

  if (framework === 'static') {
    return {
      isUpstreamReady: true,
      iframeRemountKey,
      probeStartedAt: null,
      probeAttemptCount: 0,
      isFirstUnreachableWindowExceeded: false,
      initialProbeComplete: true,
      unavailableReason: null,
    };
  }

  if (skip) {
    return {
      isUpstreamReady: false,
      iframeRemountKey,
      probeStartedAt: null,
      probeAttemptCount: 0,
      isFirstUnreachableWindowExceeded: false,
      initialProbeComplete: true,
      unavailableReason: 'upstream_unreachable',
    };
  }

  const history = query.data;
  return {
    isUpstreamReady: history?.isUpstreamReady ?? false,
    iframeRemountKey,
    probeStartedAt: session.startedAt,
    probeAttemptCount:
      (history?.completedProbeCount ?? 0) + (query.isFetching ? 1 : 0),
    isFirstUnreachableWindowExceeded:
      history?.isFirstUnreachableWindowExceeded ?? false,
    initialProbeComplete: history !== undefined,
    unavailableReason: history
      ? history.unavailableReason
      : 'upstream_unreachable',
  };
};
