import { useQuery } from '@tanstack/react-query';
import posthog from 'posthog-js';
import { fetchLocalApi } from '@/utils/localApi';
import { queryKeys } from '@/utils/queryKeys';
import { createLogger } from '../utils/logger';
import type { Framework } from '../types';
import { errorMessage } from '@rivet/core/utils/errorMessage';

const log = createLogger('useServerConfig');

export type { Framework };

type ServerConfig = {
  userPort: number;
  framework: Framework;
};

const CONFIG_FETCH_RETRY_DELAYS_MS = [250, 500, 1_000, 2_000, 4_000] as const;

const CONFIG_FETCH_MAX_ATTEMPTS =
  CONFIG_FETCH_RETRY_DELAYS_MS.length + 1;

const loadServerConfig = async (): Promise<ServerConfig> => {
  const response = await fetchLocalApi('/api/health');

  if (!response.ok) {
    throw new Error(`Failed to fetch config: ${response.status}`);
  }

  const healthData = await response.json();

  if (!healthData.framework) {
    throw new Error('Server did not return framework information');
  }

  return {
    userPort: healthData.ports?.userDevServer || 3000,
    framework: healthData.framework,
  };
};

const shouldRetryServerConfigLoad = (
  failureCount: number,
  error: Error,
): boolean => {
  if (failureCount < CONFIG_FETCH_RETRY_DELAYS_MS.length) {
    log.warn(
      `Server config fetch failed (attempt ${failureCount + 1}); retrying in ${CONFIG_FETCH_RETRY_DELAYS_MS[failureCount]}ms`,
      error,
    );
    return true;
  }
  log.warn('Error fetching server config:', error);
  posthog?.capture('preview_config_load_failed', {
    message: errorMessage(error, 'unknown_error'),
    attempts: CONFIG_FETCH_MAX_ATTEMPTS,
  });
  return false;
};

const serverConfigRetryDelay = (failureCount: number): number =>
  CONFIG_FETCH_RETRY_DELAYS_MS[
    Math.min(failureCount, CONFIG_FETCH_RETRY_DELAYS_MS.length - 1)
  ];

export const useServerConfig = () => {
  const query = useQuery({
    queryKey: queryKeys.serverConfig,
    queryFn: loadServerConfig,
    retry: shouldRetryServerConfigLoad,
    retryDelay: serverConfigRetryDelay,
    staleTime: Infinity,
    refetchOnWindowFocus: false,
    refetchOnReconnect: false,
    networkMode: 'always',
  });
  const isLoading = query.isFetching && !query.data;
  const { refetch } = query;

  return {
    config: query.data ?? null,
    isLoading,
    error: query.error && !isLoading ? query.error.message : null,
    retry: () => {
      void refetch();
    },
  };
};
