import { clsx, type ClassValue } from "clsx"
import { extendTailwindMerge } from "tailwind-merge"

const SURFACE_SHADOWS = Array.from({ length: 8 }, (_, index) => `surface-${index + 1}`)

const twMerge = extendTailwindMerge({
  extend: {
    theme: {
      text: ["micro", "micro-compact", "body", "title-compact", "paper-display", "heading"],
      shadow: [
        ...SURFACE_SHADOWS,
        "launcher",
        "launcher-dragging",
        "paper-card",
        "dialog",
        "panel",
        "floating",
        "control",
      ],
      radius: ["paper-card"],
      tracking: ["eyebrow", "heading", "display"],
      leading: ["brief", "display"],
    },
  },
})

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
