import {
  ProfileRuntimeSchema,
  type ProfileRuntime,
} from '@rivet/core/types/design-profile';

const STORAGE_KEY = 'rivet_launch_runtime';

interface LaunchContext {
  runtime: ProfileRuntime | null;
  isCaptured: boolean;
}

export const readLaunchContext = (): LaunchContext => {
  if (typeof window === 'undefined')
    return { runtime: null, isCaptured: false };
  const params = new URLSearchParams(window.location.search);
  const supplied = params.get('runtime');
  let stored: string | null = null;
  try {
    if (supplied !== null) {
      const parsed = ProfileRuntimeSchema.safeParse(supplied);
      if (parsed.success)
        window.sessionStorage.setItem(STORAGE_KEY, parsed.data);
      else window.sessionStorage.setItem(STORAGE_KEY, 'unknown');
    } else stored = window.sessionStorage.getItem(STORAGE_KEY);
  } catch {
    stored = null;
  }
  const parsed = ProfileRuntimeSchema.safeParse(supplied ?? stored);
  return {
    runtime: parsed.success ? parsed.data : null,
    isCaptured: supplied !== null || stored !== null,
  };
};

export const readLaunchRuntime = (): ProfileRuntime | null =>
  readLaunchContext().runtime;
