export const SHOW_PROJECTS_MESSAGE = 'rivet:show-projects';

export const readLibraryOrigin = (search: string): string | null => {
  const params = new URLSearchParams(search);
  const origin = params.get('libraryOrigin');
  if (params.get('library') !== '1' || !origin) return null;
  try {
    const url = new URL(origin);
    if (url.protocol !== 'http:' && url.protocol !== 'https:') return null;
    return url.origin;
  } catch {
    return null;
  }
};
