import { AnimatePresence, motion } from 'motion/react';
import { useCallback, useRef, useState } from 'react';
import rivetMarkUrl from '@/assets/rivet-icon-mark.svg';
import { CLOSE_RIVET_LABEL, OPEN_RIVET_LABEL } from '@/constants/rivetPanel';
import { readToggleRivetShortcut } from '@/utils/toggleRivetShortcut';
import Tooltip from './Tooltip';

export type RivetPanelLauncherPosition = {
  x: number;
  y: number;
};

type RivetPanelLauncherProps = {
  isVisible: boolean;
  isPanelOpen: boolean;
  isReducedMotion: boolean;
  position: RivetPanelLauncherPosition;
  dragBoundsLeftPx?: number;
  onToggle: () => void;
  onPositionChange: (position: RivetPanelLauncherPosition) => void;
};

type ViewportSize = {
  width: number;
  height: number;
};

type LauncherDragState = {
  startPointer: RivetPanelLauncherPosition;
  startPosition: RivetPanelLauncherPosition;
  hasMoved: boolean;
};

type LauncherMoveEvent =
  | React.PointerEvent<HTMLElement>
  | React.MouseEvent<HTMLElement>;

type LauncherStartEvent =
  | React.PointerEvent<HTMLButtonElement>
  | React.MouseEvent<HTMLButtonElement>;

const LAUNCHER_SIZE_PX = 44;
const LAUNCHER_VIEWPORT_PADDING_PX = 8;
const LAUNCHER_DEFAULT_EDGE_MARGIN_PX = 16;
const LAUNCHER_DRAG_THRESHOLD_PX = 4;
const LAUNCHER_MOTION_OFFSET_PX = -18;
const LAUNCHER_MOTION_DURATION_SECONDS = 0.18;
const LAUNCHER_MOTION_EASE = [0.22, 1, 0.36, 1] as const;
const LAUNCHER_HIDDEN_SCALE = 0.92;
const LAUNCHER_VISIBLE_SCALE = 1;
const LAUNCHER_PRESS_SCALE = 0.95;
const LAUNCHER_PRESS_DURATION_SECONDS = 0.4;
const LAUNCHER_PRESS_EASE = [0.19, 1, 0.22, 1] as const;
const LAUNCHER_HIDDEN_OPACITY = 0;
const LAUNCHER_VISIBLE_OPACITY = 1;
const LAUNCHER_VISIBLE_OFFSET_PX = 0;
const REDUCED_MOTION_DURATION_SECONDS = 0;
const PRIMARY_MOUSE_BUTTON = 0;

const clampLauncherPosition = ({
  position,
  viewport,
  boundsLeft = 0,
}: {
  position: RivetPanelLauncherPosition;
  viewport: ViewportSize;
  boundsLeft?: number;
}): RivetPanelLauncherPosition => {
  const minX = boundsLeft + LAUNCHER_VIEWPORT_PADDING_PX;
  const maxX = Math.max(
    minX,
    viewport.width - LAUNCHER_SIZE_PX - LAUNCHER_VIEWPORT_PADDING_PX,
  );
  const maxY = Math.max(
    LAUNCHER_VIEWPORT_PADDING_PX,
    viewport.height - LAUNCHER_SIZE_PX - LAUNCHER_VIEWPORT_PADDING_PX,
  );

  return {
    x: Math.min(maxX, Math.max(minX, position.x)),
    y: Math.min(maxY, Math.max(LAUNCHER_VIEWPORT_PADDING_PX, position.y)),
  };
};

const getViewportSize = (): ViewportSize => ({
  width: window.innerWidth,
  height: window.innerHeight,
});

export const clampRivetPanelLauncherPosition = ({
  position,
  boundsLeftPx = 0,
}: {
  position: RivetPanelLauncherPosition;
  boundsLeftPx?: number;
}): RivetPanelLauncherPosition =>
  clampLauncherPosition({
    position,
    viewport: getViewportSize(),
    boundsLeft: boundsLeftPx,
  });

export const getDefaultRivetPanelLauncherPosition =
  (): RivetPanelLauncherPosition => {
    if (typeof window === 'undefined') {
      return {
        x: LAUNCHER_DEFAULT_EDGE_MARGIN_PX,
        y: LAUNCHER_DEFAULT_EDGE_MARGIN_PX,
      };
    }
    const viewport = getViewportSize();
    return {
      x: viewport.width - LAUNCHER_SIZE_PX - LAUNCHER_DEFAULT_EDGE_MARGIN_PX,
      y: viewport.height - LAUNCHER_SIZE_PX - LAUNCHER_DEFAULT_EDGE_MARGIN_PX,
    };
  };

const hasPassedDragThreshold = ({
  deltaX,
  deltaY,
}: {
  deltaX: number;
  deltaY: number;
}): boolean =>
  Math.hypot(deltaX, deltaY) >= LAUNCHER_DRAG_THRESHOLD_PX;

const isPrimaryPointerDrag = (event: LauncherStartEvent): boolean =>
  event.button === undefined || event.button <= PRIMARY_MOUSE_BUTTON;

const getEventPosition = (
  event: LauncherMoveEvent,
): RivetPanelLauncherPosition => {
  const nativeEvent = event.nativeEvent as MouseEvent | PointerEvent;
  return {
    x: Number.isFinite(event.clientX) ? event.clientX : nativeEvent.clientX,
    y: Number.isFinite(event.clientY) ? event.clientY : nativeEvent.clientY,
  };
};

const RivetPanelLauncher = ({
  isVisible,
  isPanelOpen,
  isReducedMotion,
  position,
  dragBoundsLeftPx = 0,
  onToggle,
  onPositionChange,
}: RivetPanelLauncherProps) => {
  const dragStateRef = useRef<LauncherDragState | null>(null);
  const shouldSuppressClickRef = useRef(false);
  const [isDraggingLauncher, setIsDraggingLauncher] = useState(false);
  const [isLauncherHovered, setIsLauncherHovered] = useState(false);
  const [isLauncherFocusVisible, setIsLauncherFocusVisible] = useState(false);
  const initialMotion = isReducedMotion
    ? false
    : {
        opacity: LAUNCHER_HIDDEN_OPACITY,
        scale: LAUNCHER_HIDDEN_SCALE,
        x: LAUNCHER_MOTION_OFFSET_PX,
      };
  const exitMotion = isReducedMotion
    ? { opacity: LAUNCHER_HIDDEN_OPACITY }
    : {
        opacity: LAUNCHER_HIDDEN_OPACITY,
        scale: LAUNCHER_HIDDEN_SCALE,
        x: LAUNCHER_MOTION_OFFSET_PX,
      };
  const motionTransition = isReducedMotion
    ? { duration: REDUCED_MOTION_DURATION_SECONDS }
    : {
        duration: LAUNCHER_MOTION_DURATION_SECONDS,
        ease: LAUNCHER_MOTION_EASE,
        scale: {
          duration: LAUNCHER_PRESS_DURATION_SECONDS,
          ease: LAUNCHER_PRESS_EASE,
        },
      };

  const endLauncherDrag = useCallback(() => {
    const dragState = dragStateRef.current;
    if (dragState) {
      shouldSuppressClickRef.current = dragState.hasMoved;
    }
    dragStateRef.current = null;
    setIsDraggingLauncher(false);
  }, []);

  const moveLauncher = useCallback(
    (event: LauncherMoveEvent) => {
      const dragState = dragStateRef.current;
      if (!dragState) {
        return;
      }

      const eventPosition = getEventPosition(event);
      const deltaX = eventPosition.x - dragState.startPointer.x;
      const deltaY = eventPosition.y - dragState.startPointer.y;
      const hasMoved =
        dragState.hasMoved || hasPassedDragThreshold({ deltaX, deltaY });

      dragStateRef.current = {
        ...dragState,
        hasMoved,
      };

      if (!hasMoved) {
        return;
      }

      onPositionChange(
        clampLauncherPosition({
          position: {
            x: dragState.startPosition.x + deltaX,
            y: dragState.startPosition.y + deltaY,
          },
          viewport: getViewportSize(),
          boundsLeft: dragBoundsLeftPx,
        }),
      );
    },
    [onPositionChange, dragBoundsLeftPx],
  );

  const startLauncherDrag = useCallback(
    (event: LauncherStartEvent) => {
      if (dragStateRef.current) {
        return;
      }

      if (!isPrimaryPointerDrag(event)) {
        return;
      }

      const startPointer = getEventPosition(event);
      dragStateRef.current = {
        startPointer,
        startPosition: position,
        hasMoved: false,
      };
      setIsDraggingLauncher(true);
    },
    [position],
  );

  const handleLauncherClick = useCallback(() => {
    if (shouldSuppressClickRef.current) {
      shouldSuppressClickRef.current = false;
      return;
    }

    onToggle();
  }, [onToggle]);

  const toggleLabel = isPanelOpen ? CLOSE_RIVET_LABEL : OPEN_RIVET_LABEL;
  const toggleShortcut = readToggleRivetShortcut();
  const isTooltipAllowed =
    !isDraggingLauncher && (isLauncherHovered || isLauncherFocusVisible);

  return (
    <>
      {isDraggingLauncher ? (
        <div
          className="z-ui-secondary fixed inset-0 cursor-grabbing"
          data-cy="rivet-panel-launcher-drag-surface"
          onPointerMove={moveLauncher}
          onPointerUp={endLauncherDrag}
          onPointerCancel={endLauncherDrag}
          onMouseMove={moveLauncher}
          onMouseUp={endLauncherDrag}
        />
      ) : null}
      <AnimatePresence>
        {isVisible ? (
          <Tooltip
            label={toggleLabel}
            side="top"
            forceOpen={isTooltipAllowed ? undefined : false}
          >
            <motion.button
              type="button"
              aria-label={toggleLabel}
              aria-keyshortcuts={toggleShortcut.ariaKeyShortcuts}
              data-cy="reopen-panel"
              onMouseEnter={() => setIsLauncherHovered(true)}
              onMouseLeave={() => setIsLauncherHovered(false)}
              onFocus={(event) =>
                setIsLauncherFocusVisible(
                  event.currentTarget.matches(':focus-visible'),
                )
              }
              onBlur={() => setIsLauncherFocusVisible(false)}
              initial={initialMotion}
              animate={{
                opacity: LAUNCHER_VISIBLE_OPACITY,
                scale: LAUNCHER_VISIBLE_SCALE,
                x: LAUNCHER_VISIBLE_OFFSET_PX,
              }}
              whileTap={{ scale: LAUNCHER_PRESS_SCALE }}
              exit={exitMotion}
              transition={motionTransition}
              onPointerDown={startLauncherDrag}
              onMouseDown={startLauncherDrag}
              onPointerMove={moveLauncher}
              onPointerUp={endLauncherDrag}
              onPointerCancel={endLauncherDrag}
              onMouseMove={moveLauncher}
              onMouseUp={endLauncherDrag}
              onClick={handleLauncherClick}
              className={`bg-background z-ui-primary absolute flex h-11 w-11 touch-none items-center justify-center overflow-hidden rounded-full border border-border shadow-launcher focus-visible:outline-hidden transition-[background-color,border-color,box-shadow] duration-150 select-none hover:bg-surface-3 focus-visible:border-border-focus focus-visible:bg-surface-3 ${
                isDraggingLauncher
                  ? 'cursor-grabbing shadow-launcher-dragging'
                  : 'cursor-grab'
              }`}
              style={{
                left: position.x,
                top: position.y,
                willChange: 'left, top, transform',
              }}
            >
              <span
                aria-hidden="true"
                className="bg-foreground h-4 w-4"
                style={{
                  WebkitMaskImage: `url("${rivetMarkUrl}")`,
                  maskImage: `url("${rivetMarkUrl}")`,
                  WebkitMaskSize: 'contain',
                  maskSize: 'contain',
                  WebkitMaskRepeat: 'no-repeat',
                  maskRepeat: 'no-repeat',
                  WebkitMaskPosition: 'center',
                  maskPosition: 'center',
                }}
              />
            </motion.button>
          </Tooltip>
        ) : null}
      </AnimatePresence>
    </>
  );
};

export default RivetPanelLauncher;
