import { ArrowUp, CircleNotch } from '@phosphor-icons/react';
import { useCallback, useState } from 'react';
import { usePostHog } from 'posthog-js/react';
import { toast } from 'sonner';
import { createLogger } from '../utils/logger';
import { fetchLocalApi } from '@/utils/localApi';
import Button from './Button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
} from '@/components/Dialog';
import { errorMessage } from '@rivet/core/utils/errorMessage';
import {
  SupportTicketErrorResponseSchema,
  type SupportTicketErrorResponse,
} from '@rivet/core/types/api-responses';

const log = createLogger('SupportTicketModal');

type SupportTicketModalProps = {
  isOpen: boolean;
  onClose: () => void;
  contactEmail?: string;
};

const MESSAGE_MAX_LENGTH = 5000;
const DEFAULT_TICKET_TYPE = 'feedback';

type ValidationDetails = Exclude<
  SupportTicketErrorResponse['details'],
  string | undefined
>;

const extractValidationMessage = (
  details?: ValidationDetails,
): string | null => {
  if (!details) return null;

  const formError = details.formErrors?.[0];
  if (formError) {
    return formError;
  }

  const fieldErrors = details.fieldErrors ?? {};
  for (const fieldErrorList of Object.values(fieldErrors)) {
    const firstFieldError = fieldErrorList?.[0];
    if (firstFieldError) {
      return firstFieldError;
    }
  }

  return null;
};

const parseSupportTicketError = async (response: Response): Promise<string> => {
  let data: SupportTicketErrorResponse | undefined;

  try {
    const parsed = SupportTicketErrorResponseSchema.safeParse(
      await response.json(),
    );
    data = parsed.success ? parsed.data : undefined;
  } catch {
    data = undefined;
  }

  if (response.status === 400) {
    if (typeof data?.details === 'string' && data.details.trim()) {
      return data.details;
    }

    if (typeof data?.details === 'object' && data.details !== null) {
      const validationMessage = extractValidationMessage(data.details);
      if (validationMessage) {
        return validationMessage;
      }
    }

    return 'Please check your feedback and try again.';
  }

  if (response.status >= 500) {
    if (typeof data?.details === 'string' && data.details.trim()) {
      return data.details;
    }

    return 'Could not send feedback right now. Please try again later.';
  }

  if (typeof data?.error === 'string' && data.error.trim()) {
    return data.error;
  }

  return `HTTP ${response.status}`;
};

const SupportTicketModal = ({
  isOpen,
  onClose,
  contactEmail,
}: SupportTicketModalProps) => {
  const posthog = usePostHog();
  const [message, setMessage] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const resetForm = useCallback(() => {
    setMessage('');
  }, []);

  const handleClose = useCallback(() => {
    if (isSubmitting) return;
    resetForm();
    onClose();
  }, [isSubmitting, onClose, resetForm]);

  const handleSubmit = useCallback(async () => {
    const trimmedMessage = message.trim();
    if (!trimmedMessage || isSubmitting) {
      return;
    }

    setIsSubmitting(true);
    try {
      const posthogSessionId =
        typeof posthog?.get_session_id === 'function'
          ? posthog.get_session_id()
          : undefined;
      const posthogDistinctId =
        typeof posthog?.get_distinct_id === 'function'
          ? posthog.get_distinct_id()
          : undefined;
      const normalizedContactEmail = contactEmail?.trim();

      const response = await fetchLocalApi('/api/support/tickets', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: DEFAULT_TICKET_TYPE,
          message: trimmedMessage,
          contactEmail: normalizedContactEmail || undefined,
          metadata: {
            posthogSessionId: posthogSessionId ?? undefined,
            posthogDistinctId: posthogDistinctId ?? undefined,
            appVersion: __RIVET_VERSION__,
            appEnvironment: import.meta.env.MODE,
            pageUrl: window.location.href,
            userAgent: navigator.userAgent,
            submittedAt: new Date().toISOString(),
          },
        }),
      });

      if (!response.ok) {
        const parsedMessage = await parseSupportTicketError(response);
        throw new Error(parsedMessage);
      }

      posthog?.capture('support_ticket_submitted', {
        ticket_type: DEFAULT_TICKET_TYPE,
        has_posthog_session_id: Boolean(posthogSessionId),
      });
      toast.success('Feedback sent', {
        description: 'Thanks for sharing this.',
      });
      resetForm();
      onClose();
    } catch (error) {
      const messageText = errorMessage(error, 'Failed to send message');
      posthog?.capture('support_ticket_submit_failed', {
        ticket_type: DEFAULT_TICKET_TYPE,
        error: messageText,
      });
      log.error('Failed to submit support ticket:', messageText);
      toast.error('Could not send feedback', {
        description: messageText,
      });
    } finally {
      setIsSubmitting(false);
    }
  }, [contactEmail, isSubmitting, message, onClose, posthog, resetForm]);

  const handleKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLTextAreaElement>) => {
      if (event.key === 'Enter' && (event.metaKey || event.ctrlKey)) {
        event.preventDefault();
        handleSubmit();
      }
    },
    [handleSubmit],
  );

  const remainingCharacters = MESSAGE_MAX_LENGTH - message.length;
  const isSubmitDisabled = isSubmitting || message.trim().length === 0;

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && handleClose()}>
      <DialogContent size="md">
        <DialogHeader onClose={handleClose} isCloseDisabled={isSubmitting}>
          Send feedback
        </DialogHeader>

        <div className="flex flex-col gap-3 p-4">
          <DialogDescription className="text-muted-foreground text-sm">
            Tell us what happened or what we can improve.
          </DialogDescription>

          <div className="bg-muted rounded-lg border border-transparent transition-colors focus-within:border-soft-foreground forced-colors:focus-within:outline-2 forced-colors:focus-within:outline-solid">
            <textarea
              id="support-ticket-message"
              aria-label="Your feedback"
              value={message}
              onChange={(event) => setMessage(event.target.value)}
              onKeyDown={handleKeyDown}
              maxLength={MESSAGE_MAX_LENGTH}
              rows={6}
              disabled={isSubmitting}
              placeholder="What happened?"
              className="text-foreground placeholder-muted-foreground max-h-64 w-full resize-none overflow-y-auto bg-transparent pt-3 pr-3 pb-1 pl-3 text-sm focus:outline-none disabled:opacity-50"
            />
            <div className="flex items-center justify-between px-3 pt-1 pb-3">
              <span className="text-muted-foreground text-xs">
                Context details are included automatically.
              </span>
              <div className="flex items-center gap-2">
                {remainingCharacters <= 500 && (
                  <span className="text-muted-foreground text-xs">
                    {remainingCharacters}
                  </span>
                )}
                <Button
                  onClick={handleSubmit}
                  disabled={isSubmitDisabled}
                  title="Send feedback"
                  shortcut="⌘↵"
                  aria-label="Send feedback"
                  variant="primary"
                  size="icon-compact"
                >
                  {isSubmitting ? (
                    <CircleNotch
                      className="h-5 w-5 animate-spin"
                      weight="bold"
                    />
                  ) : (
                    <ArrowUp className="h-5 w-5" weight="bold" />
                  )}
                </Button>
              </div>
            </div>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default SupportTicketModal;
