import type { AgentApplyMode } from './previewSandbox';

export const getPreviewOrigin = (_agentApplyMode: AgentApplyMode): string => {
  if (typeof window === 'undefined') {
    return '';
  }
  const previewOrigin = window.__RIVET_BOOTSTRAP__?.previewOrigin;
  if (previewOrigin) return previewOrigin;
  const fallback = new URL(window.location.origin);
  fallback.hostname = 'localhost';
  return fallback.origin;
};

export const resolvePreviewSrc = ({
  agentApplyMode,
  url,
}: {
  agentApplyMode: AgentApplyMode;
  url: string;
}): string => {
  if (!url.startsWith('/')) return url;
  return `${getPreviewOrigin(agentApplyMode)}${url}`;
};
