import { useQuery } from '@tanstack/react-query';
import { DesignLibraryEntriesResponseSchema } from '@rivet/core/types/api-responses';
import { fetchLocalApi } from '@/utils/localApi';
import { queryKeys } from '@/utils/queryKeys';

const ENTRY_LOOKUP_STALE_MS = 60_000;
const NO_ENTRY_URLS: ReadonlyMap<string, string> = new Map();

const fetchDesignLibraryEntryUrls = async ({
  referenceIds,
  signal,
}: {
  referenceIds: readonly string[];
  signal: AbortSignal;
}): Promise<ReadonlyMap<string, string>> => {
  const query = new URLSearchParams(
    referenceIds.map((referenceId) => ['referenceId', referenceId]),
  );
  const response = await fetchLocalApi(
    `/api/reference-profiles/library-entries?${query}`,
    { signal },
  );
  if (!response.ok)
    throw new Error(`Design library lookup failed (HTTP ${response.status})`);
  const { entries } = DesignLibraryEntriesResponseSchema.parse(
    await response.json(),
  );
  return new Map(entries.map(({ referenceId, url }) => [referenceId, url]));
};

export const useDesignLibraryEntryUrls = (
  referenceIds: readonly string[],
): ReadonlyMap<string, string> => {
  const lookup = useQuery({
    queryKey: queryKeys.designLibraryEntries(referenceIds),
    queryFn: ({ signal }) =>
      fetchDesignLibraryEntryUrls({ referenceIds, signal }),
    enabled: referenceIds.length > 0,
    staleTime: ENTRY_LOOKUP_STALE_MS,
    retry: false,
  });
  return lookup.data ?? NO_ENTRY_URLS;
};
