import { useRef, useState, type FormEvent } from 'react';
import { useMutation } from '@tanstack/react-query';
import { toast } from 'sonner';
import { usePostHog } from 'posthog-js/react';
import { useAtomValue } from 'jotai';
import { mcpEditorAtom } from '@/store/atoms';
import {
  ProfileRuntimeSchema,
  type ProfileRuntime,
} from '@rivet/core/types/design-profile';
import { parseCosmosProfileUrl } from '@rivet/core/types/cosmos';
import type { ReferenceImportPlanSummary } from '@rivet/core/types/api-responses';
import {
  type ReferenceProvider,
  type AuthenticatedReferenceProvider,
} from '@rivet/core/types/reference-connectors';
import Button from '@/components/Button';
import TextInput from '@/components/TextInput';
import ReferenceProviderIcon from '@/components/ReferenceProviderIcon';
import { Dialog, DialogContent, DialogHeader } from '@/components/Dialog';
import {
  enableReferenceProfile,
  getReferenceProfileStatus,
  approveReferenceImport,
  prepareReferenceImport,
} from '@/hooks/useReferenceProfile';
import { errorMessage } from '@rivet/core/utils/errorMessage';
import { useReferenceDiscovery } from '@/hooks/useReferenceDiscovery';
import { useAuthorizationLink } from '@/hooks/authorizationLink';
import AuthorizationLinkNotice from '@/components/AuthorizationLinkNotice';

type ReferenceImportModalProps = {
  isOpen: boolean;
  onClose: () => void;
  onImported: () => void;
} & (
  | { provider: 'cosmos' }
  | {
      provider: AuthenticatedReferenceProvider;
      onReconnect: () => Promise<boolean>;
    }
);

interface ReferenceImportApproval {
  plan: ReferenceImportPlanSummary;
  runtime: ProfileRuntime;
}

const PROVIDERS: Record<
  ReferenceProvider,
  { name: string; collection: string; collections: string }
> = {
  cosmos: {
    name: 'Cosmos',
    collection: 'collection',
    collections: 'collections',
  },
  pinterest: { name: 'Pinterest', collection: 'board', collections: 'boards' },
  arena: { name: 'Are.na', collection: 'channel', collections: 'channels' },
  x: { name: 'X', collection: 'collection', collections: 'collections' },
};

const ReferenceImport = (props: ReferenceImportModalProps) => {
  const { isOpen, onClose, onImported, provider } = props;
  const providerMeta = PROVIDERS[provider];
  const [url, setUrl] = useState('');
  const [profileUrl, setProfileUrl] = useState<string | null>(null);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const editor = useAtomValue(mcpEditorAtom);
  const launchRuntime = ProfileRuntimeSchema.safeParse(editor);
  const runtime = launchRuntime.success ? launchRuntime.data : null;
  const [approval, setApproval] = useState<ReferenceImportApproval | null>(
    null,
  );
  const plan = approval?.plan ?? null;
  const [error, setError] = useState<string | null>(null);
  const [isPending, setIsPending] = useState(false);
  const requestId = useRef(0);
  const posthog = usePostHog();
  const { authorizationLink } = useAuthorizationLink();
  const activeAuthorization =
    authorizationLink?.provider === provider ? authorizationLink : null;
  const importMutation = useMutation({
    mutationFn: async ({
      plan: approvedPlan,
      runtime: approvedRuntime,
    }: ReferenceImportApproval) => {
      const status = await getReferenceProfileStatus();
      if (!status.profile.isEnabled)
        await enableReferenceProfile(approvedRuntime);
      await approveReferenceImport(approvedPlan);
    },
    onSuccess: (_result, { plan: approvedPlan }) => {
      posthog?.capture('visual_editor_reference_import_accepted', {
        provider,
        reference_count: approvedPlan.referenceCount,
      });
      onImported();
      toast.success('Import queued', {
        description: 'Check References as your import is processed.',
      });
    },
    onError: () =>
      posthog?.capture('visual_editor_reference_import_failed', { provider }),
  });
  const discoveryQuery = useReferenceDiscovery(provider, profileUrl);
  const discoveryResult = discoveryQuery.data;
  const discovery =
    discoveryResult && !('status' in discoveryResult) ? discoveryResult : null;
  const isAuthorizationRequired = Boolean(
    discoveryQuery.isSuccess && discoveryResult && 'status' in discoveryResult,
  );
  const isBusy =
    isPending || discoveryQuery.isFetching || importMutation.isPending;
  const discoveryError = discoveryQuery.error
    ? errorMessage(
        discoveryQuery.error,
        `Could not find ${providerMeta.collections}`,
      )
    : null;
  const authorizationError = isAuthorizationRequired
    ? `Reconnect ${providerMeta.name} to choose your ${providerMeta.collections}.`
    : null;
  const visibleError = error ?? discoveryError ?? authorizationError;

  const reset = () => {
    requestId.current += 1;
    setUrl('');
    setProfileUrl(null);
    setSelectedIds([]);
    setApproval(null);
    setError(null);
    setIsPending(false);
    importMutation.reset();
  };

  const handleClose = () => {
    posthog?.capture('visual_editor_reference_import_modal_closed', {
      provider,
    });
    reset();
    onClose();
  };

  const handleDiscover = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setError(null);
    try {
      const selectedUrl = parseCosmosProfileUrl(url.trim()).url;
      if (profileUrl === selectedUrl) await discoveryQuery.refetch();
      else setProfileUrl(selectedUrl);
    } catch (cause) {
      setError(errorMessage(cause, 'Invalid Cosmos profile URL'));
    }
  };

  const handleReconnect = async () => {
    if (props.provider === 'cosmos') return;
    const currentRequest = ++requestId.current;
    setError(null);
    setIsPending(true);
    try {
      const isConnected = await props.onReconnect();
      if (currentRequest !== requestId.current) return;
      if (isConnected) await discoveryQuery.refetch();
      else setError('Connection was not completed. Try again.');
    } catch (cause) {
      if (currentRequest === requestId.current)
        setError(errorMessage(cause, 'Could not reconnect. Try again.'));
    } finally {
      if (currentRequest === requestId.current) setIsPending(false);
    }
  };

  const handlePlan = async () => {
    if (!discovery || selectedIds.length === 0 || !runtime) return;
    setError(null);
    posthog?.capture('visual_editor_reference_plan_started', {
      provider,
      collection_count: selectedIds.length,
      runtime,
    });
    const currentRequest = ++requestId.current;
    setIsPending(true);
    try {
      const result = await prepareReferenceImport({
        discoveryId: discovery.id,
        collectionIds: selectedIds,
        runtime,
      });
      if (currentRequest !== requestId.current) return;
      setApproval({ plan: result, runtime });
      posthog?.capture('visual_editor_reference_plan_completed', {
        provider,
        collection_count: result.collectionCount,
        reference_count: result.referenceCount,
      });
    } catch (cause) {
      if (currentRequest !== requestId.current) return;
      setError(errorMessage(cause, 'Could not prepare import plan'));
      posthog?.capture('visual_editor_reference_plan_failed', { provider });
    } finally {
      if (currentRequest === requestId.current) setIsPending(false);
    }
  };

  const handleImport = () => {
    if (!approval) return;
    const approvedPlan = approval.plan;
    setError(null);
    posthog?.capture('visual_editor_reference_import_started', {
      provider,
      collection_count: approvedPlan.collectionCount,
      reference_count: approvedPlan.referenceCount,
    });
    importMutation.mutate(approval, {
      onSuccess: () => {
        reset();
        onClose();
      },
      onError: (cause) =>
        setError(errorMessage(cause, 'Could not start import')),
    });
  };

  const toggleCollection = (id: string) => {
    setSelectedIds((current) =>
      current.includes(id)
        ? current.filter((selected) => selected !== id)
        : [...current, id],
    );
    setApproval(null);
    posthog?.capture('visual_editor_reference_collection_toggled', {
      provider,
    });
  };

  return (
    <Dialog
      open={isOpen}
      onOpenChange={(isDialogOpen) => {
        if (!isDialogOpen) handleClose();
      }}
    >
      <DialogContent
        size="md"
        aria-describedby={undefined}
        onCloseAutoFocus={() => {
          requestId.current += 1;
        }}
        className="max-h-[min(680px,calc(100vh-32px))] overflow-y-auto"
      >
        <DialogHeader onClose={handleClose}>
          <span className="flex items-center gap-2">
            <ReferenceProviderIcon
              provider={provider}
              className="size-5 flex-none"
            />
            <span>Import from {providerMeta.name}</span>
          </span>
        </DialogHeader>
        <div className="space-y-4 p-4">
          {activeAuthorization ? (
            <AuthorizationLinkNotice authUrl={activeAuthorization.authUrl} />
          ) : null}
          {!discovery && provider === 'cosmos' ? (
            <form
              onSubmit={(event) => void handleDiscover(event)}
              className="space-y-4"
            >
              <label
                className="text-foreground block text-sm font-medium"
                htmlFor="cosmos-profile-url"
              >
                Cosmos profile URL
              </label>
              <TextInput
                id="cosmos-profile-url"
                type="url"
                required
                autoFocus
                value={url}
                onChange={(event) => setUrl(event.target.value)}
                placeholder="https://www.cosmos.so/username"
              />
              <Button type="submit" variant="secondary" disabled={isBusy}>
                {discoveryQuery.isFetching
                  ? 'Finding collections…'
                  : 'Find collections'}
              </Button>
            </form>
          ) : null}

          {!discovery && provider !== 'cosmos' ? (
            <div className="space-y-3">
              {isBusy || !visibleError ? (
                <p role="status" className="text-muted-foreground text-sm">
                  Finding {providerMeta.collections}…
                </p>
              ) : null}
              {visibleError ? (
                <Button
                  variant="secondary"
                  disabled={isBusy}
                  onClick={() => {
                    if (isAuthorizationRequired) void handleReconnect();
                    else void discoveryQuery.refetch();
                  }}
                >
                  {isAuthorizationRequired
                    ? `Reconnect ${providerMeta.name}`
                    : 'Try again'}
                </Button>
              ) : null}
            </div>
          ) : null}

          {discovery ? (
            <div className="space-y-4">
              <p className="text-foreground text-sm font-medium">
                Choose {providerMeta.collections} from{' '}
                {discovery.profile.title || discovery.profile.username}
              </p>
              {discovery.collections.length > 0 ? (
                <div className="border-separator has-[:focus-visible]:border-soft-foreground max-h-60 divide-y overflow-y-auto rounded-md border transition-colors motion-reduce:transition-none">
                  {discovery.collections.map((collection) => (
                    <label
                      key={collection.id}
                      className="text-foreground hover:bg-card has-[:focus-visible]:bg-active flex cursor-pointer items-center gap-3 px-3 py-2 text-sm transition-colors motion-reduce:transition-none"
                    >
                      <input
                        type="checkbox"
                        className="focus-visible:outline-hidden"
                        checked={selectedIds.includes(collection.id)}
                        disabled={isBusy || plan !== null}
                        onChange={() => toggleCollection(collection.id)}
                      />
                      <span className="min-w-0 flex-1 truncate">
                        {collection.title}
                      </span>
                    </label>
                  ))}
                </div>
              ) : null}
              {discovery.collections.length === 0 ? (
                <p className="text-soft-foreground text-sm">
                  No {providerMeta.collections} available to import from this
                  profile.
                </p>
              ) : null}
              {discovery.collections.length > 0 && !plan ? (
                <>
                  <p className="text-soft-foreground text-xs" role="status">
                    {selectedIds.length === 0
                      ? 'Select content to continue.'
                      : `${selectedIds.length} selected`}
                    {!runtime
                      ? ' Open Rivet from Codex, Claude, or Cursor to import references.'
                      : null}
                  </p>
                  <div className="flex items-center gap-2">
                    <Button
                      variant="secondary"
                      onClick={() => void handlePlan()}
                      disabled={isBusy || selectedIds.length === 0 || !runtime}
                    >
                      {isPending ? 'Preparing plan…' : 'Review selection'}
                    </Button>
                    <Button
                      variant="ghost"
                      onClick={() => {
                        if (provider === 'cosmos') {
                          posthog?.capture(
                            'visual_editor_reference_profile_changed',
                            { provider },
                          );
                          reset();
                        } else handleClose();
                      }}
                      disabled={isBusy}
                    >
                      {provider === 'cosmos' ? 'Use another profile' : 'Back'}
                    </Button>
                  </div>
                </>
              ) : null}
              {discovery.collections.length === 0 ? (
                <Button
                  variant="ghost"
                  onClick={() => {
                    if (provider === 'cosmos') reset();
                    else handleClose();
                  }}
                >
                  {provider === 'cosmos' ? 'Use another profile' : 'Back'}
                </Button>
              ) : null}
            </div>
          ) : null}

          {plan ? (
            <div className="space-y-4 text-sm">
              <p className="text-foreground">
                {plan.collectionCount}{' '}
                {plan.collectionCount === 1
                  ? providerMeta.collection
                  : providerMeta.collections}{' '}
                · {plan.referenceCount}{' '}
                {plan.referenceCount === 1 ? 'reference' : 'references'}
              </p>
              <div className="flex items-center gap-2">
                <Button
                  variant="secondary"
                  onClick={() => void handleImport()}
                  disabled={isBusy}
                >
                  {importMutation.isPending
                    ? 'Starting import…'
                    : `Import ${plan.referenceCount} ${plan.referenceCount === 1 ? 'reference' : 'references'}`}
                </Button>
                <Button
                  variant="ghost"
                  onClick={() => {
                    posthog?.capture('visual_editor_reference_plan_revised', {
                      provider,
                    });
                    setApproval(null);
                    setError(null);
                  }}
                  disabled={isBusy}
                >
                  Edit selection
                </Button>
              </div>
            </div>
          ) : null}

          {visibleError ? (
            <p role="alert" className="text-muted-foreground text-sm">
              {visibleError}
            </p>
          ) : null}
        </div>
      </DialogContent>
    </Dialog>
  );
};

const ReferenceImportModal = (props: ReferenceImportModalProps) =>
  props.isOpen ? <ReferenceImport key={props.provider} {...props} /> : null;

export default ReferenceImportModal;
