import * as Popover from '@radix-ui/react-popover';
import {
  createContext,
  forwardRef,
  useContext,
  type ComponentPropsWithoutRef,
  type ReactNode,
} from 'react';
import { useMenuListNavigation } from '@/hooks/useMenuListNavigation';
import { cn } from '@/lib/utils';

const MENU_SURFACE_CLASSES =
  'bg-popover text-popover-foreground shadow-surface-4 z-max min-w-40 rounded-lg p-1';
const MENU_ITEM_CLASSES =
  'text-soft-foreground hover:bg-hover hover:text-foreground focus-visible:bg-active focus-visible:text-foreground flex w-full items-center gap-2 rounded-md px-3 py-1.5 text-left text-xs focus-visible:outline-hidden transition-colors duration-80 disabled:cursor-not-allowed disabled:opacity-50';
const MENU_SIDE_OFFSET = 4;

type MenuProps = {
  isOpen: boolean;
  onOpenChange: (isOpen: boolean) => void;
  children: ReactNode;
};

type MenuContentProps = Omit<
  ComponentPropsWithoutRef<typeof Popover.Content>,
  'role' | 'onKeyDown'
>;

type MenuItemProps = Omit<
  ComponentPropsWithoutRef<'button'>,
  'role' | 'type' | 'onSelect' | 'aria-checked'
> & {
  onSelect?: () => void;
  isChecked?: boolean;
};

const MenuOpenChangeContext = createContext<(isOpen: boolean) => void>(
  () => {},
);

const Menu = ({ isOpen, onOpenChange, children }: MenuProps) => (
  <MenuOpenChangeContext.Provider value={onOpenChange}>
    <Popover.Root open={isOpen} onOpenChange={onOpenChange}>
      {children}
    </Popover.Root>
  </MenuOpenChangeContext.Provider>
);

const MenuTrigger = forwardRef<
  HTMLButtonElement,
  ComponentPropsWithoutRef<typeof Popover.Trigger>
>((props, ref) => (
  <Popover.Trigger ref={ref} {...props} aria-haspopup="menu" />
));
MenuTrigger.displayName = 'MenuTrigger';

const MenuContent = ({
  className,
  sideOffset = MENU_SIDE_OFFSET,
  onCloseAutoFocus,
  ...props
}: MenuContentProps) => {
  const onOpenChange = useContext(MenuOpenChangeContext);
  const {
    containerRef,
    onKeyDown,
    onCloseAutoFocus: onNavigationCloseAutoFocus,
  } = useMenuListNavigation<HTMLDivElement>({
    onDismiss: () => onOpenChange(false),
  });
  return (
    <Popover.Portal>
      <Popover.Content
        {...props}
        sideOffset={sideOffset}
        className={cn(MENU_SURFACE_CLASSES, className)}
        ref={containerRef}
        role="menu"
        onKeyDown={onKeyDown}
        onCloseAutoFocus={(event) => {
          onCloseAutoFocus?.(event);
          onNavigationCloseAutoFocus(event);
        }}
      />
    </Popover.Portal>
  );
};

const MenuItem = forwardRef<HTMLButtonElement, MenuItemProps>(
  ({ className, onClick, onSelect, isChecked, ...props }, ref) => {
    const onOpenChange = useContext(MenuOpenChangeContext);
    return (
      <button
        ref={ref}
        type="button"
        {...props}
        onClick={(event) => {
          onClick?.(event);
          if (!onSelect) return;
          onOpenChange(false);
          onSelect();
        }}
        className={cn(MENU_ITEM_CLASSES, className)}
        role={isChecked === undefined ? 'menuitem' : 'menuitemradio'}
        aria-checked={isChecked}
        data-menu-item
      />
    );
  },
);
MenuItem.displayName = 'MenuItem';

const MenuControl = (props: ComponentPropsWithoutRef<'div'>) => (
  <div {...props} data-menu-control />
);

export { Menu, MenuContent, MenuControl, MenuItem, MenuTrigger };
