import type { z } from 'zod';
import { ErrorResponseSchema } from '@rivet/core/types/api-responses';
import { browserSessionToken } from '@/library/browserSession';

export type ResponseSchema<T> = z.ZodType<T, unknown>;

interface RequestOptions<T> {
  schema: ResponseSchema<T>;
  method?: 'GET' | 'POST' | 'PATCH' | 'PUT' | 'DELETE';
  body?: unknown;
  signal?: AbortSignal;
}
const INVALID_RESPONSE_MESSAGE = 'The library returned an invalid response.';
const TOKEN_KEY = 'rivet_library_token';
let activeToken = '';
let sessionRevision = 0;
let storageError: string | null = null;
let linkError: string | null = null;
let isListeningToStorage = false;
const sessionListeners = new Set<() => void>();
const notifySession = (): void =>
  sessionListeners.forEach((listener) => listener());

export const libraryAuthorization = (): string => `Bearer ${activeToken}`;
export const librarySessionError = (): string | null =>
  storageError ?? linkError;
export const librarySessionRevision = (): number => sessionRevision;

const loadSession = (): void => {
  try {
    const token = window.localStorage.getItem(TOKEN_KEY) ?? '';
    if (activeToken !== token) sessionRevision += 1;
    activeToken = token;
    storageError = null;
  } catch {
    storageError =
      'Rivet cannot access browser storage. Allow site storage and try again.';
  }
};

const listenToStorage = (): void => {
  if (isListeningToStorage) return;
  window.addEventListener('storage', (event) => {
    if (event.key !== TOKEN_KEY && event.key !== null) return;
    loadSession();
    notifySession();
  });
  isListeningToStorage = true;
};

export const hasLibrarySession = (): boolean => Boolean(activeToken);
export const subscribeLibrarySession = (listener: () => void): (() => void) => {
  listenToStorage();
  sessionListeners.add(listener);
  return () => sessionListeners.delete(listener);
};

export const saveLibrarySession = (
  token: string,
  expectedRevision?: number,
): void => {
  if (expectedRevision !== undefined) loadSession();
  if (expectedRevision !== undefined && expectedRevision !== sessionRevision)
    throw new Error('Sign-in was cancelled because the browser login changed.');
  try {
    window.localStorage.setItem(TOKEN_KEY, token);
  } catch {
    storageError =
      'Rivet cannot save browser access. Allow site storage and try again.';
    notifySession();
    throw new Error(storageError);
  }
  activeToken = token;
  sessionRevision += 1;
  storageError = null;
  linkError = null;
  notifySession();
};

export const clearLibrarySession = (): void => {
  activeToken = '';
  sessionRevision += 1;
  storageError = null;
  try {
    window.localStorage.removeItem(TOKEN_KEY);
  } catch {
    storageError =
      'Rivet cannot clear browser storage. Allow site storage and try again.';
  }
  notifySession();
};

export const captureLibraryToken = async (): Promise<void> => {
  if (!window.location.pathname.startsWith('/rivet/library')) return;
  listenToStorage();
  loadSession();
  const revision = sessionRevision;
  const code = new URLSearchParams(window.location.hash.slice(1)).get('code');
  if (code) {
    window.history.replaceState(
      null,
      '',
      window.location.pathname + window.location.search,
    );
    try {
      const response = await fetch('/api/library/browser-sessions/exchange', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code }),
      });
      if (response.ok) {
        saveLibrarySession(
          browserSessionToken(await response.json()),
          revision,
        );
        return;
      }
      if (response.status >= 500 && !activeToken)
        linkError = 'Rivet is temporarily unavailable. Please retry this link.';
    } catch {
      if (!activeToken && !storageError)
        linkError =
          'Rivet could not open this link. Please retry when the server is available.';
    }
  }
  notifySession();
};

export const fetchLibraryApi = async (
  path: `/api/${string}`,
  options: RequestInit = {},
): Promise<Response> => {
  loadSession();
  const token = activeToken;
  const headers = new Headers(options.headers);
  headers.set('Authorization', `Bearer ${token}`);
  const response = await fetch(path, { ...options, headers });
  if (response.status === 401) {
    loadSession();
    if (activeToken === token) clearLibrarySession();
  }
  return response;
};

export const requestLibrary = async <T>(
  endpoint: string,
  { schema, ...options }: RequestOptions<T>,
): Promise<T> => {
  const response = await fetchLibraryApi(`/api/library${endpoint}`, {
    method: options.method ?? 'GET',
    signal: options.signal,
    headers: {
      'Content-Type': 'application/json',
    },
    ...(options.body !== undefined
      ? { body: JSON.stringify(options.body) }
      : {}),
  });
  return readLibraryResponse(response, schema);
};

export const readLibraryResponse = async <T>(
  response: Response,
  schema: ResponseSchema<T>,
): Promise<T> => {
  const text = await response.text();
  let body: unknown;
  try {
    body = JSON.parse(text);
  } catch {
    if (response.ok) throw new Error(INVALID_RESPONSE_MESSAGE);
  }
  if (!response.ok) {
    if (response.status === 401) {
      throw new Error('Sign in to access this library.');
    }
    const failure = ErrorResponseSchema.safeParse(body);
    const message =
      failure.success && failure.data.error.trim()
        ? failure.data.error
        : `Library request failed (${response.status}).`;
    throw new Error(message);
  }
  const parsed = schema.safeParse(body);
  if (!parsed.success) throw new Error(INVALID_RESPONSE_MESSAGE);
  return parsed.data;
};
