import { fetchLocalApi } from '@/utils/localApi';
import { queryKeys } from '@/utils/queryKeys';
import { useCallback, useMemo, useRef, useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import {
  VariantsUiStateResponseSchema,
  type VariantsUiState,
} from '@rivet/core/types/api-responses';
import { useImmediateQueryData } from '@/hooks/useImmediateQueryData';
import { createLogger } from '../utils/logger';

const log = createLogger('useVariantsUiState');

export type StoredListOrder = VariantsUiState['order'];

export const EMPTY_LIST_ORDER: StoredListOrder = { groups: [], rows: {} };

export const EMPTY_UI_STATE: VariantsUiState = {
  pinned: [],
  order: EMPTY_LIST_ORDER,
};

export const PINNED_CONTAINER_ID = 'pinned';
export const TOP_CONTAINER_ID = 'top';
export const rowsContainerId = (groupKey: string): string => `rows:${groupKey}`;

type UiStateMutation = (prev: VariantsUiState) => VariantsUiState;

type QueuedArrangement = {
  projectPath: string | null;
  mutations: UiStateMutation[];
  preview: VariantsUiState;
};

const emptyQueue = (projectPath: string | null): QueuedArrangement => ({
  projectPath,
  mutations: [],
  preview: EMPTY_UI_STATE,
});

const applyMutations = (
  state: VariantsUiState,
  mutations: UiStateMutation[],
): VariantsUiState => mutations.reduce((next, mutation) => mutation(next), state);

const uiStatePath = (projectPath: string | null): `/api/${string}` =>
  projectPath
    ? `/api/variants/ui-state?projectPath=${encodeURIComponent(projectPath)}`
    : '/api/variants/ui-state';

const loadStoredUiState = async (
  projectPath: string | null,
): Promise<VariantsUiState> => {
  const response = await fetchLocalApi(uiStatePath(projectPath));
  if (!response.ok) {
    throw new Error(`Failed to load variants UI state (${response.status})`);
  }
  return VariantsUiStateResponseSchema.parse(await response.json()).uiState;
};

const persistUiState = async ({
  projectPath,
  uiState,
}: {
  projectPath: string;
  uiState: VariantsUiState;
}): Promise<void> => {
  await fetchLocalApi(uiStatePath(projectPath), {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ uiState }),
  });
};

const addPin =
  (key: string): UiStateMutation =>
  (prev) =>
    prev.pinned.includes(key)
      ? prev
      : { ...prev, pinned: [...prev.pinned, key] };

const removePin =
  (key: string): UiStateMutation =>
  (prev) => ({ ...prev, pinned: prev.pinned.filter((k) => k !== key) });

const setContainerOrder =
  (containerId: string, orderedKeys: string[]): UiStateMutation =>
  (prev) => {
    if (containerId === PINNED_CONTAINER_ID) {
      const arranged = new Set(orderedKeys);
      return {
        ...prev,
        pinned: [
          ...orderedKeys,
          ...prev.pinned.filter((key) => !arranged.has(key)),
        ],
      };
    }
    if (containerId === TOP_CONTAINER_ID) {
      return { ...prev, order: { ...prev.order, groups: orderedKeys } };
    }
    return {
      ...prev,
      order: {
        ...prev.order,
        rows: {
          ...prev.order.rows,
          [containerId.slice('rows:'.length)]: orderedKeys,
        },
      },
    };
  };

export const useVariantsUiState = (
  projectPath: string | null,
): {
  pinnedKeys: string[];
  pinnedKeySet: Set<string>;
  listOrder: StoredListOrder;
  togglePin: (key: string) => void;
  pinItem: (key: string) => void;
  reorder: (containerId: string, orderedKeys: string[]) => void;
} => {
  const queryClient = useQueryClient();
  const queryKey = queryKeys.variantsUiState(projectPath);
  const [queued, setQueued] = useState(() => emptyQueue(projectPath));
  const queuedRef = useRef(queued);

  const replaceQueue = useCallback((next: QueuedArrangement) => {
    queuedRef.current = next;
    setQueued(next);
  }, []);

  const queueFor = useCallback(
    (path: string | null) =>
      queuedRef.current.projectPath === path
        ? queuedRef.current
        : emptyQueue(path),
    [],
  );

  const { mutate: persist } = useMutation({
    mutationFn: persistUiState,
    onError: (err) => {
      log.warn('persist failed — arrangement kept for this session only', err);
    },
  });

  const storedQuery = useQuery({
    queryKey,
    queryFn: async () => {
      let stored: VariantsUiState;
      try {
        stored = await loadStoredUiState(projectPath);
      } catch (err) {
        log.warn(
          'load failed — arrangement is session-local until reload',
          err,
        );
        throw err;
      }
      const { mutations } = queueFor(projectPath);
      if (mutations.length === 0) return stored;
      replaceQueue(emptyQueue(projectPath));
      const merged = applyMutations(stored, mutations);
      if (projectPath) persist({ projectPath, uiState: merged });
      return merged;
    },
    enabled: projectPath !== null,
    gcTime: 0,
    retry: false,
    refetchOnWindowFocus: false,
    refetchOnReconnect: false,
    networkMode: 'always',
  });
  const { data: storedUiState, updateData: updateStoredUiState } =
    useImmediateQueryData({
      queryKey,
      data: storedQuery.isSuccess ? storedQuery.data : undefined,
    });

  const isStoredUiStateLoaded = useCallback(
    () =>
      projectPath !== null &&
      queryClient.getQueryState(queryKeys.variantsUiState(projectPath))
        ?.status === 'success',
    [projectPath, queryClient],
  );

  const readUiState = useCallback(
    (): VariantsUiState =>
      isStoredUiStateLoaded()
        ? (queryClient.getQueryData<VariantsUiState>(
            queryKeys.variantsUiState(projectPath),
          ) ?? EMPTY_UI_STATE)
        : queueFor(projectPath).preview,
    [isStoredUiStateLoaded, projectPath, queryClient, queueFor],
  );

  const apply = useCallback(
    (mutation: UiStateMutation) => {
      if (projectPath !== null && isStoredUiStateLoaded()) {
        const next = updateStoredUiState((current) =>
          mutation(current ?? EMPTY_UI_STATE),
        );
        persist({ projectPath, uiState: next });
        return;
      }
      const queue = queueFor(projectPath);
      replaceQueue({
        projectPath,
        mutations: [...queue.mutations, mutation],
        preview: mutation(queue.preview),
      });
    },
    [
      isStoredUiStateLoaded,
      persist,
      projectPath,
      queueFor,
      replaceQueue,
      updateStoredUiState,
    ],
  );

  const togglePin = useCallback(
    (key: string) => {
      const pinning = !readUiState().pinned.includes(key);
      apply(pinning ? addPin(key) : removePin(key));
    },
    [apply, readUiState],
  );

  const pinItem = useCallback(
    (key: string) => {
      if (readUiState().pinned.includes(key)) return;
      apply(addPin(key));
    },
    [apply, readUiState],
  );

  const reorder = useCallback(
    (containerId: string, orderedKeys: string[]) => {
      apply(setContainerOrder(containerId, orderedKeys));
    },
    [apply],
  );

  let uiState = EMPTY_UI_STATE;
  if (storedUiState) uiState = storedUiState;
  else if (queued.projectPath === projectPath) uiState = queued.preview;
  const pinnedKeySet = useMemo(() => new Set(uiState.pinned), [uiState.pinned]);

  return {
    pinnedKeys: uiState.pinned,
    pinnedKeySet,
    listOrder: uiState.order,
    togglePin,
    pinItem,
    reorder,
  };
};
