import { useCallback, useEffect, useRef, useState } from 'react';
import { usePostHog } from 'posthog-js/react';
import { z } from 'zod';
import { JUST_SIGNED_IN_STORAGE_KEY } from '@/constants/auth';
import { PROXY_URL } from '@/constants/proxy';
import { fetchLocalApi } from '@/utils/localApi';
import { createLogger } from '@/utils/logger';
import {
  buildAuthEvent,
  normalizeAuthFailureReason,
  type AuthEntryPoint,
  type AuthorizationMethod,
} from '@/utils/authTelemetry';
import {
  ErrorResponseSchema,
  SignInBrowserLaunchResponseSchema,
  type SignInBrowserLaunchResponse,
} from '@rivet/core/types/api-responses';
import { errorMessage } from '@rivet/core/utils/errorMessage';

const log = createLogger('useLogin');

const OAUTH_POLL_INTERVAL_MS = 2000;
const SIGN_IN_TIMEOUT_MS = 10 * 60 * 1000;
const SIGN_IN_LAUNCH_PATH = '/api/auth/browser-launches';

const OAuthTokenResponseSchema = z.object({
  success: z.boolean(),
  token: z.string().optional(),
  refreshToken: z.string().optional(),
  user: z
    .object({
      id: z.string().optional(),
      email: z.string().optional(),
    })
    .optional(),
  error: z.string().optional(),
  message: z.string().optional(),
});

const INSTALL_REF_PATH = '/api/auth/install-ref';
const InstallRefResponseSchema = z.object({
  installRef: z.string().nullable(),
});

interface LoginCredentials {
  token: string;
  refreshToken?: string;
  email: string;
  userId?: string;
  installRef?: string;
}

const readInstallRef = async (): Promise<string | undefined> => {
  try {
    const response = await fetch(INSTALL_REF_PATH);
    if (!response.ok) return undefined;
    const parsed = InstallRefResponseSchema.safeParse(await response.json());
    return parsed.success ? (parsed.data.installRef ?? undefined) : undefined;
  } catch {
    return undefined;
  }
};

const requestBrowserLaunch = async () => {
  const response = await fetchLocalApi(SIGN_IN_LAUNCH_PATH, { method: 'POST' });
  const payload: unknown = await response.json().catch(() => null);
  if (!response.ok) {
    const parsed = ErrorResponseSchema.safeParse(payload);
    throw new Error(
      parsed.success ? parsed.data.error : 'Failed to start Google login',
    );
  }
  const parsed = SignInBrowserLaunchResponseSchema.safeParse(payload);
  if (!parsed.success) throw new Error('Invalid Google login response');
  return parsed.data;
};

const pause = (ms: number, signal: AbortSignal) =>
  new Promise<void>((resolve) => {
    const onAbort = () => {
      clearTimeout(timer);
      resolve();
    };
    const timer = setTimeout(() => {
      signal.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    signal.addEventListener('abort', onAbort, { once: true });
  });

const waitForGoogleToken = async (
  session: SignInBrowserLaunchResponse,
  signal: AbortSignal,
) => {
  const deadline = Date.now() + SIGN_IN_TIMEOUT_MS;
  while (Date.now() < deadline) {
    signal.throwIfAborted();
    const tokenResponse = await fetch(`${PROXY_URL}/api/auth/google/token`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        session: session.sessionId,
        pollSecret: session.pollSecret,
      }),
      signal,
    });
    const parsedToken = OAuthTokenResponseSchema.safeParse(
      await tokenResponse.json(),
    );
    signal.throwIfAborted();
    if (!parsedToken.success) {
      throw new Error('Invalid Google token response');
    }
    const tokenPayload = parsedToken.data;
    if (
      tokenPayload.success &&
      tokenPayload.token &&
      tokenPayload.user?.email
    ) {
      return {
        email: tokenPayload.user.email,
        token: tokenPayload.token,
        refreshToken: tokenPayload.refreshToken,
        userId: tokenPayload.user.id,
      };
    }
    if (tokenPayload.error && tokenPayload.error !== 'Pending') {
      throw new Error(tokenPayload.error || 'Google login failed');
    }
    await pause(OAUTH_POLL_INTERVAL_MS, signal);
  }
  throw new Error('Authentication timed out. Please try again.');
};

export const useLogin = (
  entryPoint: AuthEntryPoint = 'editor_gate',
  completeLogin?: (credentials: LoginCredentials) => Promise<void>,
) => {
  const posthog = usePostHog();
  const [isStartingLogin, setIsStartingLogin] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [signInUrl, setSignInUrl] = useState<string | null>(null);
  const signInAbort = useRef<AbortController | null>(null);
  useEffect(() => () => signInAbort.current?.abort(), []);
  const startLogin = useCallback(async (): Promise<void> => {
    const authAttemptId = globalThis.crypto.randomUUID();
    const startedAt = Date.now();
    signInAbort.current?.abort();
    const abort = new AbortController();
    signInAbort.current = abort;
    setIsStartingLogin(true);
    setLoginError(null);
    const startedEvent = buildAuthEvent({
      outcome: 'started',
      authAttemptId,
      entryPoint,
      startedAt,
      now: startedAt,
    });
    posthog?.capture(startedEvent.event, startedEvent.properties);
    let authorizationMethod: AuthorizationMethod | undefined;
    try {
      const installRef = await readInstallRef();
      const launch = await requestBrowserLaunch();
      abort.signal.throwIfAborted();
      authorizationMethod = launch.isLaunched ? 'system_browser' : 'link';
      setSignInUrl(launch.authUrl);

      const tokenCredentials = await waitForGoogleToken(launch, abort.signal);
      const credentials: LoginCredentials = {
        ...tokenCredentials,
        ...(installRef ? { installRef } : {}),
      };
      if (completeLogin) await completeLogin(credentials);
      else {
        const storeResponse = await fetchLocalApi('/api/auth/store', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(credentials),
        });
        if (!storeResponse.ok) {
          throw new Error('Signed in, but failed to store session locally.');
        }
      }
      window.sessionStorage.setItem(JUST_SIGNED_IN_STORAGE_KEY, '1');
      const completedEvent = buildAuthEvent({
        outcome: 'completed',
        authAttemptId,
        entryPoint,
        startedAt,
        now: Date.now(),
        authorizationMethod,
      });
      posthog?.capture(completedEvent.event, completedEvent.properties);

      window.location.reload();
    } catch (error) {
      if (abort.signal.aborted) return;
      const message = errorMessage(error, 'Failed to start login flow');
      log.warn('Login failed:', message);
      const failedEvent = buildAuthEvent({
        outcome: 'failed',
        authAttemptId,
        entryPoint,
        startedAt,
        now: Date.now(),
        failureReason: normalizeAuthFailureReason(message),
        authorizationMethod,
      });
      posthog?.capture(failedEvent.event, failedEvent.properties);
      setSignInUrl(null);
      setLoginError(message);
      setIsStartingLogin(false);
    }
  }, [posthog, entryPoint, completeLogin]);

  return {
    startLogin,
    isStartingLogin,
    loginError,
    signInUrl,
  };
};
