import { z } from 'zod';
import { errorMessage } from '../utils/errorMessage';

export const CosmosIdSchema = z
  .string()
  .regex(/^[1-9]\d{0,15}$/)
  .refine((value) => Number.isSafeInteger(Number(value)));
export const CosmosCursorSchema = z.string().min(1).max(4096);
export const parseCosmosProfileUrl = (value: string) => {
  const fail = () =>
    new Error(
      'Use an HTTPS Cosmos profile URL such as https://www.cosmos.so/username',
    );
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    throw fail();
  }
  const segments = url.pathname.split('/').filter(Boolean);
  if (
    url.protocol !== 'https:' ||
    url.username ||
    url.password ||
    url.port ||
    !['cosmos.so', 'www.cosmos.so'].includes(url.hostname) ||
    segments.length !== 1
  )
    throw fail();
  let username: string;
  try {
    username = decodeURIComponent(segments[0]);
  } catch {
    throw fail();
  }
  if (
    !/^[a-zA-Z0-9_.-]{1,100}$/.test(username) ||
    [
      'e',
      'login',
      'signup',
      'explore',
      'search',
      'collections',
      'settings',
      'api',
      'profile',
    ].includes(username.toLowerCase())
  )
    throw fail();
  return {
    username,
    url: `https://www.cosmos.so/${encodeURIComponent(username)}`,
  };
};
export const CosmosProfileUrlSchema = z
  .string()
  .max(2048)
  .transform((value, context) => {
    try {
      return parseCosmosProfileUrl(value).url;
    } catch (error) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        message: errorMessage(error, 'Invalid Cosmos profile URL'),
      });
      return z.NEVER;
    }
  });
export const parseCosmosUrl = (value: string) => {
  const fail = () =>
    new Error(
      'Use an HTTPS Cosmos collection URL such as https://www.cosmos.so/owner/collection',
    );
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    throw fail();
  }
  const segments = url.pathname.split('/').filter(Boolean);
  if (
    url.protocol !== 'https:' ||
    url.username ||
    url.password ||
    url.port ||
    !['cosmos.so', 'www.cosmos.so'].includes(url.hostname) ||
    segments.length < 2 ||
    segments.length > 3 ||
    segments[0] === 'e'
  )
    throw fail();
  let decoded: string[];
  try {
    decoded = segments.map((segment) => decodeURIComponent(segment));
  } catch {
    throw fail();
  }
  if (
    decoded.some(
      (segment) =>
        !segment.length || segment.length > 300 || /[/\\\p{Cc}]/u.test(segment),
    )
  )
    throw fail();
  return {
    ownerUsername: decoded[0],
    slug: decoded[1],
    subcollectionSlug: decoded[2],
    url: `https://www.cosmos.so/${decoded.map(encodeURIComponent).join('/')}`,
  };
};
export const CosmosMediaUrlSchema = z
  .string()
  .url()
  .refine((value) => {
    const url = new URL(value);
    return (
      url.protocol === 'https:' &&
      url.hostname === 'cdn.cosmos.so' &&
      !url.username &&
      !url.password &&
      !url.port
    );
  });
export const CosmosCollectionSchema = z.object({
  id: CosmosIdSchema,
  title: z.string().min(1).max(500),
  url: z
    .string()
    .url()
    .transform((value) => parseCosmosUrl(value).url),
  children: z.array(CosmosIdSchema),
});
export const CosmosElementSchema = z.object({
  id: CosmosIdSchema,
  url: z.string().url(),
  title: z.string().max(1000),
  text: z.string().max(100_000),
  author: z.string().nullable(),
  owner: z.string().nullable(),
  sourceUrl: z.string().url().nullable(),
  images: z
    .array(
      z.object({
        url: CosmosMediaUrlSchema,
        representation: z.enum(['image', 'video-cover']),
      }),
    )
    .max(100),
  unsupportedReason: z.string().optional(),
});
export const CosmosPageSchema = z.object({
  collection: CosmosCollectionSchema,
  elements: z.array(CosmosElementSchema),
  total: z.number().int().nonnegative(),
  nextCursor: CosmosCursorSchema.nullable(),
});
export const CosmosResultSchema = z.discriminatedUnion('status', [
  CosmosPageSchema.extend({ status: z.literal('ok') }),
  z.object({
    status: z.literal('error'),
    message: z.string(),
    reason: z
      .enum(['rate_limited', 'provider_unavailable', 'collection_unavailable'])
      .optional(),
    retryAfterMs: z.number().nonnegative().optional(),
  }),
]);
export type CosmosPage = z.infer<typeof CosmosPageSchema>;
export type CosmosResult = z.infer<typeof CosmosResultSchema>;
export type CosmosElement = z.infer<typeof CosmosElementSchema>;
export interface CosmosFetchInput {
  url: string;
  collectionId?: string;
  cursor?: string;
  signal?: AbortSignal;
}
