import {
  EDITOR_ACCESS_TOKEN_HEADER,
  isEditorApiPath,
} from '@rivet/core/utils/editorAccess';
import { editorAccessToken } from './editorSession';
import { fetchLibraryApi } from '@/library/api';

export const fetchLocalApi = (
  path: `/api/${string}`,
  options: RequestInit = {},
): Promise<Response> => {
  if (!window.location.pathname.startsWith('/rivet/library')) {
    const headers = new Headers(options.headers);
    const token = editorAccessToken();
    if (token && isEditorApiPath(path, options.method))
      headers.set(EDITOR_ACCESS_TOKEN_HEADER, token);
    return fetch(path, { ...options, headers, redirect: 'error' });
  }
  return fetchLibraryApi(path, options);
};
