const RunFolder = ({
  label,
  collapsed,
  directionCount,
  onToggle,
  isEditing = false,
  onStartRename,
  onCommitRename,
  onCancelRename,
  onRemove,
  children,
}: {
  label: string;
  collapsed: boolean;
  directionCount: number;
  onToggle: () => void;
  isEditing?: boolean;
  onStartRename?: () => void;
  onCommitRename?: (value: string) => void;
  onCancelRename?: () => void;
  onRemove?: (returnFocusTo: HTMLElement | null) => void;
  children: React.ReactNode;
}) => {
  const posthogClient = usePostHog();
  const [menuOpen, setMenuOpen] = useState(false);
  const menuActions: RowActionsMenuAction[] = [
    ...(onStartRename
      ? [
          {
            key: 'rename',
            label: 'Rename',
            icon: <PencilSimple size={13} weight="bold" />,
            onSelect: onStartRename,
          },
        ]
      : []),
    ...(onRemove
      ? [
          {
            key: 'remove',
            label: 'Remove',
            icon: <Trash size={13} weight="bold" />,
            onSelect: onRemove,
          },
        ]
      : []),
  ];
  const FolderIcon = collapsed ? FolderSimple : FolderOpen;
  const folderIcon = (
    <FolderIcon size={13} weight="fill" className="text-accent-info shrink-0" />
  );
  if (isEditing && onCommitRename && onCancelRename) {
    return (
      <li className="bg-fill-faint overflow-hidden rounded-lg">
        <div
          data-hover-dead-zone=""
          className="bg-muted flex w-full items-center gap-2 px-3 py-2"
        >
          {folderIcon}
          <span className="min-w-0 flex-1">
            <RenameInput
              initial={label}
              onCommit={onCommitRename}
              onCancel={onCancelRename}
            />
          </span>
        </div>
        <AnimatePresence initial={false}>
          {!collapsed && (
            <motion.ul key="body" className="overflow-hidden">
              {children}
            </motion.ul>
          )}
        </AnimatePresence>
      </li>
    );
  }
  return (
    <li className="bg-fill-faint overflow-hidden rounded-lg">
      {}
      <div data-hover-dead-zone="" className="group relative">
        <button
          type="button"
          onClick={(e) => {
            if ((e.metaKey || e.ctrlKey) && menuActions.length > 0) {
              setMenuOpen(true);
              return;
            }
            posthogClient?.capture('variants_panel.folder_toggled', {
              isCollapsed: !collapsed,
              directionCount,
            });
            onToggle();
          }}
          aria-expanded={!collapsed}
          aria-label={`${collapsed ? 'Expand' : 'Collapse'} ${label} directions`}
          className="focus-visible:bg-active hover:bg-fill-subtle flex w-full items-center gap-2 px-3 py-2 text-left transition-colors duration-80 focus-visible:outline-hidden"
        >
          {folderIcon}
          <span className="text-foreground min-w-0 flex-1 truncate text-sm font-medium">
            {label}
          </span>
        </button>
        {}
        {menuActions.length > 0 && (
          <div
            className={cn(
              'absolute top-1.5 right-2 flex items-center gap-0.5 transition-opacity duration-80',
              'pointer-events-none opacity-0 group-hover:pointer-events-auto group-hover:opacity-100 has-[:focus-visible]:pointer-events-auto has-[:focus-visible]:opacity-100',
              menuOpen && 'pointer-events-auto opacity-100',
            )}
          >
            <RowActionsMenu
              open={menuOpen}
              onOpenChange={setMenuOpen}
              triggerLabel={`${label} run actions`}
              actions={menuActions}
            />
          </div>
        )}
      </div>
      <AnimatePresence initial={false}>
        {!collapsed && (
          <motion.ul
            key="body"
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: FOLDER_MOTION_DURATION, ease: FOLDER_EASE }}
            className="overflow-hidden"
          >
            {children}
          </motion.ul>
        )}
      </AnimatePresence>
    </li>
  );
};

interface VariantRowProps {
  rowKey: string;
  row: VariantTableRowModel;
  index: number;
  isSelected: boolean;
  isEditing: boolean;
  isPinned: boolean;
  onTogglePin: (method: PinActionMethod) => void;
  reorderContainer: string;
  reorderKey: string;
  isNested: boolean;
  busy: VariantTableBusy;
  registerItem: (index: number, element: HTMLElement | null) => void;
  onSelectActive: (variant: AgentVariantSnapshot) => void;
  onSelectPast: (entry: PastVariantRow) => void;
  onSelectOriginal: () => void;
  onActivePointerDown: (
    variantId: string,
    event: React.PointerEvent<HTMLDivElement>,
  ) => void;
  onPastPointerDown: (
    entry: PastVariantRow,
    event: React.PointerEvent<HTMLDivElement>,
  ) => void;
  onHover: (id: string | null) => void;
  onRemove: (
    variant: AgentVariantSnapshot,
    returnFocusTo: HTMLElement | null,
  ) => void;
  onRemovePast: (
    entry: PastVariantRow,
    returnFocusTo: HTMLElement | null,
  ) => void;
  onStartRename: (rowKey: string) => void;
  onCommitRename: (row: VariantTableRowModel, label: string) => void;
  onCancelRename: () => void;
  onCopyVariantContext: (copy: VariantCopy) => void;
  activeSessionId: string | null;
  projectPath: string | null;
}

const VariantRow = ({
  rowKey,
  row,
  index,
  isSelected,
  isEditing,
  isPinned,
  onTogglePin,
  reorderContainer,
  reorderKey,
  isNested,
  busy,
  registerItem,
  onSelectActive,
  onSelectPast,
  onSelectOriginal,
  onActivePointerDown,
  onPastPointerDown,
  onHover,
  onRemove,
  onRemovePast,
  onStartRename,
  onCommitRename,
  onCancelRename,
  onCopyVariantContext,
  activeSessionId,
  projectPath,
}: VariantRowProps) => {
  const rowRef = useRef<HTMLLIElement>(null);
  useRegisterProximityItem(registerItem, index, rowRef);
  const [menuOpen, setMenuOpen] = useState(false);

  const isActiveRow = row.kind === 'active';
  const isOriginalRow = row.kind === 'original';
  const variant = row.kind === 'active' ? row.variant : null;
  const entry = row.kind === 'past' ? row.entry : null;

  const isSucceeded = variant ? variant.status === 'succeeded' : true;
  const isPreviewReady = variant ? isVariantPreviewReady(variant) : true;
  const isLoading =
    variant !== null &&
    (variant.status === 'pending' || variant.status === 'running');
  const isFailed = variant?.status === 'failed';
  const isCancelled = variant?.status === 'cancelled';
  const isRemoving =
    variant !== null &&
    busy?.kind === 'remove' &&
    busy.variantId === variant.workItemId;
  const isRefining =
    variant !== null &&
    (variant.refinement?.status === 'pending' ||
      variant.refinement?.status === 'running');

  let label = ORIGINAL_LABEL;
  if (variant) {
    label = variant.label || `Direction ${index + 1}`;
  } else if (entry) {
    label = entry.label.trim() || 'Untitled direction';
  }

  let description: string | undefined = ORIGINAL_DESCRIPTION;
  if (variant) {
    description = variant.description;
  } else if (entry) {
    description = entry.brief;
  }
  const descriptionSummary = description
    ? summarizeVariantSubtitle(description)
    : null;
  const directionRef = directionRefForRow(row);
  const copyRef = directionRef ?? variantReferenceForRow(row, activeSessionId);

  if (isEditing) {
    return (
      <li
        ref={rowRef}
        data-proximity-index={index}
        data-reorder-container={reorderContainer}
        data-reorder-key={reorderKey}
        className="group relative z-10"
      >
        <div
          className={cn(
            'bg-muted flex w-full items-start gap-2 rounded-md py-2 pr-3',
            isNested ? 'pl-[33px]' : 'pl-3',
          )}
        >
          <span className="min-w-0 flex-1">
            <RenameInput
              initial={label}
              onCommit={(value) => onCommitRename(row, value)}
              onCancel={onCancelRename}
            />
            {descriptionSummary && (
              <span className="text-soft-foreground mt-1 line-clamp-2 block text-xs leading-snug">
                {descriptionSummary}
              </span>
            )}
          </span>
        </div>
      </li>
    );
  }

  return (
    <li
      ref={rowRef}
      data-proximity-index={index}
      data-reorder-container={reorderContainer}
      data-reorder-key={reorderKey}
      className={cn('group relative z-10 rounded-md', isSelected && 'bg-muted')}
      onMouseEnter={variant ? () => onHover(variant.workItemId) : undefined}
      onMouseLeave={isActiveRow ? () => onHover(null) : undefined}
    >
      {}
      <div
        role="button"
        tabIndex={0}
        data-variant-id={variant?.workItemId}
        data-variant-key={rowKey}
        onClick={(e) => {
          if (e.metaKey || e.ctrlKey) {
            setMenuOpen(true);
            return;
          }
          const selection = window.getSelection();
          if (selection && !selection.isCollapsed) return;
          if (row.kind === 'active') {
            onSelectActive(row.variant);
          } else if (row.kind === 'past') {
            onSelectPast(row.entry);
          } else {
            onSelectOriginal();
          }
        }}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            e.stopPropagation();
            if (row.kind === 'active') {
              onSelectActive(row.variant);
            } else if (row.kind === 'past') {
              onSelectPast(row.entry);
            } else {
              onSelectOriginal();
            }
          }
        }}
        onPointerDown={(e) => {
          if (e.metaKey || e.ctrlKey) return;
          if (row.kind === 'active') {
            if (isPreviewReady) {
              onActivePointerDown(row.variant.workItemId, e);
            }
          } else if (row.kind === 'past') {
            onPastPointerDown(row.entry, e);
          }
        }}
        aria-pressed={isSelected}
        aria-disabled={isActiveRow ? false : undefined}
        aria-busy={isLoading || isRefining}
        className={cn(
          'focus-visible:bg-active flex w-full items-start gap-2 rounded-md py-2 pr-3 text-left transition-colors focus-visible:outline-hidden',
          isNested ? 'pl-[33px]' : 'pl-3',
          isPreviewReady && 'cursor-grab active:cursor-grabbing',
          !isPreviewReady && 'cursor-pointer',
        )}
        style={isPreviewReady ? { touchAction: 'none' } : undefined}
      >
        <span className="min-w-0 flex-1">
          <span className="flex items-center gap-2 pr-12">
            {}
            {(isLoading || isRefining) && (
              <SparkleLoader
                className="text-soft-foreground shrink-0 text-sm"
                data-testid={
                  isRefining && !isLoading ? 'variant-refining' : undefined
                }
              />
            )}
            <Tooltip label="Double-click to rename" disabled={isOriginalRow}>
              <span
                onDoubleClick={(e) => {
                  e.stopPropagation();
                  if (!isOriginalRow) onStartRename(rowKey);
                }}
                className={cn(
                  'min-w-0 flex-1 truncate text-sm font-medium select-text',
                  isOriginalRow ? 'cursor-default' : 'cursor-text',
                  isSucceeded || isSelected
                    ? 'text-foreground'
                    : 'text-soft-foreground',
                )}
              >
                {label}
              </span>
            </Tooltip>
            {}
            {isFailed && (
              <Tooltip
                label={variant?.errorMessage ?? variant?.errorCode ?? 'Failed'}
                disabled={!variant?.errorMessage && !variant?.errorCode}
              >
                <span className="shrink-0">
                  <VariantStatusBadge label="Failed" />
                </span>
              </Tooltip>
            )}
            {isCancelled && <VariantStatusBadge label="Cancelled" />}
          </span>
          {}
          {descriptionSummary && (
            <span className="text-soft-foreground mt-0.5 line-clamp-2 block cursor-text text-xs leading-snug select-text">
              {descriptionSummary}
            </span>
          )}
        </span>
      </div>
      {!isOriginalRow ? (
        <VariantReferenceLinks
          references={variant?.references ?? entry?.references}
          source={isActiveRow ? 'active' : 'history'}
          sessionId={entry?.sessionId ?? activeSessionId}
          variantId={entry?.variantId ?? variant?.workItemId}
          projectPath={projectPath}
          className={isNested ? 'pl-[33px]' : 'pl-3'}
        />
      ) : null}
      {}
      <div
        className={cn(
          'absolute top-1.5 right-2 flex items-center gap-0.5 transition-opacity duration-80 motion-reduce:transition-none',
          'pointer-events-none opacity-0 group-hover:pointer-events-auto group-hover:opacity-100 has-[:focus-visible]:pointer-events-auto has-[:focus-visible]:opacity-100',
          menuOpen && 'pointer-events-auto opacity-100',
        )}
      >
        <Button
          variant="ghost"
          size="icon-compact"
          title={isPinned ? 'Unpin direction' : 'Pin direction'}
          aria-label={isPinned ? 'Unpin direction' : 'Pin direction'}
          aria-pressed={isPinned}
          onPointerDown={(e) => e.stopPropagation()}
          onKeyDown={(e) => {
            if (
              (e.key !== 'ArrowUp' && e.key !== 'ArrowDown') ||
              e.altKey ||
              e.ctrlKey ||
              e.metaKey ||
              e.shiftKey
            ) {
              e.stopPropagation();
            }
          }}
          onClick={(e) => {
            e.stopPropagation();
            onTogglePin('button');
          }}
          className={ROW_ACTION_BUTTON_CLASSES}
        >
          <PushPin weight={isPinned ? 'fill' : 'bold'} />
        </Button>
        <RowActionsMenu
          open={menuOpen}
          onOpenChange={setMenuOpen}
          triggerLabel="Direction actions"
          actions={[
            ...(copyRef
              ? [
                  {
                    key: 'copy-ref',
                    label: 'Copy ref',
                    detail: copyRef,
                    icon: <Hash size={13} weight="bold" />,
                    onSelect: () =>
                      onCopyVariantContext({
                        text: copyRef,
                        copyKind: directionRef ? 'direction_ref' : 'reference',
                      }),
                  },
                ]
              : []),
            ...(!copyRef && description
              ? [
                  {
                    key: 'copy',
                    label: 'Copy description',
                    icon: <Copy size={13} weight="bold" />,
                    onSelect: () =>
                      onCopyVariantContext({
                        text: formatVariantContextForClipboard({
                          label,
                          description,
                        }),
                        copyKind: 'description',
                      }),
                  },
                ]
              : []),
            {
              key: 'pin',
              label: isPinned ? 'Unpin' : 'Pin',
              icon: <PushPin size={13} weight="bold" />,
              onSelect: () => onTogglePin('menu'),
            },
            ...(!isOriginalRow
              ? [
                  {
                    key: 'rename',
                    label: 'Rename',
                    icon: <PencilSimple size={13} weight="bold" />,
                    onSelect: () => onStartRename(rowKey),
                  },
                  {
                    key: 'remove',
                    label: 'Remove',
                    icon: <Trash size={13} weight="bold" />,
                    disabled: isRemoving,
                    onSelect: (trigger: HTMLButtonElement | null) => {
                      if (row.kind === 'active') {
                        onRemove(row.variant, trigger);
                      } else if (row.kind === 'past') {
                        onRemovePast(row.entry, trigger);
                      }
                    },
                  },
                ]
              : []),
          ]}
        />
      </div>
    </li>
  );
};

export const RenameInput = ({
  initial,
  onCommit,
  onCancel,
}: {
  initial: string;
  onCommit: (value: string) => void;
  onCancel: () => void;
}) => {
  const [value, setValue] = useState(initial);
  const doneRef = useRef(false);

  const focusOnMount = useCallback((el: HTMLInputElement | null) => {
    if (!el) return;
    el.focus();
    el.select();
  }, []);

  const finish = (commit: boolean) => {
    if (doneRef.current) return;
    doneRef.current = true;
    if (commit) onCommit(value);
    else onCancel();
  };

  return (
    <TextInput
      ref={focusOnMount}
      size="compact"
      value={value}
      maxLength={120}
      aria-label="Rename direction"
      onChange={(e) => setValue(e.target.value)}
      onKeyDown={(e) => {
        e.stopPropagation();
        if (e.key === 'Enter') {
          e.preventDefault();
          finish(true);
        } else if (e.key === 'Escape') {
          e.preventDefault();
          finish(false);
        }
      }}
      onBlur={() => finish(true)}
      onClick={(e) => e.stopPropagation()}
      onPointerDown={(e) => e.stopPropagation()}
      className="text-sm font-medium"
    />
  );
};

const VariantStatusBadge = ({ label }: { label: string }) => (
  <span className="bg-muted text-soft-foreground text-micro-compact shrink-0 rounded-full px-1.5 py-0.5 font-medium tracking-wide uppercase">
    {label}
  </span>
);

const Footer = ({
  selectedVariant,
  busy,
  onDeploy,
  onDeployCanvas,
  canShare,
  canDeploy,
  canDeployCanvas,
  canvasVariantCount,
  canvasDeployedUrl,
  deployedUrl,
}: {
  selectedVariant: AgentVariantSnapshot | null;
  busy: PanelBusy;
  onDeploy: (variant: AgentVariantSnapshot) => void;
  onDeployCanvas: () => void;
  canShare: boolean;
  canDeploy: boolean;
  canDeployCanvas: boolean;
  canvasVariantCount: number;
  canvasDeployedUrl: string | null;
  deployedUrl: string | null;
}) => {
  const variantReady = selectedVariant
    ? isVariantShareReady(selectedVariant)
    : false;
  const isDeploying =
    busy?.kind === 'deploy' && busy.variantId === selectedVariant?.workItemId;
  const isDeployingCanvas = busy?.kind === 'deploy-canvas';
  const isShareDisabled = !canDeploy || !variantReady || busy !== null;
  const showCanvasDeploy = canDeployCanvas && canvasVariantCount > 0;
  const idleDeployLabel = deployedUrl ? 'Copy link' : 'Share';
  const deployLabel = isDeploying ? 'Deploying…' : idleDeployLabel;
  const idleCanvasLabel = canvasDeployedUrl
    ? 'Copy canvas link'
    : 'Share canvas';
  const canvasLabel = isDeployingCanvas ? 'Sharing…' : idleCanvasLabel;

  return (
    <div className="border-separator bg-card flex shrink-0 items-center justify-between gap-3 border-t px-3 py-4">
      {}
      <div className="min-w-0">
        {selectedVariant ? (
          <>
            <div className="text-foreground truncate text-sm font-medium">
              {selectedVariant.label.trim() || 'Untitled direction'}
            </div>
            {deployedUrl ? (
              <div className="text-soft-foreground text-micro">
                Deployed — share link ready
              </div>
            ) : null}
          </>
        ) : null}
      </div>
      <div className="flex shrink-0 items-center gap-2">
        {canShare ? (
          <SplitButton
            primaryLabel={deployLabel}
            primaryIcon={deployedUrl && !isDeploying ? Copy : undefined}
            primaryAction={() => {
              if (selectedVariant) onDeploy(selectedVariant);
            }}
            isDisabled={isShareDisabled}
            isDropdownDisabled={busy !== null}
            isLoading={isDeploying}
            loadingLabel="Deploying…"
            dropdownAriaLabel="More share actions"
            dropdownItems={
              showCanvasDeploy
                ? [
                    {
                      label: canvasLabel,
                      icon:
                        canvasDeployedUrl && !isDeployingCanvas
                          ? Copy
                          : undefined,
                      onClick: onDeployCanvas,
                      isDisabled: busy !== null,
                    },
                  ]
                : []
            }
          />
        ) : null}
      </div>
    </div>
  );
};

