const SAMPLE_PROMPT =
  'Try different ways to create a dropdown that feels fluid and dynamic';

export const EmptyStateBody = ({
  isMCPSession = false,
  mcpEditor = null,
}: {
  isMCPSession?: boolean;
  mcpEditor?: string | null;
}) => {
  const [copied, setCopied] = useState(false);
  const editorLabel = getEditorLabel(mcpEditor);
  const agentLabel = isMCPSession ? editorLabel : 'your coding agent';

  const handleCopy = () => {
    void navigator.clipboard.writeText(SAMPLE_PROMPT).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  };

  return (
    <div className="flex flex-col items-start gap-3 px-2 py-2">
      <p className="text-foreground text-sm font-medium">
        Create your first direction
      </p>
      <p className="text-soft-foreground text-xs">
        Use {agentLabel} to generate directions.
      </p>
      <div className="w-full">
        <p className="text-soft-foreground mb-2 text-xs">
          Here&apos;s a sample prompt to use:
        </p>
        <div className="border-separator bg-muted relative rounded-md border px-3 py-2.5 pr-9">
          <p className="text-soft-foreground text-xs leading-snug">
            &ldquo;{SAMPLE_PROMPT}&rdquo;
          </p>
          <Button
            variant="ghost"
            size="icon-compact"
            onClick={handleCopy}
            aria-label="Copy sample prompt"
            title="Copy to clipboard"
            className="absolute top-1 right-1"
          >
            {copied ? (
              <Check
                data-testid="sample-prompt-copied"
                className="text-accent-success"
                weight="bold"
              />
            ) : (
              <Copy weight="bold" />
            )}
          </Button>
        </div>
      </div>
    </div>
  );
};

