import { useQuery } from '@tanstack/react-query';
import type { ReferenceDiscoveryRequest } from '@rivet/core/types/reference-connectors';
import type { ProfileRuntime } from '@rivet/core/types/design-profile';
import {
  ReferenceImportPlanSummarySchema,
  ReferenceProfileStatusResponseSchema,
  ReferenceDiscoveryResponseSchema,
  type ReferenceImportPlanSummary,
} from '@rivet/core/types/api-responses';
import {
  requestLibrary,
  readLibraryResponse,
  type ResponseSchema,
} from '@/library/api';
import { fetchLocalApi } from '@/utils/localApi';
import { queryKeys } from '@/utils/queryKeys';

interface ProfileRequestOptions<T> {
  schema: ResponseSchema<T>;
  method?: 'GET' | 'POST' | 'PATCH';
  body?: unknown;
  signal?: AbortSignal;
}

const requestProfile = async <T>(
  endpoint: `/profile${string}`,
  { schema, method = 'GET', body, signal }: ProfileRequestOptions<T>,
): Promise<T> => {
  if (window.location.pathname.startsWith('/rivet/library')) {
    return requestLibrary(endpoint, { schema, method, body, signal });
  }
  const response = await fetchLocalApi(
    endpoint.replace(
      /^\/profile/,
      '/api/reference-profiles',
    ) as `/api/${string}`,
    {
      method,
      signal,
      headers: { 'Content-Type': 'application/json' },
      ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
    },
  );
  return readLibraryResponse(response, schema);
};

export const getReferenceProfileStatus = () =>
  requestProfile('/profile', { schema: ReferenceProfileStatusResponseSchema });

export const useReferenceProfile = (isOpen: boolean) =>
  useQuery({
    queryKey: queryKeys.referenceProfile,
    queryFn: getReferenceProfileStatus,
    enabled: isOpen,
  });

export const discoverReferenceCollections = (
  source: ReferenceDiscoveryRequest,
  signal?: AbortSignal,
) =>
  requestProfile('/profile/discoveries', {
    schema: ReferenceDiscoveryResponseSchema,
    method: 'POST',
    body: source,
    signal,
  });

export const prepareReferenceImport = ({
  discoveryId,
  collectionIds,
  runtime,
}: {
  discoveryId: string;
  collectionIds: string[];
  runtime: ProfileRuntime;
}) =>
  requestProfile('/profile/import-plans', {
    schema: ReferenceImportPlanSummarySchema,
    method: 'POST',
    body: {
      discoveryId,
      collectionIds,
      runtime,
    },
  });

export const enableReferenceProfile = (runtime: ProfileRuntime) =>
  requestProfile('/profile', {
    schema: ReferenceProfileStatusResponseSchema,
    method: 'PATCH',
    body: {
      isEnabled: true,
      runtime,
    },
  });

export const setReferenceAutonomy = (isOn: boolean) =>
  requestProfile('/profile', {
    schema: ReferenceProfileStatusResponseSchema,
    method: 'PATCH',
    body: { autonomousReferences: isOn },
  });

export const approveReferenceImport = (plan: ReferenceImportPlanSummary) =>
  requestProfile(`/profile/import-plans/${plan.id}/imports`, {
    schema: ReferenceImportPlanSummarySchema,
    method: 'POST',
    body: { revision: plan.revision, isApproved: true },
  });
