import { useCallback, type ReactNode } from 'react';
import posthog from 'posthog-js';
import { CircleNotch } from '@phosphor-icons/react';
import CoalesceLoader from './CoalesceLoader';


type SurfaceFill =
  | 'surface'
  | 'overlay'
  | 'page';

type SurfaceTone = 'neutral' | 'error';
type SurfaceSize = 'sm' | 'md' | 'lg';

export interface SurfaceAction {
  label: string;
  onClick: () => void;
  variant?: 'neutral' | 'ghost';
}

export interface StatusSurfaceProps {
  backdrop?: ReactNode;
  media?: ReactNode;
  title?: ReactNode;
  description?: ReactNode;
  actions?: SurfaceAction[];
  tone?: SurfaceTone;
  fill?: SurfaceFill;
  size?: SurfaceSize;
  children?: ReactNode;
  state?: string;
  role?: 'status' | 'alert';
  busy?: boolean;
  className?: string;
}

const FILL_CLASS: Record<SurfaceFill, string> = {
  surface:
    'relative flex h-full w-full items-center justify-center bg-background px-6',
  overlay:
    'absolute inset-0 z-10 flex items-center justify-center bg-background/90 px-6',
  page: 'relative flex h-screen w-full items-center justify-center bg-background px-6',
};

const HEADING_CLASS: Record<SurfaceSize, string> = {
  sm: 'text-lg font-semibold text-foreground',
  md: 'text-2xl font-semibold text-foreground',
  lg: 'text-3xl font-semibold text-foreground',
};

const ACTION_CLASS: Record<NonNullable<SurfaceAction['variant']>, string> = {
  neutral:
    'rounded-md border border-border-strong bg-transparent px-5 py-2 text-sm font-medium text-foreground transition-colors hover:bg-surface-3',
  ghost:
    'rounded-md px-5 py-2 text-sm font-medium text-soft-foreground transition-colors hover:text-foreground',
};

const StatusSurface = ({
  backdrop,
  media,
  title,
  description,
  actions,
  tone = 'neutral',
  fill = 'surface',
  size = 'md',
  children,
  state,
  role = 'status',
  busy = false,
  className = '',
}: StatusSurfaceProps) => {
  const captureImpression = useCallback(
    (node: HTMLDivElement | null) => {
      if (node && state) {
        posthog?.capture('status_surface_shown', { state, tone, fill });
      }
    },
    [state, tone, fill],
  );

  const hasContent = Boolean(
    media || title || description || children || actions?.length,
  );

  return (
    <div
      ref={captureImpression}
      className={`${FILL_CLASS[fill]} ${className}`.trim()}
      role={role}
      aria-live="polite"
      aria-busy={busy || undefined}
      data-state={state}
    >
      {backdrop ? <div className="absolute inset-0">{backdrop}</div> : null}
      {hasContent ? (
        <div className="relative z-10 flex max-w-sm flex-col items-center gap-5 text-center">
          {media}
          {title ? <h2 className={HEADING_CLASS[size]}>{title}</h2> : null}
          {description ? (
            <p className="text-soft-foreground text-base leading-relaxed">
              {description}
            </p>
          ) : null}
          {children}
          {actions?.length ? (
            <div className="flex flex-row items-center gap-3">
              {actions.map((action) => (
                <button
                  key={action.label}
                  type="button"
                  onClick={action.onClick}
                  className={ACTION_CLASS[action.variant ?? 'neutral']}
                >
                  {action.label}
                </button>
              ))}
            </div>
          ) : null}
        </div>
      ) : null}
    </div>
  );
};

export default StatusSurface;


type LoaderKind = 'coalesce' | 'spinner';

export interface LoadingSurfaceProps extends Omit<
  StatusSurfaceProps,
  'backdrop' | 'media' | 'tone' | 'role' | 'busy' | 'actions'
> {
  loader?: LoaderKind;
  trackGlobalLoaderCount?: boolean;
}

export const LoadingSurface = ({
  loader = 'coalesce',
  trackGlobalLoaderCount,
  size = 'lg',
  ...rest
}: LoadingSurfaceProps) => {
  if (loader === 'coalesce') {
    return (
      <StatusSurface
        {...rest}
        size={size}
        busy
        backdrop={
          <CoalesceLoader trackGlobalLoaderCount={trackGlobalLoaderCount} />
        }
      />
    );
  }

  return (
    <StatusSurface
      {...rest}
      size={size}
      busy
      media={
        <CircleNotch
          aria-hidden
          className="text-foreground h-8 w-8 shrink-0 animate-spin"
          weight="bold"
        />
      }
    />
  );
};


export interface EmptyStateProps extends Omit<
  StatusSurfaceProps,
  'backdrop' | 'media' | 'tone' | 'role' | 'busy'
> {
  icon?: ReactNode;
}

export const EmptyState = ({ icon, ...rest }: EmptyStateProps) => (
  <StatusSurface
    {...rest}
    tone="neutral"
    media={icon ? <div className="text-soft-foreground">{icon}</div> : undefined}
  />
);


export interface ErrorStateProps extends Omit<
  StatusSurfaceProps,
  'backdrop' | 'tone' | 'role' | 'busy'
> {
  actions: [SurfaceAction, ...SurfaceAction[]];
}

export const ErrorState = (props: ErrorStateProps) => (
  <StatusSurface {...props} tone="error" role="alert" />
);
