import { fetchLocalApi } from '@/utils/localApi';
import type { VariantSplitSlot, VariantSplitView } from '@/store/atoms';

type ReplayTarget = Pick<
  VariantSplitSlot,
  'sessionId' | 'source' | 'variantId'
>;

type Fetcher = typeof fetchLocalApi;

export const stopHistoryReplayTarget = (
  target: ReplayTarget | null | undefined,
  fetcher: Fetcher = fetchLocalApi,
): void => {
  if (target?.source !== 'history-dev-server') return;
  const params = new URLSearchParams({
    sessionId: target.sessionId,
    variantId: target.variantId,
  });
  void fetcher(`/api/variants/history/replay/stop?${params.toString()}`, {
    method: 'POST',
  }).catch(() => undefined);
};

export const stopHistoryReplayTargetsForSplit = (
  split: VariantSplitView | null | undefined,
  fetcher: Fetcher = fetchLocalApi,
): void => {
  const seen = new Set<string>();
  for (const target of [split?.left, split?.right]) {
    if (target?.source !== 'history-dev-server') continue;
    const key = `${target.sessionId}:${target.variantId}`;
    if (seen.has(key)) continue;
    seen.add(key);
    stopHistoryReplayTarget(target, fetcher);
  }
};
