import { MotionConfig } from 'motion/react';
import { cn } from '@/lib/utils';
import {
  Select as FluidSelect,
  SelectContent as FluidSelectContent,
  SelectItem as FluidSelectItem,
  SelectTrigger as FluidSelectTrigger,
} from '@/components/ui/select';

type SelectSize = 'default' | 'compact';

type SelectOption<Value extends string> = {
  value: Value;
  label: string;
  isDisabled?: boolean;
};

type SelectLabelling =
  { label: string; labelledBy?: never } | { labelledBy: string; label?: never };

type SelectProps<Value extends string> = SelectLabelling & {
  options: readonly SelectOption<Value>[];
  value: Value;
  onValueChange: (value: Value) => void;
  size?: SelectSize;
  isDisabled?: boolean;
  className?: string;
};

const FORCED_COLORS_ICON = 'forced-colors:[&_svg]:text-[CanvasText]';

const TRIGGER_TREATMENT = [
  'w-auto min-w-0 border-separator bg-muted text-foreground',
  'hover:border-soft-foreground/50 hover:bg-muted',
  'data-[state=open]:border-soft-foreground',
  'focus-visible:not-data-[pointer-focus]:border-soft-foreground focus-visible:not-data-[pointer-focus]:outline-hidden focus-visible:[box-shadow:none]!',
  'motion-reduce:transition-none',
  FORCED_COLORS_ICON,
];

const LIST_TREATMENT = [
  'bg-popover text-popover-foreground shadow-surface-4 rounded-lg forced-colors:border',
  '[&_[data-slot=select-checked-highlight]]:hidden',
  '[&_[data-slot=select-focus-ring]]:hidden',
];

const OPTION_TREATMENT = [
  'text-soft-foreground data-[highlighted]:text-foreground data-[state=checked]:text-foreground',
  'focus-visible:outline-hidden',
  FORCED_COLORS_ICON,
];

const TYPE_SIZE: Record<SelectSize, string> = {
  default: 'text-sm',
  compact: 'text-xs',
};

const Select = <Value extends string>({
  options,
  value,
  onValueChange,
  size = 'default',
  isDisabled = false,
  className,
  label,
  labelledBy,
}: SelectProps<Value>) => {
  const chooseOption = (next: string) => {
    const option = options.find((candidate) => candidate.value === next);
    if (option) onValueChange(option.value);
  };
  return (
    <MotionConfig reducedMotion="user">
      <FluidSelect
        value={value}
        onValueChange={chooseOption}
        disabled={isDisabled}
        size={size}
      >
        <FluidSelectTrigger
          aria-label={label}
          aria-labelledby={labelledBy}
          className={cn(TRIGGER_TREATMENT, TYPE_SIZE[size], className)}
        />
        <FluidSelectContent className={cn(LIST_TREATMENT)}>
          {options.map((option, index) => (
            <FluidSelectItem
              key={option.value}
              index={index}
              value={option.value}
              disabled={option.isDisabled}
              className={cn(OPTION_TREATMENT, TYPE_SIZE[size])}
            >
              {option.label}
            </FluidSelectItem>
          ))}
        </FluidSelectContent>
      </FluidSelect>
    </MotionConfig>
  );
};

export type { SelectOption, SelectProps, SelectSize };
export default Select;
