import {
  parseThemePreference,
  type ThemePreference,
} from '@rivet/core/types/theme-preference';
import {
  LIGHT_SCHEME_QUERY,
  THEME_QUERY_PARAMETER,
  THEME_STORAGE_KEY,
  type ResolvedTheme,
} from '@/utils/themeBootstrap';

type ThemeState = {
  preference: ThemePreference;
  resolvedTheme: ResolvedTheme;
};

type SavedThemeApi = (
  path: `/api/${string}`,
  options?: RequestInit,
) => Promise<Response>;

export const THEME_PREFERENCE_MESSAGE = 'rivet:theme-preference';

const SAVED_THEME_PATH = '/api/preferences/theme';

type ThemePreferenceMessage = {
  type: typeof THEME_PREFERENCE_MESSAGE;
  preference: ThemePreference;
};

const isThemePreferenceMessage = (
  data: unknown,
): data is ThemePreferenceMessage =>
  typeof data === 'object' &&
  data !== null &&
  'type' in data &&
  data.type === THEME_PREFERENCE_MESSAGE &&
  'preference' in data &&
  parseThemePreference(data.preference) !== null;

const listeners = new Set<() => void>();
let state: ThemeState = { preference: 'system', resolvedTheme: 'dark' };
let savedThemeApi: SavedThemeApi | null = null;
let pendingSavedThemeRead: AbortController | null = null;

const readStoredPreference = (): ThemePreference | null => {
  try {
    return parseThemePreference(window.localStorage.getItem(THEME_STORAGE_KEY));
  } catch {
    return null;
  }
};

const storePreference = (preference: ThemePreference) => {
  try {
    window.localStorage.setItem(THEME_STORAGE_KEY, preference);
  } catch {
    return;
  }
};

const readSavedPreference = async (
  api: SavedThemeApi,
  signal: AbortSignal,
): Promise<ThemePreference | null> => {
  try {
    const response = await api(SAVED_THEME_PATH, { signal });
    if (!response.ok) return null;
    const saved: unknown = await response.json();
    return typeof saved === 'object' && saved !== null && 'preference' in saved
      ? parseThemePreference(saved.preference)
      : null;
  } catch {
    return null;
  }
};

const isOsLight = (): boolean =>
  typeof window.matchMedia === 'function' &&
  window.matchMedia(LIGHT_SCHEME_QUERY).matches;

const resolveTheme = (preference: ThemePreference): ResolvedTheme => {
  if (preference !== 'system') return preference;
  return isOsLight() ? 'light' : 'dark';
};

const applyPreference = (preference: ThemePreference) => {
  const resolvedTheme = resolveTheme(preference);
  document.documentElement.dataset.theme = resolvedTheme;
  if (state.preference === preference && state.resolvedTheme === resolvedTheme)
    return;
  state = { preference, resolvedTheme };
  listeners.forEach((listener) => listener());
};

const adoptPreference = (preference: ThemePreference) => {
  pendingSavedThemeRead?.abort();
  applyPreference(preference);
};

export const followThemePreference = (preference: ThemePreference) => {
  storePreference(preference);
  adoptPreference(preference);
};

export const setThemePreference = (preference: ThemePreference) => {
  followThemePreference(preference);
  void savedThemeApi?.(SAVED_THEME_PATH, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ preference }),
  }).catch(() => undefined);
};

export const subscribeToThemePreference = (listener: () => void) => {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
};

export const readThemeState = (): ThemeState => state;

export const readThemePreferenceMessage = (
  data: unknown,
): ThemePreference | null =>
  isThemePreferenceMessage(data) ? data.preference : null;

export const createThemePreferenceMessage = (
  preference: ThemePreference,
): ThemePreferenceMessage => ({
  type: THEME_PREFERENCE_MESSAGE,
  preference,
});

const followSavedPreference = async (
  api: SavedThemeApi,
  read: AbortController,
) => {
  const saved = await readSavedPreference(api, read.signal);
  if (saved && !read.signal.aborted) followThemePreference(saved);
};

export const startThemeSync = ({
  libraryOrigin,
  fetchApi,
}: {
  libraryOrigin: string | null;
  fetchApi?: SavedThemeApi;
}): (() => void) => {
  const requested = parseThemePreference(
    new URLSearchParams(window.location.search).get(THEME_QUERY_PARAMETER),
  );
  if (requested) storePreference(requested);
  applyPreference(requested ?? readStoredPreference() ?? 'system');

  const savedThemeRead = new AbortController();
  pendingSavedThemeRead = savedThemeRead;
  savedThemeApi = fetchApi ?? null;
  if (fetchApi) void followSavedPreference(fetchApi, savedThemeRead);

  const followOs = () => applyPreference(state.preference);
  const followOtherTab = (event: StorageEvent) => {
    if (event.key !== THEME_STORAGE_KEY) return;
    adoptPreference(parseThemePreference(event.newValue) ?? 'system');
  };
  const followLibrary = (event: MessageEvent<unknown>) => {
    if (event.source !== window.parent || event.origin !== libraryOrigin)
      return;
    if (isThemePreferenceMessage(event.data))
      followThemePreference(event.data.preference);
  };
  const lightScheme =
    typeof window.matchMedia === 'function'
      ? window.matchMedia(LIGHT_SCHEME_QUERY)
      : null;
  lightScheme?.addEventListener('change', followOs);
  window.addEventListener('storage', followOtherTab);
  const stopTellingLibrary = libraryOrigin
    ? subscribeToThemePreference(() =>
        window.parent.postMessage(
          createThemePreferenceMessage(state.preference),
          libraryOrigin,
        ),
      )
    : () => {};
  if (libraryOrigin) window.addEventListener('message', followLibrary);
  return () => {
    savedThemeRead.abort();
    savedThemeApi = null;
    lightScheme?.removeEventListener('change', followOs);
    window.removeEventListener('storage', followOtherTab);
    window.removeEventListener('message', followLibrary);
    stopTellingLibrary();
  };
};
