import type {
  AgentVariantsProjectContext,
  AgentVariantSnapshot,
} from '@/store/atoms';
import { previewRouteSchema } from '@rivet/core/types/preview-routes';
import type { VariantHistoryRow } from '@rivet/core/types/variant-history';

const TARGET_PREVIEW_PREFIX = '/__rivet/preview';
const TARGET_VARIANT_PREVIEW_PREFIX = `${TARGET_PREVIEW_PREFIX}/variant/`;
const TARGET_HISTORY_PREVIEW_PREFIX = `${TARGET_PREVIEW_PREFIX}/history/`;

const normalizeRoutePath = (routePath: string | null | undefined): string => {
  if (!routePath) return '/';
  return routePath.startsWith('/') ? routePath : `/${routePath}`;
};

export const appendPreviewRoute = (
  previewUrl: string,
  routePath?: string | null,
): string => {
  if (!routePath) return previewUrl;
  const route = previewRouteSchema.parse(routePath);
  if (previewUrl.includes('?') || previewUrl.includes('#'))
    throw new Error(
      'Preview target must not contain an application query or hash',
    );
  return previewUrl.replace(/\/$/, '') + route;
};

export const buildHistoryRunPath = (
  target: Pick<VariantHistoryRow, 'sessionId' | 'variantId'>,
  query: string,
): `/api/${string}` => {
  const params = new URLSearchParams(query);
  params.set('targetAddressed', '1');
  return `/api/variants/history/${encodeURIComponent(target.sessionId)}/${encodeURIComponent(target.variantId)}/run?${params}`;
};

export const buildHistoryStaticPreviewUrl = (
  args: Pick<VariantHistoryRow, 'sessionId' | 'variantId'> & {
    projectPath?: string | null;
    routePath?: string | null;
  },
): string => {
  const base =
    '/api/variants/history/' +
    encodeURIComponent(args.sessionId) +
    '/' +
    encodeURIComponent(args.variantId);
  if (args.routePath)
    return appendPreviewRoute(
      base + '/site/' + encodeURIComponent(args.projectPath ?? 'current'),
      args.routePath,
    );
  return (
    base +
    '/preview' +
    (args.projectPath
      ? '?projectPath=' + encodeURIComponent(args.projectPath)
      : '')
  );
};

export const buildVariantDevServerPreviewUrl = (args: {
  sessionId: string;
  variantId: string;
  routePath?: string | null;
}): string =>
  `${TARGET_PREVIEW_PREFIX}/variant/${encodeURIComponent(
    args.sessionId,
  )}/${encodeURIComponent(args.variantId)}${normalizeRoutePath(args.routePath)}`;

export const buildHistoryDevServerPreviewUrl = (args: {
  sessionId: string;
  variantId: string;
  routePath?: string | null;
}): string =>
  `${TARGET_PREVIEW_PREFIX}/history/${encodeURIComponent(
    args.sessionId,
  )}/${encodeURIComponent(args.variantId)}${normalizeRoutePath(args.routePath)}`;

export const isTargetAddressedDevServerPreviewUrl = (url: string): boolean => {
  try {
    const parsed = new URL(url, 'http://localhost');
    return (
      parsed.pathname.startsWith(TARGET_VARIANT_PREVIEW_PREFIX) ||
      parsed.pathname.startsWith(TARGET_HISTORY_PREVIEW_PREFIX)
    );
  } catch {
    return (
      url.startsWith(TARGET_VARIANT_PREVIEW_PREFIX) ||
      url.startsWith(TARGET_HISTORY_PREVIEW_PREFIX)
    );
  }
};

export const resolveVariantPreviewUrl = (args: {
  sessionId: string | null;
  variant: AgentVariantSnapshot;
  projectContext: AgentVariantsProjectContext | null;
  routePath?: string | null;
}): string | null => {
  const { sessionId, variant, projectContext } = args;
  if (variant.status !== 'succeeded') return null;
  if (variant.preview?.kind === 'static_artifact') {
    return appendPreviewRoute(variant.preview.url, variant.previewRoutes?.[0]);
  }
  if (
    sessionId &&
    (variant.preview?.kind === 'dev_server' || typeof variant.port === 'number')
  ) {
    return buildVariantDevServerPreviewUrl({
      sessionId,
      variantId: variant.workItemId,
      routePath:
        variant.previewRoutes?.[0] ??
        (projectContext?.kind === 'fresh' ? '/' : args.routePath),
    });
  }
  if (
    sessionId &&
    projectContext?.kind === 'fresh' &&
    projectContext.executionPlan?.mode !== 'vite_app' &&
    variant.preview?.kind !== 'dev_server'
  ) {
    return `/api/variants/${sessionId}/static/${variant.workItemId}`;
  }
  return null;
};
