import type { ReferenceDiscoveryRequest } from '@rivet/core/types/reference-connectors';

type LibraryWorkspace = { id: string; projectPath: string };
type ReferenceDiscoveryKey = {
  viewId: string;
  source: ReferenceDiscoveryRequest | null;
};

type DesignReferenceSearchKey = {
  profileId: string;
  revision: number;
  references: readonly unknown[];
  search: string;
  sourceId: string;
};

type DesignLibraryImageKey = {
  profileId: string;
  referenceId: string;
  hash: string;
};

type LibraryPreviewKey = {
  projectId: string | undefined;
  sessionId: string | undefined;
  variantId: string | undefined;
};

type PreviewUpstreamHealthKey = {
  instanceId: string;
  sessionId: number;
  rerunVersion: number | null;
};

type VariantsHistoryKey = {
  historyQuery: string;
  snapshotKey: string;
};

const PROJECT_LIBRARY_KEY = ['project-library'] as const;
const PROJECT_LIBRARY_HISTORY_KEY = [
  ...PROJECT_LIBRARY_KEY,
  'history',
] as const;
const LIBRARY_PROJECT_PREVIEW_KEY = ['library-project-preview'] as const;
const VARIANTS_HISTORY_KEY = ['variants-history'] as const;
const DESIGN_LIBRARY_KEY = ['design-library'] as const;
const DESIGN_REFERENCE_SEARCH_KEY = ['design-reference-search'] as const;

export const queryKeys = {
  rivetConfig: ['rivet-config'] as const,
  featureFlags: ['rivet-feature-flags'] as const,
  account: ['rivet-account'] as const,
  serverConfig: ['server-config'] as const,
  integrations: ['integrations'] as const,
  referenceProfile: ['reference-profile'] as const,
  referenceDiscovery: (key: ReferenceDiscoveryKey) =>
    ['reference-discovery', key] as const,
  designLibraryAll: DESIGN_LIBRARY_KEY,
  designReferenceSearchAll: DESIGN_REFERENCE_SEARCH_KEY,
  previewUpstreamHealth: (key: PreviewUpstreamHealthKey) =>
    ['preview-upstream-health', key] as const,
  variantsUiState: (projectPath: string | null) =>
    ['variants-ui-state', projectPath] as const,
  variantsHistory: {
    all: VARIANTS_HISTORY_KEY,
    list: (key: VariantsHistoryKey) => [...VARIANTS_HISTORY_KEY, key] as const,
  },
  designLibrary: (
    userId: string | undefined,
    isAuthenticated: boolean | undefined,
  ) => [...DESIGN_LIBRARY_KEY, userId, isAuthenticated] as const,
  designReferenceSearch: ({
    profileId,
    revision,
    references,
    search,
    sourceId,
  }: DesignReferenceSearchKey) =>
    [
      ...DESIGN_REFERENCE_SEARCH_KEY,
      profileId,
      revision,
      references,
      search,
      sourceId,
    ] as const,
  designLibraryEntries: (referenceIds: readonly string[]) =>
    ['design-library-entries', referenceIds] as const,
  designLibraryImage: ({
    profileId,
    referenceId,
    hash,
  }: DesignLibraryImageKey) =>
    ['design-library-image', profileId, referenceId, hash] as const,
  projectLibrary: {
    all: PROJECT_LIBRARY_KEY,
    projects: [...PROJECT_LIBRARY_KEY, 'projects'] as const,
    histories: PROJECT_LIBRARY_HISTORY_KEY,
    history: (workspaces: LibraryWorkspace[]) =>
      [...PROJECT_LIBRARY_HISTORY_KEY, workspaces] as const,
  },
  libraryProjectPreview: {
    project: (projectId: string) =>
      [...LIBRARY_PROJECT_PREVIEW_KEY, projectId] as const,
    thumbnail: (projectId: string, projectPath: string) =>
      [...LIBRARY_PROJECT_PREVIEW_KEY, projectId, projectPath] as const,
  },
  libraryWorkspace: (projectId: string | undefined) =>
    ['library-workspace', projectId] as const,
  libraryPreview: ({ projectId, sessionId, variantId }: LibraryPreviewKey) =>
    ['library-preview', projectId, sessionId, variantId] as const,
};
