import { z } from 'zod/v3';

export const referenceImageSchema = z.object({
  hash: z.string().regex(/^[a-f0-9]{64}$/),
  mimeType: z.enum([
    'image/png',
    'image/jpeg',
    'image/webp',
    'image/gif',
    'image/avif',
  ]),
});

export type ReferenceImageDescriptor = z.infer<typeof referenceImageSchema>;

export const variantReferenceSchema = z
  .object({
    id: z.string().min(1),
    title: z.string().trim().min(1),
    url: z
      .string()
      .url()
      .refine((value) => {
        try {
          const url = new URL(value);
          return (
            ['http:', 'https:'].includes(url.protocol) &&
            !url.username &&
            !url.password
          );
        } catch {
          return false;
        }
      })
      .optional(),
    reason: z.string().optional(),
    image: referenceImageSchema.optional().catch(undefined),
  })
  .refine((reference) => Boolean(reference.url || reference.image), {
    message: 'A reference requires a public URL or an image',
  });

export type VariantReference = z.infer<typeof variantReferenceSchema>;

export const mergeVariantReferences = (
  ...groups: Array<readonly unknown[] | undefined>
): VariantReference[] | undefined => {
  const references: VariantReference[] = [];
  const ids = new Set<string>();
  const urls = new Set<string>();
  for (const value of groups.flatMap((group) => group ?? [])) {
    const parsed = variantReferenceSchema.safeParse(value);
    if (!parsed.success) continue;
    const reference = parsed.data;
    const url = reference.url ? new URL(reference.url).href : undefined;
    if (ids.has(reference.id) || (url && urls.has(url))) {
      const existing = references.find(
        (item) =>
          item.url === url && (url !== undefined || item.id === reference.id),
      );
      if (
        existing &&
        !existing.image &&
        reference.image &&
        (existing.id === reference.id || !ids.has(reference.id))
      ) {
        existing.id = reference.id;
        existing.image = reference.image;
        ids.add(reference.id);
      }
      continue;
    }
    references.push({ ...reference, ...(url ? { url } : {}) });
    ids.add(reference.id);
    if (url) urls.add(url);
  }
  return references.length ? references : undefined;
};
