import type { VariantSplitView } from '@/store/atoms';

type VariantComparisonTelemetryOutcome = 'started' | 'updated' | 'ended';

interface VariantComparisonTelemetryEvent {
  event: `visual_editor_variant_compare_${VariantComparisonTelemetryOutcome}`;
  properties: {
    bound_side_count: number;
    is_cross_session: boolean;
    left_session_id: string | undefined;
    left_source: string | undefined;
    left_variant_id: string | undefined;
    right_session_id: string | undefined;
    right_source: string | undefined;
    right_variant_id: string | undefined;
  };
}

export const buildVariantComparisonTelemetryEvent = (
  outcome: VariantComparisonTelemetryOutcome,
  split: VariantSplitView | null,
): VariantComparisonTelemetryEvent => {
  const left = split?.left;
  const right = split?.right;

  return {
    event: `visual_editor_variant_compare_${outcome}`,
    properties: {
      bound_side_count: Number(Boolean(left)) + Number(Boolean(right)),
      is_cross_session: Boolean(
        left && right && left.sessionId !== right.sessionId,
      ),
      left_session_id: left?.sessionId,
      left_source: left?.source,
      left_variant_id: left?.variantId,
      right_session_id: right?.sessionId,
      right_source: right?.source,
      right_variant_id: right?.variantId,
    },
  };
};
