import type { VariantHistoryRow } from '@rivet/core/types/variant-history';
import type { AgentVariantSnapshot } from '@/store/atoms';
import { buildHistoryStaticPreviewUrl } from '@/utils/variantPreviewUrl';

type DirectionIdentity = { sessionId: string; variantId: string };

type SavedDirectionLocation = {
  entry: VariantHistoryRow;
  projectPath: string | null;
};

export type SessionChangePreview =
  | { kind: 'keep_selected' }
  | { kind: 'show_saved'; entry: VariantHistoryRow }
  | { kind: 'clear' };

export const isReplayablePastVariant = (entry: VariantHistoryRow): boolean =>
  Boolean(entry.hasTree) && entry.serve?.kind === 'dev-server';

export const isListedPastVariant = (entry: VariantHistoryRow): boolean =>
  entry.preview?.kind === 'static' ||
  entry.serve?.kind === 'static' ||
  isReplayablePastVariant(entry);

export const findNewestStaticPastVariant = (
  rows: readonly VariantHistoryRow[],
): VariantHistoryRow | undefined =>
  [...rows]
    .sort(
      (a, b) =>
        new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
    )
    .find((entry) => !isReplayablePastVariant(entry));

export const isVariantPreviewReady = (
  variant: AgentVariantSnapshot,
): boolean => {
  if (variant.status !== 'succeeded') return false;
  return (
    variant.actions?.view?.enabled ??
    (Boolean(variant.preview) || typeof variant.port === 'number')
  );
};

export const isPreviewableDirection = (
  variant: AgentVariantSnapshot,
): boolean =>
  isVariantPreviewReady(variant) &&
  (variant.preview?.kind === 'static_artifact' ||
    variant.preview?.kind === 'dev_server');

export const staticPastVariantPreviewUrl = ({
  entry,
  projectPath,
}: SavedDirectionLocation): string =>
  buildHistoryStaticPreviewUrl({
    sessionId: entry.sessionId,
    variantId: entry.variantId,
    projectPath,
    routePath: entry.previewRoutes?.[0],
  });

export const staticPastVariantSelection = ({
  entry,
  projectPath,
}: SavedDirectionLocation) => ({
  selectedPastVariant: {
    sessionId: entry.sessionId,
    variantId: entry.variantId,
    previewKind: 'static' as const,
    references: entry.references,
    projectPath: projectPath ?? undefined,
  },
  previewUrl: staticPastVariantPreviewUrl({ entry, projectPath }),
});

export const resolveSessionChangePreview = ({
  incomingSessionId,
  previousSessionId,
  isIncomingSessionPreviewable,
  selectedPastVariant,
  displayedLiveVariantId,
  pastVariants,
}: {
  incomingSessionId: string | null;
  previousSessionId: string | null;
  isIncomingSessionPreviewable: boolean;
  selectedPastVariant: DirectionIdentity | null;
  displayedLiveVariantId: string | null;
  pastVariants: readonly VariantHistoryRow[];
}): SessionChangePreview => {
  if (isIncomingSessionPreviewable) return { kind: 'clear' };
  if (selectedPastVariant) {
    return selectedPastVariant.sessionId === incomingSessionId
      ? { kind: 'clear' }
      : { kind: 'keep_selected' };
  }
  const entry = pastVariants.find(
    (row) =>
      row.sessionId === previousSessionId &&
      row.variantId === displayedLiveVariantId &&
      !isReplayablePastVariant(row),
  );
  return entry ? { kind: 'show_saved', entry } : { kind: 'clear' };
};
