import { useCallback, useEffect } from 'react';
import { atom, useAtom } from 'jotai';
import {
  authorizationAtom,
  authorizationLinkFrom,
  beginAuthorization,
  bindAuthorizationSettlement,
  isActiveAttempt,
  stopAuthorization,
  type IntegrationConnectOutcome,
} from './authorizationLink';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { z } from 'zod';
import {
  ErrorResponseSchema,
  IntegrationBrowserLaunchResponseSchema,
} from '@rivet/core/types/api-responses';
import { fetchLocalApi } from '@/utils/localApi';
import { queryKeys } from '@/utils/queryKeys';

export type { IntegrationConnectOutcome };
export type IntegrationProvider = 'pinterest' | 'arena' | 'x';
export type AuthorizationMethod = 'system_browser' | 'link';

export type IntegrationConnectResult = {
  outcome: IntegrationConnectOutcome;
  authorizationMethod: AuthorizationMethod;
};

export type IntegrationSummary = {
  provider: string;
  status: string;
  externalUsername: string | null;
  connectedAt: string;
};

const IntegrationSummarySchema: z.ZodType<IntegrationSummary> = z.object({
  provider: z.string(),
  status: z.string(),
  externalUsername: z.string().nullable(),
  connectedAt: z.string(),
});

const IntegrationListBodySchema = z.object({
  integrations: z.array(IntegrationSummarySchema).optional(),
});

const AUTHORIZATION_LINK_POLL_MS = 2_000;
const AUTHORIZATION_LINK_TIMEOUT_MS = 10 * 60 * 1_000;

const pendingProviderAtom = atom<IntegrationProvider | null>(null);

const hasFreshConnection = ({
  integrations,
  provider,
  baselineConnectedAt,
}: {
  integrations: IntegrationSummary[];
  provider: IntegrationProvider;
  baselineConnectedAt: string | undefined;
}) =>
  integrations.some(
    (integration) =>
      integration.provider === provider &&
      integration.status === 'connected' &&
      integration.connectedAt !== baselineConnectedAt,
  );

const requestBrowserLaunch = async (provider: IntegrationProvider) => {
  const response = await fetchLocalApi(
    `/api/integrations/${provider}/browser-launches`,
    { method: 'POST' },
  );
  const payload: unknown = await response.json().catch(() => ({}));
  if (!response.ok) {
    const parsed = ErrorResponseSchema.safeParse(payload);
    const message = parsed.success ? parsed.data.error : '';
    throw new Error(message || `Could not connect ${provider}`);
  }
  const parsed = IntegrationBrowserLaunchResponseSchema.safeParse(payload);
  if (!parsed.success) throw new Error(`Could not connect ${provider}`);
  return parsed.data;
};

const loadIntegrations = async (): Promise<IntegrationSummary[]> => {
  const response = await fetchLocalApi('/api/integrations');
  if (!response.ok) {
    throw new Error(`Failed to load integrations (${response.status})`);
  }
  const body = IntegrationListBodySchema.parse(await response.json());
  return body.integrations ?? [];
};

const disconnectIntegration = async (
  provider: IntegrationProvider,
): Promise<void> => {
  const response = await fetchLocalApi(`/api/integrations/${provider}`, {
    method: 'DELETE',
  });
  if (!response.ok) {
    const parsed = ErrorResponseSchema.safeParse(
      await response.json().catch(() => ({})),
    );
    throw new Error(
      (parsed.success && parsed.data.error) ||
        `Could not disconnect ${provider}`,
    );
  }
};

export const useIntegrations = () => {
  const queryClient = useQueryClient();
  const [disconnectingProvider, setDisconnectingProvider] =
    useAtom(pendingProviderAtom);
  const [authorization, setAuthorization] = useAtom(authorizationAtom);
  const pendingProvider =
    disconnectingProvider ?? authorization?.provider ?? null;
  const authorizationLink = authorizationLinkFrom(authorization);
  useEffect(() => stopAuthorization, []);

  const query = useQuery<IntegrationSummary[]>({
    queryKey: queryKeys.integrations,
    queryFn: loadIntegrations,
    staleTime: 10_000,
  });

  const refetch = useCallback(async () => {
    await queryClient.invalidateQueries({
      queryKey: queryKeys.integrations,
      refetchType: 'none',
    });
    return queryClient.fetchQuery({
      queryKey: queryKeys.integrations,
      queryFn: loadIntegrations,
    });
  }, [queryClient]);

  const connect = useCallback(
    async (
      provider: IntegrationProvider,
    ): Promise<IntegrationConnectResult> => {
      const baselineConnectedAt = queryClient
        .getQueryData<IntegrationSummary[]>(queryKeys.integrations)
        ?.find((integration) => integration.provider === provider)?.connectedAt;
      const attempt = beginAuthorization();
      const releaseAuthorization = () => {
        setAuthorization((current) =>
          current?.attempt === attempt ? null : current,
        );
      };
      setAuthorization({ attempt, provider, link: null });
      try {
        const launch = await requestBrowserLaunch(provider);
        const authorizationMethod: AuthorizationMethod = launch.isLaunched
          ? 'system_browser'
          : 'link';
        if (!isActiveAttempt(attempt)) {
          return { outcome: 'abandoned', authorizationMethod };
        }
        setAuthorization({
          attempt,
          provider,
          link: {
            authUrl: launch.authUrl,
            isLaunched: launch.isLaunched,
          },
        });
        const outcome = await new Promise<IntegrationConnectOutcome>(
          (resolve) => {
            let isFinished = false;
            let pollId: ReturnType<typeof setInterval> | undefined;
            let timeoutId: ReturnType<typeof setTimeout> | undefined;
            const finish = (next: IntegrationConnectOutcome) => {
              if (isFinished) return;
              isFinished = true;
              if (pollId) clearInterval(pollId);
              if (timeoutId) clearTimeout(timeoutId);
              releaseAuthorization();
              resolve(next);
            };
            bindAuthorizationSettlement(attempt, finish);
            pollId = setInterval(() => {
              void refetch()
                .then((integrations) => {
                  if (
                    hasFreshConnection({
                      integrations,
                      provider,
                      baselineConnectedAt,
                    })
                  )
                    finish('connected');
                })
                .catch(() => undefined);
            }, AUTHORIZATION_LINK_POLL_MS);
            timeoutId = setTimeout(() => {
              finish('timed_out');
            }, AUTHORIZATION_LINK_TIMEOUT_MS);
          },
        );
        return { outcome, authorizationMethod };
      } finally {
        releaseAuthorization();
      }
    },
    [queryClient, refetch, setAuthorization],
  );

  const { mutateAsync: removeIntegration } = useMutation({
    mutationFn: disconnectIntegration,
    onSuccess: refetch,
  });

  const disconnect = useCallback(
    async (provider: IntegrationProvider): Promise<void> => {
      setDisconnectingProvider(provider);
      try {
        await removeIntegration(provider);
      } finally {
        setDisconnectingProvider(null);
      }
    },
    [removeIntegration, setDisconnectingProvider],
  );

  return {
    integrations: query.data ?? [],
    isLoading: query.isPending,
    error: query.error instanceof Error ? query.error.message : null,
    pendingProvider,
    connect,
    disconnect,
    authorizationLink,
    refetch,
  };
};
