import { useEffect } from 'react';
import {
  identifyTelemetryAccount,
  type TelemetryAccount,
} from '@/utils/telemetryPolicy';

export const useTelemetryIdentity = (account?: TelemetryAccount): void => {
  const userId = account?.userId;
  const email = account?.email;
  useEffect(() => {
    identifyTelemetryAccount({ userId, email });
  }, [userId, email]);
};
