import { errnoCode } from './errnoCode';
import { errorMessage } from './errorMessage';
import { isDevServerStartError } from './devServerError';
import { redactSensitiveText } from './hostedLogPrivacy';

const DEPENDENCY_REASON_CODES = [
  'multiple_lockfiles',
  'unsupported_package_manager',
  'invalid_package_manager_field',
  'invalid_manifest',
  'invalid_workspace',
  'path_outside_workspace',
  'dangling_symlink',
  'version_unreadable',
  'version_mismatch',
  'no_install_command',
  'install_failed',
  'lockfile_outdated',
  'engine_incompatible',
  'install_script_failed',
  'installer_unstoppable',
  'inputs_changed',
] as const;

const ERRNO_REASON_CODES = [
  'ENOENT',
  'EACCES',
  'EPERM',
  'EEXIST',
  'ENOTDIR',
  'EISDIR',
  'ELOOP',
  'ENOSPC',
  'EMFILE',
  'EADDRINUSE',
  'ECONNREFUSED',
  'ECONNRESET',
  'ETIMEDOUT',
  'EBUSY',
  'ENOTSUP',
  'EINVAL',
  'ENOTEMPTY',
  'EROFS',
  'EAI_AGAIN',
] as const;

const GENERAL_REASON_CODES = ['timeout', 'aborted', 'unknown'] as const;

export const FAILURE_REASON_CODES = [
  ...DEPENDENCY_REASON_CODES,
  ...ERRNO_REASON_CODES,
  ...GENERAL_REASON_CODES,
] as const;

export type FailureReasonCode = (typeof FAILURE_REASON_CODES)[number];

export interface FailureReason {
  reasonCode: FailureReasonCode;
  reasonDetail?: string;
}

const REASON_DETAIL_LIMIT = 400;
const REDACTION_INPUT_LIMIT = 4_000;
const ABSOLUTE_PATH =
  /(?<![\w.:/\\])\/(?:[\w.@+~-]+(?: [\w.@+~-]+)*\/)+[\w.@+~-]*/g;
const REASON_CODES: ReadonlySet<string> = new Set(FAILURE_REASON_CODES);
const ERRNO_CODES: ReadonlySet<string> = new Set(ERRNO_REASON_CODES);
const ERROR_NAME_REASON_CODES = new Map<string, FailureReasonCode>([
  ['AbortError', 'aborted'],
  ['TimeoutError', 'timeout'],
]);

const propertyOf = (error: unknown, key: string): unknown =>
  typeof error === 'object' && error !== null
    ? Reflect.get(error, key)
    : undefined;

const isFailureReasonCode = (value: unknown): value is FailureReasonCode =>
  typeof value === 'string' && REASON_CODES.has(value);

const isErrnoReasonCode = (
  value: string | undefined,
): value is (typeof ERRNO_REASON_CODES)[number] =>
  value !== undefined && ERRNO_CODES.has(value);

export const failureReasonCode = (error: unknown): FailureReasonCode => {
  const declared = propertyOf(error, 'reasonCode');
  if (isFailureReasonCode(declared)) return declared;
  const code = errnoCode(error);
  if (isErrnoReasonCode(code)) return code;
  return (
    ERROR_NAME_REASON_CODES.get(String(propertyOf(error, 'name'))) ?? 'unknown'
  );
};

const failureText = (error: unknown): string => {
  if (!isDevServerStartError(error)) return errorMessage(error);
  return error.summary ?? '';
};

const failureDetail = (error: unknown): string | undefined =>
  redactSensitiveText(
    failureText(error)
      .slice(-REDACTION_INPUT_LIMIT)
      .replace(/\s+/g, ' ')
      .trim(),
  )
    .replace(ABSOLUTE_PATH, '[redacted]')
    .slice(-REASON_DETAIL_LIMIT)
    .trim() || undefined;

export const failureReason = (error: unknown): FailureReason => {
  const reasonDetail = failureDetail(error);
  return {
    reasonCode: failureReasonCode(error),
    ...(reasonDetail ? { reasonDetail } : {}),
  };
};

export const failureReasonProperties = (
  error: unknown,
): { reason_code?: FailureReasonCode; reason_detail?: string } => {
  if (error === undefined) return {};
  const { reasonCode, reasonDetail } = failureReason(error);
  return {
    reason_code: reasonCode,
    ...(reasonDetail ? { reason_detail: reasonDetail } : {}),
  };
};

export const failureReasonCodeProperties = (
  error: unknown,
): { reason_code?: FailureReasonCode } =>
  error === undefined ? {} : { reason_code: failureReasonCode(error) };
