import { Copy } from '@phosphor-icons/react';
import type { VariantHistoryRow as PastVariantRow } from '@rivet/core/types/variant-history';

const PastDeploySheet = ({
  entry,
  deploying,
  deployedUrl,
  onDeploy,
  isDeployDisabled = false,
}: {
  entry: PastVariantRow;
  deploying: boolean;
  deployedUrl: string | null;
  onDeploy: (entry: PastVariantRow) => void;
  isDeployDisabled?: boolean;
}) => {
  const idleLabel = deployedUrl ? 'Copy link' : 'Share';
  const label = deploying ? 'Deploying…' : idleLabel;
  return (
    <div className="border-separator bg-card flex shrink-0 items-center justify-between gap-3 border-t px-3 py-4">
      <div className="min-w-0">
        <div className="text-foreground truncate text-sm font-medium">
          {entry.label.trim() || 'Untitled direction'}
        </div>
        {deployedUrl ? (
          <div className="text-soft-foreground text-micro">
            Deployed — share link ready
          </div>
        ) : null}
      </div>
      <button
        type="button"
        onClick={() => onDeploy(entry)}
        disabled={deploying || isDeployDisabled}
        title={
          deployedUrl
            ? `Copy share link (${deployedUrl})`
            : 'Deploy this direction and get a public link to share'
        }
        className="border-separator text-foreground hover:bg-muted flex shrink-0 items-center gap-1 rounded-md border px-2 py-1.5 text-xs font-medium transition-colors disabled:cursor-not-allowed disabled:opacity-50"
      >
        {deployedUrl && !deploying ? <Copy size={12} weight="bold" /> : null}
        {label}
      </button>
    </div>
  );
};

export default PastDeploySheet;
