import posthog, { type PostHogConfig } from 'posthog-js';
import { pluginMetricProperties } from '@rivet/core/config/pluginMetrics';

import { fetchLocalApi } from './localApi';
import { setEditorTelemetryMode } from './telemetryPolicy';
const POSTHOG_PUBLIC_API_KEY = 'phc_Ntj9tXHbS64XgYxlTfhglRmFivFsfm0AERph4ZlnNH';
const POLICY_TIMEOUT_MS = 3_000;
const PLUGIN_ID_PATTERN =
  /^plugin-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

export const pluginTelemetryOptions = (
  distinctId: string,
): Partial<PostHogConfig> => ({
  person_profiles: 'never',
  autocapture: false,
  opt_out_useragent_filter: true,
  capture_pageview: false,
  capture_pageleave: false,
  capture_exceptions: false,
  capture_performance: false,
  disable_session_recording: true,
  enable_recording_console_log: false,
  disable_external_dependency_loading: true,
  disable_surveys: true,
  advanced_disable_flags: true,
  advanced_disable_feature_flags: true,
  mask_all_text: true,
  mask_all_element_attributes: true,
  persistence: 'memory',
  bootstrap: { distinctID: distinctId, isIdentifiedID: false },
  before_send: (event) => {
    const approved = pluginMetricProperties(event.event, event.properties);
    if (!approved) return null;
    void fetchLocalApi('/api/telemetry/events', {
      method: 'POST',
      credentials: 'same-origin',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ event: event.event, properties: approved }),
      keepalive: true,
    }).catch(() => {});
    return null;
  },
});

export const initializeTelemetry = async (): Promise<void> => {
  try {
    const response = await fetchLocalApi('/api/telemetry', {
      signal: AbortSignal.timeout(POLICY_TIMEOUT_MS),
      cache: 'no-store',
    });
    if (!response.ok) return;
    const policy: { mode?: unknown; distinctId?: unknown } =
      await response.json();
    if (policy.mode !== 'full' && policy.mode !== 'metrics') return;
    if (
      policy.mode === 'metrics' &&
      (typeof policy.distinctId !== 'string' ||
        !PLUGIN_ID_PATTERN.test(policy.distinctId))
    )
      return;
    const mode = policy.mode;
    const recording = __RIVET_DISABLE_SESSION_REPLAY__
      ? { disable_session_recording: true }
      : {
          session_recording: {
            maskAllInputs: true,
            maskTextSelector: '[data-rivet-private]',
            blockSelector: 'iframe[data-rivet-private]',
          },
        };
    const options: Partial<PostHogConfig> = {
      api_host: __POSTHOG_API_HOST__,
      ui_host: 'https://us.posthog.com',
      person_profiles: 'always',
      capture_exceptions: true,
      autocapture: true,
      capture_pageview: true,
      capture_performance: true,
      persistence: 'localStorage',
      ...recording,
      mask_all_text: false,
      mask_all_element_attributes: false,
      loaded: (client) =>
        client.register({
          source: 'visual_editor',
          surface: 'visual_editor',
          telemetry_version: __TELEMETRY_VERSION__,
          rivet_version: __RIVET_VERSION__,
          env: import.meta.env.MODE,
        }),
    };
    if (mode === 'metrics') {
      Object.assign(
        options,
        pluginTelemetryOptions(policy.distinctId as string),
        { api_host: window.location.origin },
      );
    }
    posthog.init(POSTHOG_PUBLIC_API_KEY, options);
    setEditorTelemetryMode(mode);
  } catch {
    setEditorTelemetryMode('off');
  }
};
