import type { ReactNode } from 'react';
import { XLogo } from '@phosphor-icons/react';
import arenaLogoUrl from '@/assets/arena.png';
import cosmosLogoUrl from '@/assets/cosmos.svg';
import pinterestLogoUrl from '@/assets/pinterest.svg';
import { cn } from '@/lib/utils';

export type ReferenceProvider = 'pinterest' | 'arena' | 'x' | 'cosmos';

type ReferenceProviderIconProps = {
  provider: ReferenceProvider;
  className?: string;
};

type MarkAppearance = { className: string; color?: string };

type ProviderMark = {
  brandColor?: string;
  draw: (appearance: MarkAppearance) => ReactNode;
};

const MARK_SIZE_CLASS = 'h-6 w-6';

const drawMask = (maskUrl: string) => {
  const MaskMark = ({ className, color }: MarkAppearance) => (
    <span
      aria-hidden="true"
      className={cn(
        'bg-current forced-colors:bg-[CanvasText] forced-colors:forced-color-adjust-none',
        className,
      )}
      style={{
        color,
        WebkitMaskImage: `url("${maskUrl}")`,
        maskImage: `url("${maskUrl}")`,
        WebkitMaskSize: 'contain',
        maskSize: 'contain',
        WebkitMaskRepeat: 'no-repeat',
        maskRepeat: 'no-repeat',
        WebkitMaskPosition: 'center',
        maskPosition: 'center',
      }}
    />
  );
  return MaskMark;
};

const PROVIDER_MARKS: Record<ReferenceProvider, ProviderMark> = {
  x: {
    draw: ({ className, color }) => (
      <XLogo className={className} style={{ color }} aria-hidden="true" />
    ),
  },
  pinterest: {
    draw: ({ className }) => (
      <img
        src={pinterestLogoUrl}
        className={className}
        alt=""
        aria-hidden="true"
      />
    ),
  },
  arena: { brandColor: 'var(--brand-arena)', draw: drawMask(arenaLogoUrl) },
  cosmos: { draw: drawMask(cosmosLogoUrl) },
};

const ReferenceProviderIcon = ({
  provider,
  className,
}: ReferenceProviderIconProps) => {
  const mark = PROVIDER_MARKS[provider];
  return mark.draw({
    className: cn(
      MARK_SIZE_CLASS,
      mark.brandColor && 'forced-colors:text-[CanvasText]!',
      className,
    ),
    color: mark.brandColor,
  });
};

export default ReferenceProviderIcon;
