import type { RefObject } from 'react';
import type { VariantHistoryRow as PastVariantRow } from '@rivet/core/types/variant-history';
import Button from '@/components/Button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogTitle,
} from '@/components/Dialog';
import type { AgentVariantSnapshot } from '@/store/atoms';

const DESTRUCTIVE_ACTION_CLASSES =
  'bg-destructive/15 text-destructive hover:bg-destructive/25 hover:text-destructive focus-visible:bg-destructive/25 focus-visible:text-destructive';

export type PendingRemoveTarget = (
  | { kind: 'active'; variant: AgentVariantSnapshot }
  | { kind: 'past'; entry: PastVariantRow }
  | {
      kind: 'run';
      label: string;
      variants: AgentVariantSnapshot[];
      entries: PastVariantRow[];
    }
) & { returnFocusTo: HTMLElement | null };

interface RemoveVariantConfirmationDialogProps {
  target: PendingRemoveTarget | null;
  fallbackFocus?: RefObject<HTMLElement | null>;
  isConfirming: boolean;
  onCancel: () => void;
  onConfirm: () => void;
}

const getPendingRemoveLabel = (target: PendingRemoveTarget): string => {
  if (target.kind === 'active') {
    return target.variant.label.trim() || 'this direction';
  }
  if (target.kind === 'run') {
    return target.label.trim() || 'this run';
  }
  return target.entry.label.trim() || 'this direction';
};

const RemoveVariantConfirmationDialog = ({
  target,
  fallbackFocus,
  isConfirming,
  onCancel,
  onConfirm,
}: RemoveVariantConfirmationDialogProps) => {
  if (!target) return null;

  const label = getPendingRemoveLabel(target);
  const isRun = target.kind === 'run';
  const runCount = isRun ? target.variants.length + target.entries.length : 0;
  const confirmLabel = isRun ? 'Remove run' : 'Remove direction';

  return (
    <Dialog
      open
      onOpenChange={(isOpen) => {
        if (!isOpen && !isConfirming) onCancel();
      }}
    >
      <DialogContent
        size="sm"
        onCloseAutoFocus={(event) => {
          const focusTarget = [
            target.returnFocusTo,
            fallbackFocus?.current,
          ].find((element) => element?.isConnected);
          if (!focusTarget) return;
          event.preventDefault();
          focusTarget.focus();
        }}
      >
        <div className="flex flex-col gap-3 p-4">
          <DialogTitle className="text-foreground text-base font-medium">
            {isRun ? 'Remove run?' : 'Remove direction?'}
          </DialogTitle>
          <DialogDescription className="text-muted-foreground text-sm leading-5">
            {isRun
              ? `This removes all ${runCount} directions in “${label}”.`
              : `This removes “${label}” from the directions list.`}
          </DialogDescription>
          <div className="flex justify-end gap-2 pt-1">
            <Button variant="ghost" onClick={onCancel} disabled={isConfirming}>
              Cancel
            </Button>
            <Button
              variant="ghost"
              aria-label="Confirm remove direction"
              onClick={onConfirm}
              disabled={isConfirming}
              className={DESTRUCTIVE_ACTION_CLASSES}
            >
              {isConfirming ? 'Removing...' : confirmLabel}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default RemoveVariantConfirmationDialog;
