import { useCallback, useRef, useState } from 'react';
import { WarningCircle } from '@phosphor-icons/react';
import type { ReferenceProvider } from '@rivet/core/types/reference-connectors';
import { usePostHog } from 'posthog-js/react';
import Button from '@/components/Button';
import ReferenceProviderIcon from './ReferenceProviderIcon';
import {
  useIntegrations,
  type IntegrationConnectOutcome,
  type IntegrationProvider,
} from '../hooks/useIntegrations';
import AuthorizationLinkNotice from './AuthorizationLinkNotice';
import { createLogger } from '../utils/logger';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
} from '@/components/Dialog';
import {
  buildReferenceConnectionEvent,
  connectedReferenceProviders,
} from '../utils/referenceTelemetry';
import {
  getReferenceProfileStatus,
  useReferenceProfile,
} from '../hooks/useReferenceProfile';
import ReferenceImportModal from './ReferenceImportModal';
import { errorMessage } from '@rivet/core/utils/errorMessage';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { queryKeys } from '@/utils/queryKeys';

const log = createLogger('ConnectorsModal');
let latestProviderWrite = 0;

type ConnectorsModalProps = {
  isOpen: boolean;
  onClose: () => void;
  context?: 'menu' | 'onboarding' | 'library';
  highlightProvider?: IntegrationProvider | null;
};

type ConnectorMeta = {
  provider: IntegrationProvider;
  name: string;
  icon: React.ReactNode;
};

const CONNECTORS: ConnectorMeta[] = [
  {
    provider: 'x',
    name: 'X',
    icon: <ReferenceProviderIcon provider="x" />,
  },
  {
    provider: 'pinterest',
    name: 'Pinterest',
    icon: <ReferenceProviderIcon provider="pinterest" />,
  },
  {
    provider: 'arena',
    name: 'Are.na',
    icon: <ReferenceProviderIcon provider="arena" />,
  },
];

const connectionFailureReason = (
  outcome: Exclude<IntegrationConnectOutcome, 'connected'>,
) => {
  switch (outcome) {
    case 'abandoned':
      return 'sign_in_abandoned';
    case 'timed_out':
      return 'sign_in_timed_out';
    default: {
      const unhandled: never = outcome;
      return unhandled;
    }
  }
};

const COSMOS_CONNECTOR = {
  name: 'Cosmos',
  icon: <ReferenceProviderIcon provider="cosmos" />,
};

const ConnectorRow = ({
  meta,
  status,
  action,
  actionLabel,
  buttonLabel,
  isDisabled,
  isHighlighted,
  onAction,
}: {
  meta: Pick<ConnectorMeta, 'name' | 'icon'>;
  status: string;
  action: 'Connect' | 'Import';
  actionLabel: string;
  buttonLabel: string;
  isDisabled: boolean;
  isHighlighted: boolean;
  onAction: () => void;
}) => {
  return (
    <li
      className={`flex min-h-[64px] items-center gap-3 py-3 ${
        isHighlighted ? 'ring-secondary -mx-2 rounded-md px-2 ring-2' : ''
      }`}
    >
      <span
        className="text-foreground grid h-7 w-7 flex-none place-items-center"
        aria-hidden="true"
      >
        {meta.icon}
      </span>

      <div className="min-w-0 flex-1">
        <span className="text-foreground block text-sm font-medium">
          {meta.name}
        </span>
        <span className="text-soft-foreground block truncate text-xs">
          {status}
        </span>
      </div>

      <Button
        variant={action === 'Connect' ? 'tertiary' : 'secondary'}
        size="compact"
        aria-label={actionLabel}
        onClick={onAction}
        disabled={isDisabled}
        className="w-24 flex-none"
      >
        {buttonLabel}
      </Button>
    </li>
  );
};

const ReferenceConnections = ({
  isOpen,
  onClose,
  context = 'menu',
  highlightProvider = null,
}: ConnectorsModalProps) => {
  const {
    integrations,
    isLoading,
    error,
    pendingProvider,
    connect,
    authorizationLink,
    refetch: refetchIntegrations,
  } = useIntegrations();
  const posthog = usePostHog();
  const [importProvider, setImportProvider] =
    useState<ReferenceProvider | null>(null);
  const [connectionError, setConnectionError] = useState<string | null>(null);
  const visibleError = connectionError || error;
  const referenceProfile = useReferenceProfile(isOpen);
  const queryClient = useQueryClient();
  const cosmosStartedAt = useRef<number | null>(null);

  const resetImportView = () => {
    authorizationMutation.reset();
    setImportProvider(null);
    setConnectionError(null);
  };
  const handleClose = () => {
    resetImportView();
    onClose();
  };

  const byProvider = (provider: IntegrationProvider) =>
    integrations.find((entry) => entry.provider === provider);

  const recordConnectedProviders = useCallback(async () => {
    const write = ++latestProviderWrite;
    try {
      const [current, profile] = await Promise.all([
        refetchIntegrations(),
        queryClient
          .cancelQueries({ queryKey: queryKeys.referenceProfile })
          .then(() =>
            queryClient.fetchQuery({
              queryKey: queryKeys.referenceProfile,
              queryFn: getReferenceProfileStatus,
            }),
          ),
      ]);
      if (write !== latestProviderWrite) return;
      posthog?.setPersonProperties({
        connected_providers: connectedReferenceProviders({
          integrations: current,
          profileSources: profile.sources,
        }),
      });
    } catch (err: unknown) {
      if (write !== latestProviderWrite) return;
      log.warn(
        'Connected providers unavailable:',
        errorMessage(err, 'Could not read connection status.'),
      );
    }
  }, [posthog, queryClient, refetchIntegrations]);

  const handleConnect = useCallback(
    (provider: IntegrationProvider) => {
      const startedAt = Date.now();
      const startedEvent = buildReferenceConnectionEvent({
        action: 'connect',
        outcome: 'started',
        provider,
        entryPoint: context,
      });
      posthog?.capture(startedEvent.event, startedEvent.properties);
      return connect(provider)
        .then((result) => {
          const durationMs = Date.now() - startedAt;
          if (result.outcome === 'connected') {
            const completedEvent = buildReferenceConnectionEvent({
              action: 'connect',
              outcome: 'completed',
              provider,
              entryPoint: context,
              durationMs,
              authorizationMethod: result.authorizationMethod,
            });
            posthog?.capture(completedEvent.event, completedEvent.properties);
            void recordConnectedProviders();
            return true;
          }
          const failedEvent = buildReferenceConnectionEvent({
            action: 'connect',
            outcome: 'failed',
            provider,
            entryPoint: context,
            durationMs,
            failureReason: connectionFailureReason(result.outcome),
            authorizationMethod: result.authorizationMethod,
          });
          posthog?.capture(failedEvent.event, failedEvent.properties);
          return false;
        })
        .catch((err: unknown) => {
          const message = errorMessage(err, 'Could not connect.');
          const failedEvent = buildReferenceConnectionEvent({
            action: 'connect',
            outcome: 'failed',
            provider,
            entryPoint: context,
            durationMs: Date.now() - startedAt,
            failureReason: 'request_failed',
          });
          posthog?.capture(failedEvent.event, failedEvent.properties);
          log.warn(`Connect error for ${provider}:`, message);
          throw err;
        });
    },
    [connect, context, posthog, recordConnectedProviders],
  );

  const authorizationMutation = useMutation({ mutationFn: handleConnect });

  const startCosmosConnection = useCallback(() => {
    cosmosStartedAt.current = Date.now();
    const startedEvent = buildReferenceConnectionEvent({
      action: 'connect',
      outcome: 'started',
      provider: 'cosmos',
      entryPoint: context,
    });
    posthog?.capture(startedEvent.event, startedEvent.properties);
  }, [context, posthog]);

  const startImport = (provider: ReferenceProvider, isConnected: boolean) => {
    setConnectionError(null);
    const openImport = () => {
      posthog?.capture('visual_editor_reference_import_modal_opened', {
        provider,
      });
      setImportProvider(provider);
    };
    if (provider === 'cosmos') startCosmosConnection();
    if (provider === 'cosmos' || isConnected) {
      openImport();
      return;
    }
    authorizationMutation.mutate(provider, {
      onSuccess: (didConnect) => {
        if (didConnect) openImport();
        else setConnectionError('Connection was not completed. Try again.');
      },
      onError: (cause) =>
        setConnectionError(errorMessage(cause, 'Could not connect.')),
    });
  };

  const handleCosmosImported = () => {
    const completedEvent = buildReferenceConnectionEvent({
      action: 'connect',
      outcome: 'completed',
      provider: 'cosmos',
      entryPoint: context,
      ...(cosmosStartedAt.current === null
        ? {}
        : { durationMs: Date.now() - cosmosStartedAt.current }),
    });
    posthog?.capture(completedEvent.event, completedEvent.properties);
    void recordConnectedProviders();
  };

  const isOnboarding = context === 'onboarding';
  const isAccountActionPending =
    pendingProvider !== null && authorizationLink === null;
  const hasCosmosSources = referenceProfile.data?.sources.some(
    (source) => source.provider === 'cosmos',
  );
  let cosmosStatus = hasCosmosSources
    ? 'Profiles added'
    : 'Public profiles · No sign-in needed';
  if (referenceProfile.isError) cosmosStatus = 'Status unavailable';
  if (referenceProfile.isPending) cosmosStatus = 'Checking status…';

  const importEntry =
    importProvider && importProvider !== 'cosmos'
      ? {
          provider: importProvider,
          onReconnect: () => handleConnect(importProvider),
        }
      : { provider: 'cosmos' as const };

  return (
    <>
      <Dialog
        open={isOpen}
        onOpenChange={(isDialogOpen) => {
          if (!isDialogOpen) handleClose();
        }}
      >
        <DialogContent size="md">
          <DialogHeader onClose={handleClose}>Add references</DialogHeader>

          <div className="flex flex-col gap-4 p-4">
            <DialogDescription className="text-muted-foreground text-sm">
              Choose a source, then select and review what to import.
            </DialogDescription>

            {visibleError ? (
              <p
                role="alert"
                className="bg-surface-3 text-muted-foreground text-body flex items-center gap-2 rounded-lg px-4 py-3 font-medium"
              >
                <WarningCircle
                  aria-hidden
                  className="text-muted-foreground size-4 shrink-0"
                />
                {visibleError}
              </p>
            ) : null}

            {authorizationLink ? (
              <AuthorizationLinkNotice authUrl={authorizationLink.authUrl} />
            ) : null}

            <ul
              className="divide-separator divide-y"
              aria-label="Design reference services"
            >
              {CONNECTORS.map((meta) => {
                const integration = byProvider(meta.provider);
                const isConnected = integration?.status === 'connected';
                const username = integration?.externalUsername;
                let status = isConnected
                  ? `Connected${username ? ` as @${username}` : ''}`
                  : 'Not connected';
                if (isLoading) status = 'Checking status…';
                if (error) status = 'Status unavailable';
                const isPending = pendingProvider === meta.provider;
                const action = isConnected ? 'Import' : 'Connect';
                let buttonLabel = action;
                if (isPending) buttonLabel = 'Connecting…';
                return (
                  <ConnectorRow
                    key={meta.provider}
                    meta={meta}
                    status={status}
                    action={action}
                    actionLabel={
                      isConnected
                        ? `Import from ${meta.name}`
                        : `Connect ${meta.name}`
                    }
                    buttonLabel={buttonLabel}
                    isDisabled={isLoading || isAccountActionPending}
                    isHighlighted={highlightProvider === meta.provider}
                    onAction={() => startImport(meta.provider, isConnected)}
                  />
                );
              })}
              <ConnectorRow
                meta={COSMOS_CONNECTOR}
                status={cosmosStatus}
                action="Import"
                actionLabel="Import from Cosmos"
                buttonLabel="Import"
                isDisabled={isAccountActionPending}
                isHighlighted={false}
                onAction={() => {
                  startImport('cosmos', true);
                }}
              />
            </ul>

            {isOnboarding ? (
              <div className="flex items-center justify-between gap-4">
                <p className="text-muted-foreground text-xs">
                  You can always do this later from the account menu.
                </p>
                <Button
                  variant="secondary"
                  onClick={handleClose}
                  className="flex-none"
                >
                  Skip for now
                </Button>
              </div>
            ) : null}
          </div>
        </DialogContent>
      </Dialog>
      {isOpen && importProvider ? (
        <ReferenceImportModal
          {...importEntry}
          isOpen
          onClose={() => setImportProvider(null)}
          onImported={() => {
            if (importProvider === 'cosmos') handleCosmosImported();
            else void referenceProfile.refetch();
            void queryClient.invalidateQueries({
              queryKey: queryKeys.designLibraryAll,
            });
            void queryClient.invalidateQueries({
              queryKey: queryKeys.designReferenceSearchAll,
            });
          }}
        />
      ) : null}
    </>
  );
};

const ConnectorsModal = (props: ConnectorsModalProps) =>
  props.isOpen ? <ReferenceConnections {...props} /> : null;

export default ConnectorsModal;
