import { createEventStream } from '@/utils/eventStream';
import { fetchLocalApi } from '@/utils/localApi';
import { useEffect, useRef } from 'react';
import { useSetAtom } from 'jotai';
import {
  agentVariantsSnapshotAtom,
  hasReceivedAgentVariantsSnapshotAtom,
  panelOpenAtom,
  variantsPanelOptimisticGeneratingAtom,
  type AgentVariantsSnapshot,
} from '../store/atoms';
import { createLogger } from '../utils/logger';

const log = createLogger('useAgentVariantsSession');

export const useAgentVariantsSession = ({
  enabled = true,
}: {
  enabled?: boolean;
} = {}) => {
  const setSnapshot = useSetAtom(agentVariantsSnapshotAtom);
  const setHasReceivedSnapshot = useSetAtom(
    hasReceivedAgentVariantsSnapshotAtom,
  );
  const setPanelOpen = useSetAtom(panelOpenAtom);
  const setVariantsPanelOptimisticGenerating = useSetAtom(
    variantsPanelOptimisticGeneratingAtom,
  );
  const lastSessionIdRef = useRef<string | null>(null);

  useEffect(() => {
    setHasReceivedSnapshot(false);
    if (!enabled) return undefined;
    const es = createEventStream('/api/variants/events');

    es.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data) as AgentVariantsSnapshot;
        const previousSessionId = lastSessionIdRef.current;

        if (data.active) {
          const resolvedRequestIds = new Set(
            data.variants
              .map((v) => v.requestId)
              .filter((id): id is string => Boolean(id)),
          );
          setVariantsPanelOptimisticGenerating((prev) => {
            const next = prev.filter(
              (p) => !resolvedRequestIds.has(p.requestId),
            );
            return next;
          });
          if (data.sessionId !== lastSessionIdRef.current) {
            lastSessionIdRef.current = data.sessionId;
            setPanelOpen(true);
          }
        } else {
          lastSessionIdRef.current = null;
        }

        setSnapshot(data);
        setHasReceivedSnapshot(true);

        const sessionSwitched =
          data.active && data.sessionId !== previousSessionId;
        if (sessionSwitched) {
          void fetchLocalApi(`/api/variants/${data.sessionId}/preview-port`, {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ variantId: null }),
          }).catch((err) =>
            log.warn('failed to reset preview-port on session switch', err),
          );
        }
      } catch (err) {
        log.warn('failed to parse SSE event payload', err);
      }
    };

    es.onerror = (err) => {
      log.warn('SSE error (auto-reconnects)', err);
    };

    return () => {
      es.close();
    };
  }, [
    enabled,
    setSnapshot,
    setHasReceivedSnapshot,
    setPanelOpen,
    setVariantsPanelOptimisticGenerating,
  ]);
};
