const getBootstrapAgentApplyMode = (): 'embedded' | 'external' | null => {
  if (typeof window === 'undefined') {
    return null;
  }
  return window.__RIVET_BOOTSTRAP__?.agentApplyMode ?? null;
};

export const agentApplyModeAtom = atom<'embedded' | 'external' | null>(
  getBootstrapAgentApplyMode(),
);

export const queueAccessTokenAtom = atom<string | null>(null);
