export type PreviewTarget =
  | { kind: 'base' }
  | { kind: 'variant'; sessionId: string; variantId: string };

export const BASE_TARGET: PreviewTarget = { kind: 'base' };

export function previewTargetKey(target: PreviewTarget): string {
  return target.kind === 'base'
    ? 'base'
    : `variant:${target.sessionId}:${target.variantId}`;
}
