export type AuthFailureReason =
  'credential_store_failed' | 'provider_failed' | 'timeout';

export type AuthEntryPoint = 'editor_gate' | 'account_menu' | 'library';

export type AuthorizationMethod = 'system_browser' | 'link';

type AuthEventOptions = {
  outcome: 'started' | 'completed' | 'failed';
  authAttemptId: string;
  startedAt: number;
  now: number;
  failureReason?: AuthFailureReason;
  entryPoint?: AuthEntryPoint;
  authorizationMethod?: AuthorizationMethod;
};

export const normalizeAuthFailureReason = (
  message: string,
): AuthFailureReason => {
  const normalizedMessage = message.toLowerCase();
  if (normalizedMessage.includes('timed out')) return 'timeout';
  if (normalizedMessage.includes('store session')) {
    return 'credential_store_failed';
  }
  return 'provider_failed';
};

export const buildAuthEvent = ({
  outcome,
  authAttemptId,
  startedAt,
  now,
  failureReason,
  entryPoint = 'editor_gate',
  authorizationMethod,
}: AuthEventOptions) => ({
  event: `visual_editor_auth_${outcome}`,
  properties: {
    auth_attempt_id: authAttemptId,
    duration_ms: now - startedAt,
    entry_point: entryPoint,
    method: 'google_oauth',
    ...(failureReason ? { failure_reason: failureReason } : {}),
    ...(authorizationMethod
      ? { authorization_method: authorizationMethod }
      : {}),
  },
});
