import { forwardRef } from 'react';
import {
  Button as FluidButton,
  type ButtonProps as BaseButtonProps,
} from '@/components/ui/button';
import { TOOLTIP_SURFACE_CLASSES } from '@/components/Tooltip';
import { Tooltip as FluidTooltip } from '@/components/ui/tooltip';

type ButtonProps = BaseButtonProps & {
  title?: string;
  shortcut?: string;
  'data-cy'?: string;
};

const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  ({ title, shortcut, ...props }, ref) => {
    const button = <FluidButton ref={ref} {...props} />;

    if (!title) return button;

    return (
      <FluidTooltip
        className={TOOLTIP_SURFACE_CLASSES}
        content={
          <div className="flex flex-row items-center gap-2">
            <span>{title}</span>
            {shortcut ? (
              <span className="bg-tooltip-chip text-micro rounded px-1.5 py-0.5">
                {shortcut}
              </span>
            ) : null}
          </div>
        }
      >
        {button}
      </FluidTooltip>
    );
  },
);
Button.displayName = 'Button';

export type { ButtonProps };
export default Button;
