let openMenuCount = 0;

export const registerOpenMenu = (): (() => void) => {
  openMenuCount += 1;
  let released = false;
  return () => {
    if (released) return;
    released = true;
    openMenuCount = Math.max(0, openMenuCount - 1);
  };
};

export const isMenuOpen = (): boolean => openMenuCount > 0;
