import { CaretDown, type Icon } from '@phosphor-icons/react';
import { useState } from 'react';
import { Menu, MenuContent, MenuItem, MenuTrigger } from '@/components/Menu';

type DropdownItem = {
  label: string;
  icon?: Icon;
  onClick: () => void;
  isDisabled?: boolean;
};

type SplitButtonProps = {
  primaryLabel: string;
  primaryIcon?: Icon;
  primaryAction: () => void;
  isDisabled?: boolean;
  isDropdownDisabled?: boolean;
  isLoading?: boolean;
  loadingLabel?: string;
  dropdownAriaLabel?: string;
  dropdownItems: DropdownItem[];
};

const SplitButton = ({
  primaryLabel,
  primaryIcon: PrimaryIcon,
  primaryAction,
  isDisabled = false,
  isDropdownDisabled = false,
  isLoading = false,
  loadingLabel,
  dropdownAriaLabel = 'More actions',
  dropdownItems,
}: SplitButtonProps) => {
  const [isOpen, setIsOpen] = useState(false);

  const displayLabel = isLoading
    ? (loadingLabel ?? primaryLabel)
    : primaryLabel;
  const hasDropdownItems = dropdownItems.length > 0;

  return (
    <div className="flex items-stretch">
      <button
        onClick={primaryAction}
        disabled={isDisabled || isLoading}
        className={`bg-selected hover:bg-muted focus-visible:bg-muted flex h-7 shrink-0 items-center gap-1.5 px-3 text-xs font-medium text-foreground focus-visible:outline-hidden transition-colors disabled:cursor-not-allowed disabled:opacity-50 ${
          hasDropdownItems ? 'rounded-l-md' : 'rounded-md'
        }`}
      >
        {PrimaryIcon ? (
          <PrimaryIcon className="h-3.5 w-3.5" weight="bold" />
        ) : null}
        {displayLabel}
      </button>

      {hasDropdownItems ? (
        <Menu isOpen={isOpen} onOpenChange={setIsOpen}>
          <MenuTrigger asChild>
            <button
              aria-label={dropdownAriaLabel}
              disabled={isDropdownDisabled || isLoading}
              title={dropdownAriaLabel}
              className="bg-selected hover:bg-muted focus-visible:bg-muted h-7 shrink-0 rounded-r-md border-l border-border-emphasis px-1.5 text-foreground focus-visible:outline-hidden transition-colors disabled:cursor-not-allowed disabled:opacity-50"
            >
              <CaretDown className="h-3.5 w-3.5" weight="bold" />
            </button>
          </MenuTrigger>

          <MenuContent align="end">
            {dropdownItems.map((item) => {
              const ItemIcon = item.icon;
              return (
                <MenuItem
                  key={item.label}
                  onSelect={item.onClick}
                  disabled={item.isDisabled}
                >
                  {ItemIcon ? (
                    <ItemIcon className="h-3.5 w-3.5" weight="bold" />
                  ) : null}
                  {item.label}
                </MenuItem>
              );
            })}
          </MenuContent>
        </Menu>
      ) : null}
    </div>
  );
};

export default SplitButton;
