interface ProjectTitle {
  name?: string;
  projectPath?: string;
}

export const getProjectTitle = ({ name, projectPath }: ProjectTitle): string => {
  const folderName = projectPath?.split(/[\\/]/).filter(Boolean).pop();
  const projectName = name?.trim() || folderName;

  return projectName ? `${projectName} — Rivet` : 'Rivet';
};

export const setDocumentTitle = (title: string): (() => void) => {
  document.title = title;
  return () => {
    document.title = 'Rivet';
  };
};
