
import log from 'loglevel';
import posthog from 'posthog-js';
import { errorMessage } from '@rivet/core/utils/errorMessage';

const isDevelopment = import.meta.env.DEV;
const defaultLevel = isDevelopment ? 'DEBUG' : 'INFO';
const LOG_LEVEL = (
  import.meta.env.VITE_LOG_LEVEL || defaultLevel
).toUpperCase();

log.setLevel(
  log.levels[LOG_LEVEL as keyof typeof log.levels] || log.levels.INFO,
);

if (isDevelopment) {
  const originalFactory = log.methodFactory;
  log.methodFactory = (methodName, logLevel, loggerName) => {
    const rawMethod = originalFactory(methodName, logLevel, loggerName);

    const emojis = {
      trace: '🔍',
      debug: '🐛',
      info: '📋',
      warn: '⚠️',
      error: '❌',
    };

    return (message: string, ...args: unknown[]) => {
      const emoji = emojis[methodName as keyof typeof emojis] || '';
      const timestamp = new Date().toISOString().slice(11, 23);
      rawMethod(`${emoji} [${timestamp}] ${message}`, ...args);
    };
  };
  log.setLevel(log.getLevel());
}

export const createLogger = (componentName?: string) => {
  const prefix = componentName ? `[${componentName}] ` : '';

  return {
    trace: (message: string, ...args: unknown[]) =>
      log.trace(`${prefix}${message}`, ...args),
    debug: (message: string, ...args: unknown[]) =>
      log.debug(`${prefix}${message}`, ...args),
    info: (message: string, ...args: unknown[]) =>
      log.info(`${prefix}${message}`, ...args),
    warn: (message: string, ...args: unknown[]) =>
      log.warn(`${prefix}${message}`, ...args),
    error: (message: string, ...args: unknown[]) => {
      log.error(`${prefix}${message}`, ...args);
      try {
        const MAX_DETAIL_LENGTH = 512;
        const errorDetail = args
          .map((a) => errorMessage(a))
          .join(' ')
          .slice(0, MAX_DETAIL_LENGTH);

        const payload = {
          source: 'ui',
          error_message: message,
          service: componentName ?? 'unknown',
          error_type: 'logged_error',
          url: window.location.pathname,
          error_args_count: args.length,
          ...(errorDetail ? { error_detail: errorDetail } : {}),
        };
        posthog.capture('logger_error', payload);
      } catch (e) {
        console.error('[logger] Failed to send logger_error to PostHog:', e);
      }
    },

    api: (message: string, ...args: unknown[]) =>
      log.info(`${prefix}API: ${message}`, ...args),

    hook: (message: string, ...args: unknown[]) =>
      log.debug(`${prefix}Hook: ${message}`, ...args),

    mount: (message: string, ...args: unknown[]) =>
      log.debug(`${prefix}Mount: ${message}`, ...args),
  };
};
