import type { CSSProperties } from 'react';
import { WarningCircle } from '@phosphor-icons/react';
import { Toaster } from 'sonner';
import { useThemePreference } from '@/hooks/useThemePreference';

const TOAST_DURATION_MS = 5000;
const TOAST_MAX_HEIGHT = '150px';
const TOAST_ICON_SIZE_PX = 20;

const TOAST_COLORS = {
  '--normal-bg': 'var(--popover)',
  '--normal-border': 'var(--border)',
  '--normal-text': 'var(--popover-foreground)',
  '--success-bg': 'var(--popover)',
  '--success-border': 'var(--border)',
  '--success-text': 'var(--success)',
  '--error-bg': 'var(--normal-bg)',
  '--error-border': 'var(--normal-border)',
  '--error-text': 'var(--normal-text)',
} as CSSProperties;

const EditorToaster = () => {
  const { resolvedTheme } = useThemePreference();
  return (
    <Toaster
      duration={TOAST_DURATION_MS}
      richColors
      theme={resolvedTheme}
      style={TOAST_COLORS}
      icons={{
        error: (
          <WarningCircle
            aria-hidden
            weight="bold"
            size={TOAST_ICON_SIZE_PX}
            className="text-muted-foreground"
          />
        ),
      }}
      toastOptions={{
        style: { maxHeight: TOAST_MAX_HEIGHT, overflow: 'hidden' },
      }}
    />
  );
};

export default EditorToaster;
