import type { ThemePreference } from '@rivet/core/types/theme-preference';

export type { ThemePreference };

export type ResolvedTheme = Exclude<ThemePreference, 'system'>;

export const THEME_STORAGE_KEY = 'rivet-theme';

export const THEME_QUERY_PARAMETER = 'theme';

export const LIGHT_SCHEME_QUERY = '(prefers-color-scheme: light)';

export const applyInitialTheme = (
  storageKey: string,
  queryParameter: string,
  lightSchemeQuery: string,
): void => {
  const isPreference = (value: string | null) =>
    value === 'light' || value === 'dark' || value === 'system';
  let preference: string | null = 'system';
  try {
    const requested = new URLSearchParams(window.location.search).get(
      queryParameter,
    );
    const stored = window.localStorage.getItem(storageKey);
    if (isPreference(requested)) preference = requested;
    else if (isPreference(stored)) preference = stored;
  } catch {
    preference = 'system';
  }
  const isLight =
    preference === 'light' ||
    (preference === 'system' &&
      typeof window.matchMedia === 'function' &&
      window.matchMedia(lightSchemeQuery).matches);
  document.documentElement.dataset.theme = isLight ? 'light' : 'dark';
};

export const themeBootstrapScript = (): string =>
  `(${applyInitialTheme.toString()})(${[
    THEME_STORAGE_KEY,
    THEME_QUERY_PARAMETER,
    LIGHT_SCHEME_QUERY,
  ]
    .map((value) => JSON.stringify(value))
    .join(', ')});`;
