type ShortcutModifier = 'metaKey' | 'ctrlKey';

type ToggleRivetShortcut = {
  ariaKeyShortcuts: string;
  modifier: ShortcutModifier;
};

const TOGGLE_RIVET_KEY = '.';
const IME_PROCESS_KEY_CODE = 229;
const APPLE_PLATFORM_PATTERN = /Mac|iPhone|iPad|iPod/;

const APPLE_TOGGLE_RIVET_SHORTCUT: ToggleRivetShortcut = {
  ariaKeyShortcuts: 'Meta+.',
  modifier: 'metaKey',
};

const DEFAULT_TOGGLE_RIVET_SHORTCUT: ToggleRivetShortcut = {
  ariaKeyShortcuts: 'Control+.',
  modifier: 'ctrlKey',
};

export const readToggleRivetShortcut = (): ToggleRivetShortcut =>
  typeof navigator !== 'undefined' &&
  APPLE_PLATFORM_PATTERN.test(navigator.platform)
    ? APPLE_TOGGLE_RIVET_SHORTCUT
    : DEFAULT_TOGGLE_RIVET_SHORTCUT;

export const isToggleRivetShortcut = (event: KeyboardEvent): boolean => {
  const { modifier } = readToggleRivetShortcut();
  return (
    event.key === TOGGLE_RIVET_KEY &&
    !event.isComposing &&
    event.keyCode !== IME_PROCESS_KEY_CODE &&
    event.metaKey === (modifier === 'metaKey') &&
    event.ctrlKey === (modifier === 'ctrlKey') &&
    !event.altKey &&
    !event.shiftKey
  );
};
