import { atom, useAtomValue } from 'jotai';

export type IntegrationConnectOutcome = 'connected' | 'abandoned' | 'timed_out';

export type AuthorizationLink = {
  provider: 'pinterest' | 'arena' | 'x';
  authUrl: string;
  isLaunched: boolean;
};

type AuthorizationAttempt = {
  attempt: number;
  provider: AuthorizationLink['provider'];
  link: {
    authUrl: string;
    isLaunched: boolean;
  } | null;
};

export const authorizationAtom = atom<AuthorizationAttempt | null>(null);

type AuthorizationSettlement = (outcome: IntegrationConnectOutcome) => void;

let activeAttempt = 0;
let settleAuthorization: AuthorizationSettlement | null = null;

export const stopAuthorization = () => {
  activeAttempt += 1;
  const settle = settleAuthorization;
  settleAuthorization = null;
  settle?.('abandoned');
};

export const beginAuthorization = (): number => {
  stopAuthorization();
  return activeAttempt;
};

export const isActiveAttempt = (attempt: number) => attempt === activeAttempt;

export const bindAuthorizationSettlement = (
  attempt: number,
  settlement: AuthorizationSettlement,
) => {
  if (attempt !== activeAttempt) return;
  settleAuthorization = settlement;
};

export const authorizationLinkFrom = (
  authorization: AuthorizationAttempt | null,
): AuthorizationLink | null => {
  if (!authorization?.link) return null;
  return {
    provider: authorization.provider,
    authUrl: authorization.link.authUrl,
    isLaunched: authorization.link.isLaunched,
  };
};

export const useAuthorizationLink = () => {
  const authorization = useAtomValue(authorizationAtom);
  return { authorizationLink: authorizationLinkFrom(authorization) };
};
