import { useCallback, useRef } from 'react';
import { useSetAtom } from 'jotai';
import { fullscreenLoaderCountAtom } from '@/store/atoms';
import { readThemeToken } from '@/utils/themeTokens';

type Channels = readonly [number, number, number];

const FIELD_TOKEN = '--loader-field';
const LIFT_TOKEN = '--foreground';
const SHAPE_ALPHA = 0.85;

const SWAP_STEP = 3;
const POP_DURATION = 0.15;

const CELL_PITCH = 36;
const BASE_SIZE = 4.4;
const WEIGHT_CONTRAST = 0.7;

const HOLD = 3.5;
const FADE = 0.8;
const RING_HALF = 9;
const BAND = 11;
const LEVEL_MARK = [1.35, 1.12, 0.95, 0.85];
const LEVEL_START = [0, 1.1, 2.3, 3.1];
const LEVEL_STEP = [0, 0.35, 0.16, 0.13];
const LEVEL_DUR = [0.9, 0.5, 0.4, 0.35];

const SLOTS = 3;

type ShapeKind = 0 | 1 | 2;

type CompositionElement = {
  x1: number;
  y1?: number;
  x2: number;
  y2?: number;
  y?: number;
  level: number;
  hline?: boolean;
};

