const hash01 = (seed: number): number => {
  let h = seed | 0;
  h = Math.imul(h ^ (h >>> 16), 0x45d9f3b);
  h = Math.imul(h ^ (h >>> 16), 0x45d9f3b);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
};

const smoothstep = (x: number): number => {
  const t = Math.min(1, Math.max(0, x));
  return t * t * (3 - 2 * t);
};

const snap = (v: number, pitch: number): number =>
  (Math.round(v / pitch - 0.5) + 0.5) * pitch;

type Cell = {
  x: number;
  y: number;
  size: number;
  seed: number;
  phase: number;
  kind: ShapeKind;
};

type SketchGeo = {
  hline: boolean;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  level: number;
  start: number;
  dur: number;
};

type Sketch = {
  startT: number;
  buildEnd: number;
  els: SketchGeo[];
  frame: SketchGeo;
  cellQ: Float32Array;
  cellEl: Int16Array;
  inFrame: Uint8Array;
};

const TRIANGLE_W = Math.sin(Math.PI / 3);

const HEX_CHANNEL_OFFSETS = [1, 3, 5];

const toHexColor = (channels: Channels): string =>
  `#${channels.map((channel) => channel.toString(16).padStart(2, '0')).join('')}`;

const readTokenChannels = (
  ctx: CanvasRenderingContext2D,
  token: string,
): Channels => {
  ctx.fillStyle = readThemeToken(token, ctx.canvas);
  const normalized = String(ctx.fillStyle);
  const [r, g, b] = HEX_CHANNEL_OFFSETS.map((offset) =>
    parseInt(normalized.slice(offset, offset + 2), 16),
  );
  return [r, g, b];
};

const drawShape = (
  ctx: CanvasRenderingContext2D,
  kind: ShapeKind,
  x: number,
  y: number,
  r: number,
) => {
  ctx.beginPath();
  if (kind === 0) {
    ctx.arc(x, y, r, 0, Math.PI * 2);
  } else if (kind === 1) {
    const w = r * TRIANGLE_W;
    ctx.moveTo(x, y - r);
    ctx.lineTo(x + w, y + r / 2);
    ctx.lineTo(x - w, y + r / 2);
    ctx.closePath();
  } else {
    const half = r * 0.85;
    ctx.rect(x - half, y - half, half * 2, half * 2);
  }
  ctx.fill();
};

const coverage = (lx: number, ly: number, g: SketchGeo): number => {
  let d: number;
  if (g.hline) {
    const dx = Math.max(g.x1 - lx, lx - g.x2, 0);
    const dy = Math.abs(ly - g.y1);
    d = Math.hypot(dx, dy) - RING_HALF;
  } else {
    const dxOut = Math.max(g.x1 - lx, lx - g.x2, 0);
    const dyOut = Math.max(g.y1 - ly, ly - g.y2, 0);
    if (dxOut === 0 && dyOut === 0) {
      d = -Math.min(lx - g.x1, g.x2 - lx, ly - g.y1, g.y2 - ly);
    } else {
      d = Math.hypot(dxOut, dyOut);
    }
    d = Math.abs(d) - RING_HALF;
  }
  return smoothstep(0.5 - d / (2 * BAND));
};

const CoalesceLoader = ({
  className = '',
  trackGlobalLoaderCount = true,
}: {
  className?: string;
  trackGlobalLoaderCount?: boolean;
}) => {
  const setLoaderCount = useSetAtom(fullscreenLoaderCountAtom);

  const cleanupRef = useRef<(() => void) | null>(null);

  const canvasRef = useCallback(
    (canvas: HTMLCanvasElement | null) => {
      cleanupRef.current?.();
      cleanupRef.current = null;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      if (trackGlobalLoaderCount) setLoaderCount((c) => c + 1);

      const reducedMotion = window.matchMedia(
        '(prefers-reduced-motion: reduce)',
      ).matches;

      let cells: Cell[] = [];
      let width = 0;
      let height = 0;
      let cellW = CELL_PITCH;
      let cellH = CELL_PITCH;
      let active: Sketch | null = null;
      let fading: Sketch | null = null;
      let fadeT = 0;
      let lastComp = -1;
      let field: Channels = [0, 0, 0];
      let lift: Channels = [0, 0, 0];

      const liftStyles = new Array<string | undefined>(33);
      const liftStyle = (m: number): string => {
        const i = Math.round(m * 32);
        let s = liftStyles[i];
        if (!s) {
          const k = i / 32;
          s = toHexColor([
            Math.round(field[0] + (lift[0] - field[0]) * k),
            Math.round(field[1] + (lift[1] - field[1]) * k),
            Math.round(field[2] + (lift[2] - field[2]) * k),
          ]);
          liftStyles[i] = s;
        }
        return s;
      };
      const fieldStyle = (dim: number): string => {
        const shade = 1 - 0.35 * dim;
        return toHexColor([
          Math.round(field[0] * shade),
          Math.round(field[1] * shade),
          Math.round(field[2] * shade),
        ]);
      };

      const makeSketch = (startT: number): Sketch => {
        let idx = Math.floor(Math.random() * COMPOSITIONS.length);
        if (idx === lastComp) idx = (idx + 1) % COMPOSITIONS.length;
        lastComp = idx;
        const counters = [0, 0, 0, 0];
        const els: SketchGeo[] = COMPOSITIONS[idx].map((r, i) => {
          const lv = r.level;
          const k = counters[lv]++;
          const start = LEVEL_START[lv] + k * LEVEL_STEP[lv];
          const dur = LEVEL_DUR[lv] + hash01(idx * 131 + i * 17 + 5) * 0.2;
          if (r.hline) {
            const y = snap((r.y ?? 0) * height, cellH);
            return {
              hline: true,
              x1: snap(r.x1 * width, cellW),
              x2: snap(r.x2 * width, cellW),
              y1: y,
              y2: y,
              level: lv,
              start,
              dur,
            };
          }
          const x1 = snap(r.x1 * width, cellW);
          const y1 = snap((r.y1 ?? 0) * height, cellH);
          return {
            hline: false,
            x1,
            y1,
            x2: Math.max(snap(r.x2 * width, cellW), x1 + cellW),
            y2: Math.max(snap((r.y2 ?? 0) * height, cellH), y1 + cellH),
            level: lv,
            start,
            dur,
          };
        });
        const buildEnd = els.reduce((acc, e) => Math.max(acc, e.start + e.dur), 0);

        const n = cells.length;
        const cellQ = new Float32Array(n * SLOTS);
        const cellEl = new Int16Array(n * SLOTS).fill(-1);
        const inFrame = new Uint8Array(n);
        const frame = els[0];
        for (let i = 0; i < n; i++) {
          const c = cells[i];
          if (
            c.x > frame.x1 &&
            c.x < frame.x2 &&
            c.y > frame.y1 &&
            c.y < frame.y2
          ) {
            inFrame[i] = 1;
          }
          const base = i * SLOTS;
          for (let e = 0; e < els.length; e++) {
            const q = coverage(c.x, c.y, els[e]);
            if (q <= 0.02) continue;
            let minSlot = base;
            for (let s = base; s < base + SLOTS; s++) {
              if (cellEl[s] === -1) {
                minSlot = s;
                break;
              }
              if (cellQ[s] < cellQ[minSlot]) minSlot = s;
            }
            if (cellEl[minSlot] === -1 || q > cellQ[minSlot]) {
              cellQ[minSlot] = q;
              cellEl[minSlot] = e;
            }
          }
        }

        return { startT, buildEnd, els, frame, cellQ, cellEl, inFrame };
      };

      const rebuild = () => {
        const rect = canvas.getBoundingClientRect();
        width = Math.max(1, rect.width);
        height = Math.max(1, rect.height);
        const dpr = Math.min(2, window.devicePixelRatio || 1);
        canvas.width = Math.round(width * dpr);
        canvas.height = Math.round(height * dpr);
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        field = readTokenChannels(ctx, FIELD_TOKEN);
        lift = readTokenChannels(ctx, LIFT_TOKEN);
        liftStyles.fill(undefined);
        ctx.globalAlpha = SHAPE_ALPHA;

        const cols = Math.max(8, Math.round(width / CELL_PITCH));
        const rows = Math.max(6, Math.round(height / CELL_PITCH));
        cellW = width / cols;
        cellH = height / rows;
        cells = [];
        for (let row = 0; row < rows; row++) {
          const rowT = rows > 1 ? row / (rows - 1) : 0.5;
          const size = BASE_SIZE * (1 + WEIGHT_CONTRAST * 0.4 * (rowT * 2 - 1));
          for (let col = 0; col < cols; col++) {
            const seed = row * 8191 + col * 131 + 1;
            const cell: Cell = {
              x: (col + 0.5) * cellW,
              y: (row + 0.5) * cellH,
              size,
              seed,
              phase: hash01(seed),
              kind: 0,
            };
            cell.kind = Math.floor(hash01(seed * 97) * 3) as ShapeKind;
            cells.push(cell);
          }
        }
        fading = null;
        active = null;
      };

      const fadeP = new Float32Array(32);

      const paint = (t: number) => {
        ctx.clearRect(0, 0, width, height);

        if (!active) active = makeSketch(t + 0.2);
        if (t >= active.startT + active.buildEnd + HOLD) {
          fading = active;
          fadeT = t;
          active = makeSketch(t + 0.2);
        }
        let fadeAlpha = 0;
        if (fading) {
          fadeAlpha = 1 - smoothstep((t - fadeT) / FADE);
          if (fadeAlpha <= 0) fading = null;
        }

        const sk = active;
        for (let e = 0; e < sk.els.length; e++) {
          const el = sk.els[e];
          fadeP[e] = smoothstep(
            Math.min(1, Math.max(0, (t - sk.startT - el.start) / el.dur)),
          );
        }
        const frameIn = fadeP[0];

        const styleNone = fieldStyle(0);
        const styleA = fieldStyle(frameIn);
        const styleF = fadeAlpha > 0 ? fieldStyle(fadeAlpha) : styleNone;
        const styleAF =
          fadeAlpha > 0 ? fieldStyle(Math.max(frameIn, fadeAlpha)) : styleA;

        const n = cells.length;
        for (let i = 0; i < n; i++) {
          const cell = cells[i];

          let m = 0;
          let level = 0;
          const base = i * SLOTS;
          for (let s = base; s < base + SLOTS; s++) {
            const e = sk.cellEl[s];
            if (e < 0) break;
            const v = sk.cellQ[s] * fadeP[e];
            if (v > m) {
              m = v;
              level = sk.els[e].level;
            }
          }
          if (fading) {
            for (let s = base; s < base + SLOTS; s++) {
              const e = fading.cellEl[s];
              if (e < 0) break;
              const v = fading.cellQ[s] * fadeAlpha;
              if (v > m) {
                m = v;
                level = fading.els[e].level;
              }
            }
          }

          const tau = t / SWAP_STEP + cell.phase;
          const step = Math.floor(tau);
          const frac = tau - step;
          const shuffleScale = smoothstep(
            Math.min(frac, 1 - frac) / POP_DURATION,
          );

          const kind = Math.floor(
            hash01(cell.seed * 97 + step * 7919) * 3,
          ) as ShapeKind;
          if (kind !== cell.kind && m < 0.02 && shuffleScale < 0.05) {
            cell.kind = kind;
          }

          const scale = Math.max(shuffleScale * (1 - m), m);
          if (scale < 0.01) continue;

          if (m < 0.02) {
            const inA = sk.inFrame[i] === 1;
            const inF = fading ? fading.inFrame[i] === 1 : false;
            if (inA) {
              ctx.fillStyle = inF ? styleAF : styleA;
            } else {
              ctx.fillStyle = inF ? styleF : styleNone;
            }
            const dim = Math.max(inA ? frameIn : 0, inF ? fadeAlpha : 0);
            drawShape(
              ctx,
              cell.kind,
              cell.x,
              cell.y,
              cell.size * scale * (1 - 0.2 * dim),
            );
          } else {
            ctx.fillStyle = liftStyle(m);
            const markMul = 1 + (LEVEL_MARK[level] - 1) * m;
            drawShape(ctx, cell.kind, cell.x, cell.y, cell.size * scale * markMul);
          }
        }
      };

      rebuild();

      let raf = 0;
      if (reducedMotion) {
        active = makeSketch(-100);
        paint(0);
      } else {
        const t0 = performance.now();
        const frame = (now: number) => {
          paint((now - t0) / 1000);
          raf = requestAnimationFrame(frame);
        };
        raf = requestAnimationFrame(frame);
      }

      const observer = new ResizeObserver(() => {
        rebuild();
        if (reducedMotion) {
          active = makeSketch(-100);
          paint(0);
        }
      });
      observer.observe(canvas);

      cleanupRef.current = () => {
        cancelAnimationFrame(raf);
        observer.disconnect();
        if (trackGlobalLoaderCount) setLoaderCount((c) => c - 1);
      };
    },
    [trackGlobalLoaderCount, setLoaderCount],
  );

  return (
    <canvas
      ref={canvasRef}
      aria-hidden="true"
      className={`bg-background h-full w-full ${className}`.trim()}
    />
  );
};

export default CoalesceLoader;
