import { useTelemetryIdentity } from '@/hooks/useTelemetryIdentity';
import { useAtom, useAtomValue, useSetAtom } from 'jotai';
import { motion, useReducedMotion } from 'motion/react';
import posthog from 'posthog-js';
import { usePostHog } from 'posthog-js/react';
import { useCallback, useEffect, useState } from 'react';
import ElementInspector from './components/ElementInspector';
import EditorToaster from './components/EditorToaster';
import PreviewFrame from './components/PreviewFrame';
import AuthScreenView from './components/AuthScreenView';
import AuthProgressScreen from './components/AuthProgressScreen';
import RivetPanelLauncher, {
  clampRivetPanelLauncherPosition,
  getDefaultRivetPanelLauncherPosition,
  type RivetPanelLauncherPosition,
} from './components/RivetPanelLauncher';
import { useConfig } from './hooks/useConfig';
import { useOAuthCallback } from './hooks/useOAuthCallback';
import { useAgentVariantsSession } from './hooks/useAgentVariantsSession';
import { springs } from '@/lib/springs';
import ConnectorsModal from './components/ConnectorsModal';
import type { IntegrationProvider } from './hooks/useIntegrations';
import { JUST_SIGNED_IN_STORAGE_KEY } from './constants/auth';
import {
  configPendingAtom,
  fullscreenLoaderCountAtom,
  panelOpenAtom,
  projectPathAtom,
} from './store/atoms';
import { isTextEntryTarget } from './utils/textEntryTarget';
import { isToggleRivetShortcut } from './utils/toggleRivetShortcut';
import { useLogin } from '@/hooks/useLogin';
import { getProjectTitle, setDocumentTitle } from '@/utils/projectTitle';

const PANEL_MIN_WIDTH_PX = 274;
const PANEL_MAX_WIDTH_PX = 395;
const PANEL_DEFAULT_WIDTH_PX = Math.min(
  PANEL_MAX_WIDTH_PX,
  Math.round(((PANEL_MIN_WIDTH_PX + PANEL_MAX_WIDTH_PX) / 2) * 1.1),
);
const PANEL_WIDTH_STORAGE_KEY = 'rivet:panelWidth:v2';

type RivetToggleSource = 'shortcut' | 'click';

type MainEditorProps = {
  libraryOrigin: string | null;
};

const MainEditor = ({ libraryOrigin }: MainEditorProps) => {
  const isFullscreenLoaderActive = useAtomValue(fullscreenLoaderCountAtom) > 0;
  const [isPanelVisible, setIsPanelVisible] = useAtom(panelOpenAtom);
  const posthogClient = usePostHog();
  const prefersReducedMotion = useReducedMotion();
  const toggleRivet = useCallback(
    (source: RivetToggleSource) => {
      const isOpen = !isPanelVisible;
      posthogClient?.capture('editor.ui_toggled', { source, isOpen });
      setIsPanelVisible(isOpen);
    },
    [isPanelVisible, posthogClient, setIsPanelVisible],
  );
  const [panelWidth, setPanelWidth] = useState<number>(() => {
    if (typeof window === 'undefined') return PANEL_DEFAULT_WIDTH_PX;
    const stored = Number(window.localStorage.getItem(PANEL_WIDTH_STORAGE_KEY));
    return Number.isFinite(stored) &&
      stored >= PANEL_MIN_WIDTH_PX &&
      stored <= PANEL_MAX_WIDTH_PX
      ? stored
      : PANEL_DEFAULT_WIDTH_PX;
  });
  const [isResizingPanel, setIsResizingPanel] = useState(false);
  const [panelLauncherPosition, setPanelLauncherPosition] =
    useState<RivetPanelLauncherPosition>(getDefaultRivetPanelLauncherPosition);
  const launcherBoundsLeftPx = isPanelVisible ? panelWidth : 0;
  const panelSlideTransition = isPanelVisible ? springs.slow : springs.moderate;
  const [isPanelSpaceReserved, setIsPanelSpaceReserved] =
    useState(isPanelVisible);
  if (!isPanelVisible && isPanelSpaceReserved) setIsPanelSpaceReserved(false);
  const [appliedLauncherBoundsLeftPx, setAppliedLauncherBoundsLeftPx] =
    useState(0);
  if (launcherBoundsLeftPx !== appliedLauncherBoundsLeftPx) {
    setAppliedLauncherBoundsLeftPx(launcherBoundsLeftPx);
    if (isPanelVisible) {
      setPanelLauncherPosition((position) =>
        clampRivetPanelLauncherPosition({ position, boundsLeftPx: panelWidth }),
      );
    }
  }
  useEffect(() => {
    window.localStorage.setItem(PANEL_WIDTH_STORAGE_KEY, String(panelWidth));
  }, [panelWidth]);
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (isTextEntryTarget(event.target)) return;
      if (isToggleRivetShortcut(event)) {
        event.preventDefault();
        toggleRivet('shortcut');
        return;
      }
      if (event.key !== 'Escape' || !isPanelVisible) return;
      event.preventDefault();
      setIsPanelVisible(false);
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isPanelVisible, setIsPanelVisible, toggleRivet]);
  const startPanelResize = useCallback(
    (e: React.PointerEvent) => {
      e.preventDefault();
      e.stopPropagation();
      const startX = e.clientX;
      const startWidth = panelWidth;
      setIsResizingPanel(true);
      const onMove = (ev: PointerEvent) => {
        const next = Math.min(
          PANEL_MAX_WIDTH_PX,
          Math.max(PANEL_MIN_WIDTH_PX, startWidth + (ev.clientX - startX)),
        );
        setPanelWidth(next);
      };
      const endResize = () => {
        window.removeEventListener('pointermove', onMove);
        window.removeEventListener('pointerup', endResize);
        window.removeEventListener('pointercancel', endResize);
        setIsResizingPanel(false);
      };
      window.addEventListener('pointermove', onMove);
      window.addEventListener('pointerup', endResize);
      window.addEventListener('pointercancel', endResize);
    },
    [panelWidth],
  );
  const resetPanelWidth = useCallback(
    () => setPanelWidth(PANEL_DEFAULT_WIDTH_PX),
    [],
  );
  const oauthState = useOAuthCallback();
  const configPending = useAtomValue(configPendingAtom);
  useAgentVariantsSession({ enabled: !configPending });
  const fullPageAuthProgressMessage = oauthState.isProcessing
    ? 'Completing authentication...'
    : null;
  return (
    <motion.div
      className="relative flex h-screen overflow-hidden"
      initial={false}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.5, ease: 'easeOut' }}
      data-cy="rivet-app"
    >
      {fullPageAuthProgressMessage !== null ? (
        <div className="z-ui-primary absolute inset-0">
          <AuthProgressScreen message={fullPageAuthProgressMessage} />
        </div>
      ) : null}
      { }
      <PreviewFrame />

      <>
        {!isFullscreenLoaderActive ? (
          <>
            {









}
            <div
              className="relative order-first h-full flex-shrink-0"
              style={{ width: isPanelSpaceReserved ? panelWidth : 0 }}
            >
              <motion.div
                className="z-panel absolute inset-y-0 left-0"
                initial={false}
                animate={{ x: isPanelVisible ? 0 : -panelWidth }}
                transition={
                  prefersReducedMotion ? { duration: 0 } : panelSlideTransition
                }
                onAnimationComplete={() => {
                  if (isPanelVisible) setIsPanelSpaceReserved(true);
                }}
                style={{ width: panelWidth, willChange: 'transform' }}
              >
                <ElementInspector
                  onClose={() => setIsPanelVisible(false)}
                  libraryOrigin={libraryOrigin}
                />
                {

}
                <div
                  role="separator"
                  aria-orientation="vertical"
                  aria-label="Resize panel"
                  onPointerDown={startPanelResize}
                  onDoubleClick={resetPanelWidth}
                  className="group/resize absolute inset-y-0 right-0 z-20 flex w-3 cursor-col-resize touch-none justify-end"
                >
                  {
}
                  <span
                    className={`h-full transition-all duration-150 ${
                      isResizingPanel
                        ? 'bg-soft-foreground w-0.5'
                        : 'bg-border-strong group-hover/resize:bg-soft-foreground w-px group-hover/resize:w-0.5'
                    }`}
                  />
                </div>
              </motion.div>
            </div>

            {


}
            {isResizingPanel && (
              <div className="fixed inset-0 z-max cursor-col-resize" />
            )}

            {


}
            <RivetPanelLauncher
              isVisible
              isPanelOpen={isPanelVisible}
              isReducedMotion={Boolean(prefersReducedMotion)}
              position={panelLauncherPosition}
              dragBoundsLeftPx={launcherBoundsLeftPx}
              onPositionChange={setPanelLauncherPosition}
              onToggle={() => toggleRivet('click')}
            />
          </>
        ) : null}
      </>

      { }
      <EditorToaster />
    </motion.div>
  );
};

const CONNECT_DEEP_LINK_STORAGE_KEY = 'rivet_connect_deep_link';

const readConnectDeepLink = (): IntegrationProvider | null => {
  if (typeof window === 'undefined') {
    return null;
  }
  const params = new URLSearchParams(window.location.search);
  const fromUrl = params.get('connect');
  const provider =
    fromUrl ?? window.sessionStorage.getItem(CONNECT_DEEP_LINK_STORAGE_KEY);
  if (provider !== 'pinterest' && provider !== 'arena' && provider !== 'x') {
    return null;
  }
  window.sessionStorage.setItem(CONNECT_DEEP_LINK_STORAGE_KEY, provider);
  if (fromUrl) {
    params.delete('connect');
    const query = params.toString();
    window.history.replaceState(
      null,
      document.title,
      window.location.pathname +
        (query ? `?${query}` : '') +
        window.location.hash,
    );
  }
  return provider;
};

const initialConnectDeepLinkProvider = readConnectDeepLink();

const App = () => {
  const [justSignedIn] = useState(
    () =>
      typeof window !== 'undefined' &&
      window.sessionStorage.getItem(JUST_SIGNED_IN_STORAGE_KEY) === '1',
  );
  const [connectorsLandingDismissed, setConnectorsLandingDismissed] =
    useState(false);
  const [deepLinkConnectProvider, setDeepLinkConnectProvider] =
    useState<IntegrationProvider | null>(initialConnectDeepLinkProvider);

  useEffect(() => {
    if (justSignedIn) {
      window.sessionStorage.removeItem(JUST_SIGNED_IN_STORAGE_KEY);
    }
  }, [justSignedIn]);
  const {
    config,
    refetchConfig,
    loading: configLoading,
    error: configError,
  } = useConfig();
  const setProjectPath = useSetAtom(projectPathAtom);
  useEffect(() => {
    setProjectPath(config?.projectPath ?? null);
    return setDocumentTitle(
      getProjectTitle({
        name: config?.projectName,
        projectPath: config?.projectPath,
      }),
    );
  }, [config?.projectPath, config?.projectName, setProjectPath]);
  const setConfigPending = useSetAtom(configPendingAtom);
  const { startLogin, isStartingLogin, loginError, signInUrl } = useLogin();
  const [isRetryingConfig, setIsRetryingConfig] = useState(false);
  useTelemetryIdentity(config ?? undefined);

  useEffect(() => {
    if (!config) return;
    posthog.register({
      source: 'visual_editor',
      surface: 'visual_editor',
    });
  }, [config]);

  const shouldShowFullPageSignIn =
    config != null && config.agentModeAvailable !== true;

  const retryConfig = useCallback(async () => {
    setIsRetryingConfig(true);
    setConfigPending(true);
    try {
      await refetchConfig();
    } finally {
      setConfigPending(false);
      setIsRetryingConfig(false);
    }
  }, [refetchConfig, setConfigPending]);

  const showConfigError =
    !configLoading && config === null && !isRetryingConfig;

  if (showConfigError) {
    const message = configError || 'Could not load Rivet configuration.';
    return (
      <div className="bg-background flex h-screen items-center justify-center px-6">
        <div className="border-border-strong bg-background w-full max-w-md rounded-lg border p-6 text-center shadow-floating">
          <p className="text-foreground text-sm font-medium">
            We could not start Rivet yet.
          </p>
          <p className="text-soft-foreground mt-2 text-xs">{message}</p>
          <button
            type="button"
            className="border-border-strong text-foreground hover:bg-background/80 mt-4 rounded-md border px-3 py-1.5 text-xs"
            onClick={() => {
              void retryConfig();
            }}
          >
            Retry
          </button>
        </div>
      </div>
    );
  }


  if (shouldShowFullPageSignIn) {
    return (
      <AuthScreenView
        isSigningIn={isStartingLogin}
        onStartSignIn={() => {
          void startLogin();
        }}
        errorMessage={loginError}
        signInUrl={signInUrl}
      />
    );
  }

  const showDeepLinkConnectors =
    config?.agentModeAvailable === true && deepLinkConnectProvider !== null;

  const showOnboardingConnectors =
    config?.agentModeAvailable === true &&
    justSignedIn &&
    !connectorsLandingDismissed &&
    !showDeepLinkConnectors;

  return (
    <>
      <MainEditor
        libraryOrigin={config?.libraryOrigin ?? null}
      />
      <ConnectorsModal
        context="onboarding"
        isOpen={showOnboardingConnectors}
        onClose={() => setConnectorsLandingDismissed(true)}
      />
      <ConnectorsModal
        context="menu"
        isOpen={showDeepLinkConnectors}
        highlightProvider={deepLinkConnectProvider}
        onClose={() => {
          window.sessionStorage.removeItem(CONNECT_DEEP_LINK_STORAGE_KEY);
          setDeepLinkConnectProvider(null);
        }}
      />
    </>
  );
};

export default App;
