import { fetchLocalApi } from '@/utils/localApi';
import { queryKeys } from '@/utils/queryKeys';
import { fetchRivetConfig, type RivetConfig } from '@/utils/rivetConfig';
import { useCallback, useLayoutEffect } from 'react';
import { useQuery } from '@tanstack/react-query';
import { useAtomValue, useSetAtom } from 'jotai';
import { z } from 'zod';
import { createLogger } from '../utils/logger';
import {
  DEFAULT_FEATURE_FLAGS,
  agentApplyModeAtom,
  agentModeAvailableAtom,
  configPendingAtom,
  featureFlagsAtom,
  featureFlagsLoadedAtom,
  isMCPSessionAtom,
  mcpEditorAtom,
  launchContextAtom,
  projectIdAtom,
  queueAccessTokenAtom,
  userProfileAtom,
} from '../store/atoms';
import type { FeatureFlags } from '../store/atoms';

const log = createLogger('useConfig');
const CONFIG_QUERY_STALE_TIME_MS = 5 * 60 * 1000;
const CONFIG_QUERY_GC_TIME_MS = 30 * 60 * 1000;
const FEATURE_FLAGS_QUERY_STALE_TIME_MS = 60 * 1000;
const FEATURE_FLAGS_QUERY_GC_TIME_MS = 5 * 60 * 1000;

type FeatureFlagPayload = Partial<FeatureFlags>;
type FeatureFlagsResponse = {
  featureFlags?: FeatureFlagPayload;
};

const getBootstrapQueueAccessToken = (): string | null => {
  if (typeof window === 'undefined') {
    return null;
  }
  return window.__RIVET_BOOTSTRAP__?.queueAccessToken ?? null;
};

const getBootstrapAgentApplyMode = (): RivetConfig['agentApplyMode'] => {
  if (typeof window === 'undefined') {
    return null;
  }
  return window.__RIVET_BOOTSTRAP__?.agentApplyMode ?? null;
};

const FeatureFlagsResponseSchema = z.object({
  featureFlags: z
    .record(z.string(), z.object({ isEnabled: z.boolean() }))
    .optional(),
});

const fetchFeatureFlags = async (): Promise<FeatureFlagsResponse> => {
  const response = await fetchLocalApi('/api/feature-flags');
  if (!response.ok) {
    throw new Error(`Failed to fetch feature flags: ${response.statusText}`);
  }
  return FeatureFlagsResponseSchema.parse(await response.json());
};

const mergeFeatureFlags = (
  featureFlags: FeatureFlagPayload | undefined,
): FeatureFlags => ({
  ...DEFAULT_FEATURE_FLAGS,
  ...(featureFlags ?? {}),
});

export const useConfig = () => {
  const launchContext = useAtomValue(launchContextAtom);
  const featureFlags = useAtomValue(featureFlagsAtom);
  const setFeatureFlags = useSetAtom(featureFlagsAtom);
  const setIsMCPSession = useSetAtom(isMCPSessionAtom);
  const setMcpEditor = useSetAtom(mcpEditorAtom);
  const setAgentApplyMode = useSetAtom(agentApplyModeAtom);
  const setQueueAccessToken = useSetAtom(queueAccessTokenAtom);
  const setAgentModeAvailable = useSetAtom(agentModeAvailableAtom);
  const setFeatureFlagsLoaded = useSetAtom(featureFlagsLoadedAtom);
  const setConfigPending = useSetAtom(configPendingAtom);
  const setUserProfile = useSetAtom(userProfileAtom);
  const setProjectId = useSetAtom(projectIdAtom);

  const applyFetchedConfig = useCallback(
    (data: RivetConfig) => {
      setAgentModeAvailable(data.agentModeAvailable);
      setProjectId(data.projectId ?? null);
      setUserProfile({ name: data.name ?? null, email: data.email ?? null });
      if (data.isMCPSession) {
        setIsMCPSession(true);
      }
      setMcpEditor(
        launchContext.isCaptured ? launchContext.runtime : data.mcpEditor,
      );
      setAgentApplyMode(
        data.agentApplyMode ?? getBootstrapAgentApplyMode() ?? null,
      );
      setQueueAccessToken(
        data.queueAccessToken ?? getBootstrapQueueAccessToken(),
      );
    },
    [
      setAgentApplyMode,
      setAgentModeAvailable,
      setIsMCPSession,
      setMcpEditor,
      setQueueAccessToken,
      setProjectId,
      setUserProfile,
      launchContext,
    ],
  );

  const query = useQuery({
    queryKey: queryKeys.rivetConfig,
    queryFn: fetchRivetConfig,
    staleTime: CONFIG_QUERY_STALE_TIME_MS,
    gcTime: CONFIG_QUERY_GC_TIME_MS,
  });
  const featureFlagsQuery = useQuery({
    queryKey: queryKeys.featureFlags,
    queryFn: fetchFeatureFlags,
    staleTime: FEATURE_FLAGS_QUERY_STALE_TIME_MS,
    gcTime: FEATURE_FLAGS_QUERY_GC_TIME_MS,
  });
  const { refetch } = query;
  const { refetch: refetchFeatureFlags } = featureFlagsQuery;

  useLayoutEffect(() => {
    if (query.data) {
      applyFetchedConfig(query.data);
      setConfigPending(false);
      log.info('Config loaded:', query.data);
    }
    if (featureFlagsQuery.data) {
      setFeatureFlags(mergeFeatureFlags(featureFlagsQuery.data.featureFlags));
      setFeatureFlagsLoaded(true);
    }
    if (query.error) {
      setFeatureFlagsLoaded(true);
      setConfigPending(false);
      log.warn('Failed to load config:', query.error.message);
    }
    if (featureFlagsQuery.error) {
      setFeatureFlagsLoaded(true);
      log.warn(
        'Failed to load feature flags:',
        featureFlagsQuery.error.message,
      );
    }
  }, [
    query.data,
    query.error,
    featureFlagsQuery.data,
    featureFlagsQuery.error,
    applyFetchedConfig,
    setConfigPending,
    setFeatureFlags,
    setFeatureFlagsLoaded,
  ]);

  const refetchConfig = useCallback(async (): Promise<RivetConfig | null> => {
    const [result] = await Promise.all([refetch(), refetchFeatureFlags()]);
    if (result.data) {
      return result.data;
    }
    return null;
  }, [refetch, refetchFeatureFlags]);

  return {
    config: query.data ?? null,
    featureFlags,
    loading: query.isPending || (!query.error && featureFlagsQuery.isPending),
    error: query.error ? query.error.message : null,
    refetchConfig,
  };
};
