import { forwardRef } from 'react';
import type { Icon } from '@phosphor-icons/react';
import { cn } from '@/lib/utils';
import {
  Input as FluidInput,
  type InputProps as FluidInputProps,
} from '@/components/ui/input';

type TextInputSize = 'default' | 'compact';

type TextInputProps = Omit<FluidInputProps, 'size' | 'type'> & {
  type?: 'text' | 'search' | 'url';
  size?: TextInputSize;
  leadingIcon?: Icon;
  isInvalid?: boolean;
  containerClassName?: string;
};

const FIELD_TREATMENT = [
  'border-separator bg-muted placeholder:text-soft-foreground',
  'hover:border-soft-foreground/50 hover:bg-muted',
  'focus:border-soft-foreground focus:hover:bg-muted focus-visible:border-soft-foreground focus-visible:outline-hidden',
  'aria-invalid:border-destructive aria-invalid:focus:border-destructive',
  'motion-reduce:transition-none',
];

const TYPE_SIZE = {
  default: 'text-sm',
  compact: 'text-xs',
};

const LEADING_ICON_LAYOUT = {
  default: { size: 14, inset: 'left-3', fieldPadding: 'pl-9' },
  compact: { size: 13, inset: 'left-2.5', fieldPadding: 'pl-7' },
};

const HIDDEN_SEARCH_CLEAR_BUTTON = '[&::-webkit-search-cancel-button]:hidden';

const TextInput = forwardRef<HTMLInputElement, TextInputProps>(
  (
    {
      type = 'text',
      size = 'default',
      leadingIcon: LeadingIcon,
      isInvalid,
      containerClassName,
      className,
      style,
      ...props
    },
    ref,
  ) => {
    const field = (
      <FluidInput
        {...props}
        ref={ref}
        type={type}
        size={size}
        aria-invalid={isInvalid ? true : props['aria-invalid']}
        className={cn(
          FIELD_TREATMENT,
          TYPE_SIZE[size],
          type === 'search' && HIDDEN_SEARCH_CLEAR_BUTTON,
          LeadingIcon && LEADING_ICON_LAYOUT[size].fieldPadding,
          className,
        )}
        style={{ fontVariationSettings: 'normal', ...style }}
      />
    );

    if (!LeadingIcon) return field;

    const layout = LEADING_ICON_LAYOUT[size];
    return (
      <span
        className={cn('relative flex min-w-0 items-center', containerClassName)}
      >
        <LeadingIcon
          size={layout.size}
          weight="regular"
          aria-hidden
          className={cn(
            'text-soft-foreground pointer-events-none absolute top-1/2 -translate-y-1/2',
            layout.inset,
          )}
        />
        {field}
      </span>
    );
  },
);
TextInput.displayName = 'TextInput';

export type { TextInputProps };
export default TextInput;
