import { useId } from 'react';
import { useQuery } from '@tanstack/react-query';
import { usePostHog } from 'posthog-js/react';
import type {
  ReferenceProvider,
  ReferenceDiscoveryRequest,
} from '@rivet/core/types/reference-connectors';
import { discoverReferenceCollections } from '@/hooks/useReferenceProfile';
import { queryKeys } from '@/utils/queryKeys';

const DISCOVERY_CACHE_LIFETIME_MS = 0;
const getDiscoverySource = (
  provider: ReferenceProvider,
  profileUrl: string | null,
): ReferenceDiscoveryRequest | null => {
  if (provider !== 'cosmos') return { provider };
  if (profileUrl) return { url: profileUrl };
  return null;
};

export const useReferenceDiscovery = (
  provider: ReferenceProvider,
  profileUrl: string | null,
) => {
  const posthog = usePostHog();
  const viewId = useId();
  const discoverySource = getDiscoverySource(provider, profileUrl);
  return useQuery({
    queryKey: queryKeys.referenceDiscovery({ viewId, source: discoverySource }),
    enabled: discoverySource !== null,
    retry: false,
    staleTime: Infinity,
    gcTime: DISCOVERY_CACHE_LIFETIME_MS,
    refetchOnWindowFocus: false,
    refetchOnReconnect: false,
    queryFn: async ({ signal }) => {
      if (!discoverySource) throw new Error('Choose a reference source first.');
      posthog?.capture('visual_editor_reference_discovery_started', {
        provider,
      });
      try {
        const result = await discoverReferenceCollections(
          discoverySource,
          signal,
        );
        if ('status' in result)
          posthog?.capture('visual_editor_reference_discovery_failed', {
            provider,
          });
        else
          posthog?.capture('visual_editor_reference_discovery_completed', {
            provider,
            collection_count: result.collections.length,
          });
        return result;
      } catch (cause) {
        if (!signal.aborted)
          posthog?.capture('visual_editor_reference_discovery_failed', {
            provider,
          });
        throw cause;
      }
    },
  });
};
