import ReferenceProviderIcon, {
  type ReferenceProvider,
} from './ReferenceProviderIcon';
import { useState } from 'react';
import { usePostHog } from 'posthog-js/react';
import {
  mergeVariantReferences,
  type VariantReference,
} from '@rivet/core/types/variant-reference';
import { cn } from '@/lib/utils';
import { useDesignLibraryEntryUrls } from '@/hooks/useDesignLibraryEntryUrls';

interface VariantReferenceLinksProps {
  references?: VariantReference[];
  source: 'active' | 'history';
  sessionId?: string | null;
  variantId?: string;
  projectPath?: string | null;
  className?: string;
}

type ReferenceChipProps = {
  reference: VariantReference;
  imageUrl?: string;
  libraryEntryUrl?: string;
  onOpen: () => void;
};

const referenceProvider = (url: string): ReferenceProvider | null => {
  const host = new URL(url).hostname.replace(/^www\./, '');
  if (host === 'are.na') return 'arena';
  if (host === 'pinterest.com' || host === 'pin.it') return 'pinterest';
  if (host === 'x.com') return 'x';
  if (host === 'cosmos.so') return 'cosmos';
  return null;
};

const ReferenceChip = ({
  reference,
  imageUrl,
  libraryEntryUrl,
  onOpen,
}: ReferenceChipProps) => {
  const [isImageUnavailable, setImageUnavailable] = useState(false);
  const hasImage = Boolean(imageUrl) && !isImageUnavailable;
  const provider = reference.url ? referenceProvider(reference.url) : null;
  const href =
    libraryEntryUrl ?? reference.url ?? (hasImage ? imageUrl : undefined);
  const Chip = href ? 'a' : 'span';
  const label =
    hasImage && reference.url
      ? new URL(reference.url).hostname
      : reference.title;
  return (
    <Chip
      href={href}
      target={href ? '_blank' : undefined}
      rel={href ? 'noopener noreferrer' : undefined}
      aria-label={reference.title}
      onPointerDown={(event) => event.stopPropagation()}
      onKeyDown={(event) => {
        if (
          (event.key !== 'ArrowUp' && event.key !== 'ArrowDown') ||
          event.altKey ||
          event.ctrlKey ||
          event.metaKey ||
          event.shiftKey
        ) {
          event.stopPropagation();
        }
      }}
      onClick={(event) => {
        event.stopPropagation();
        if (href) onOpen();
      }}
      className={cn(
        'border-separator bg-muted text-foreground hover:border-soft-foreground/50 focus-visible:border-soft-foreground flex max-w-full min-w-0 shrink-0 items-center gap-1.5 overflow-hidden rounded-md border pr-1.5 text-xs focus-visible:outline-hidden',
        !hasImage && 'py-1.5 pl-2',
      )}
    >
      {hasImage ? (
        <img
          src={imageUrl}
          alt=""
          className="h-8 w-12 shrink-0 object-contain"
          width={48}
          height={32}
          onError={() => setImageUnavailable(true)}
        />
      ) : null}
      {provider && (hasImage || provider === 'cosmos') ? (
        <ReferenceProviderIcon
          provider={provider}
          className="h-3.5 w-3.5 shrink-0"
        />
      ) : null}
      {!hasImage || !provider ? (
        <span className="max-w-40 truncate">{label}</span>
      ) : null}
    </Chip>
  );
};

const VariantReferenceLinks = ({
  references,
  source,
  sessionId,
  variantId,
  projectPath,
  className,
}: VariantReferenceLinksProps) => {
  const posthog = usePostHog();
  const sources = mergeVariantReferences(references);
  const libraryEntryUrls = useDesignLibraryEntryUrls(
    sources?.map((reference) => reference.id) ?? [],
  );
  if (!sources) return null;
  return (
    <div
      className={cn(
        'ph-no-capture flex min-w-0 flex-nowrap gap-1.5 overflow-x-auto pr-3 pb-2',
        className,
      )}
      aria-label="References"
    >
      {sources.map((reference) => {
        const query = projectPath
          ? `?${new URLSearchParams({ projectPath })}`
          : '';
        const imageUrl =
          reference.image && sessionId && variantId
            ? `/api/variants/${encodeURIComponent(sessionId)}/${encodeURIComponent(variantId)}/references/${encodeURIComponent(reference.id)}/image${query}`
            : undefined;
        const libraryEntryUrl = libraryEntryUrls.get(reference.id);
        return (
          <ReferenceChip
            key={`${reference.id}:${reference.image?.hash ?? ''}:${imageUrl ?? ''}`}
            reference={reference}
            imageUrl={imageUrl}
            libraryEntryUrl={libraryEntryUrl}
            onOpen={() =>
              posthog?.capture('preview_reference_opened', {
                variant_source: source,
                reference_count: sources.length,
                is_library_entry: Boolean(libraryEntryUrl),
              })
            }
          />
        );
      })}
    </div>
  );
};

export default VariantReferenceLinks;
