import { EDITOR_ACCESS_TOKEN_FRAGMENT } from '@rivet/core/utils/editorAccess';

const EDITOR_SESSION_KEY = 'rivet_editor_token';
let capturedToken: string | null | undefined;

export const captureEditorToken = (): void => {
  if (window.location.pathname.startsWith('/rivet/library')) return;
  const fragment = new URLSearchParams(window.location.hash.slice(1));
  const token = fragment.get(EDITOR_ACCESS_TOKEN_FRAGMENT);
  if (token === null) return;
  capturedToken = token || null;
  fragment.delete(EDITOR_ACCESS_TOKEN_FRAGMENT);
  const remaining = fragment.toString();
  window.history.replaceState(
    null,
    '',
    `${window.location.pathname}${window.location.search}${remaining ? `#${remaining}` : ''}`,
  );
  try {
    if (token) window.sessionStorage.setItem(EDITOR_SESSION_KEY, token);
    else window.sessionStorage.removeItem(EDITOR_SESSION_KEY);
  } catch {}
};

export const editorAccessToken = (): string | null => {
  if (capturedToken !== undefined) return capturedToken;
  try {
    return window.sessionStorage.getItem(EDITOR_SESSION_KEY);
  } catch {
    return null;
  }
};
