import type {
  AuthorizationMethod,
  IntegrationProvider,
  IntegrationSummary,
} from '../hooks/useIntegrations';

export type ReferenceConnectionProvider = IntegrationProvider | 'cosmos';

type ReferenceConnectionEventOptions = {
  action: 'connect' | 'disconnect';
  outcome: 'started' | 'completed' | 'failed';
  provider: ReferenceConnectionProvider;
  entryPoint: 'menu' | 'onboarding' | 'library';
  durationMs?: number;
  failureReason?: 'sign_in_abandoned' | 'sign_in_timed_out' | 'request_failed';
  authorizationMethod?: AuthorizationMethod;
};

export const buildReferenceConnectionEvent = ({
  action,
  outcome,
  provider,
  entryPoint,
  durationMs,
  failureReason,
  authorizationMethod,
}: ReferenceConnectionEventOptions) => {
  const lifecycle = action === 'connect' ? 'connection' : 'disconnection';
  return {
    event: `visual_editor_reference_${lifecycle}_${outcome}`,
    properties: {
      provider,
      entry_point: entryPoint,
      ...(durationMs !== undefined ? { duration_ms: durationMs } : {}),
      ...(failureReason ? { failure_reason: failureReason } : {}),
      ...(authorizationMethod
        ? { authorization_method: authorizationMethod }
        : {}),
    },
  };
};

const INTEGRATION_PROVIDERS: IntegrationProvider[] = [
  'pinterest',
  'arena',
  'x',
];

export const connectedReferenceProviders = ({
  integrations,
  profileSources,
}: {
  integrations: Pick<IntegrationSummary, 'provider' | 'status'>[];
  profileSources: { provider: string }[];
}): ReferenceConnectionProvider[] => {
  const providers: ReferenceConnectionProvider[] = INTEGRATION_PROVIDERS.filter(
    (provider) =>
      integrations.some(
        (integration) =>
          integration.provider === provider &&
          integration.status === 'connected',
      ),
  );
  if (profileSources.some((source) => source.provider === 'cosmos'))
    providers.push('cosmos');
  return providers.sort();
};
