import { useAtomValue } from 'jotai';
import { createPortal } from 'react-dom';
import { draggedVariantAtom, draggedVariantPointerAtom } from '@/store/atoms';

export function VariantDragGhost() {
  const dragged = useAtomValue(draggedVariantAtom);
  const pointer = useAtomValue(draggedVariantPointerAtom);

  if (!dragged || !pointer) return null;

  return createPortal(
    <div
      aria-hidden="true"
      className="border-separator bg-background z-tooltip shadow-floating pointer-events-none fixed top-0 left-0 flex max-w-60 items-center gap-2 rounded-md border px-3 py-1.5"
      style={{
        transform: `translate3d(${pointer.x + 12}px, ${pointer.y + 12}px, 0)`,
      }}
    >
      <span className="text-foreground truncate text-sm font-medium">
        {dragged.label}
      </span>
    </div>,
    document.body,
  );
}

export default VariantDragGhost;
