import { useCallback, useRef } from 'react';
import type { KeyboardEvent, RefCallback } from 'react';
import { useLatestRef } from '@/hooks/useLatestRef';
import { registerOpenMenu } from '../utils/menuOpenRegistry';

const DEFAULT_ITEM_SELECTOR =
  '[data-menu-item]:not([disabled]):not([aria-disabled="true"]), [data-menu-control] button:not([disabled])';

type UseMenuListNavigationOptions = {
  itemSelector?: string;
  loop?: boolean;
  onDismiss?: () => void;
};

type UseMenuListNavigationResult<T extends HTMLElement> = {
  containerRef: RefCallback<T>;
  onKeyDown: (event: KeyboardEvent<T>) => void;
  onCloseAutoFocus: (event: Event) => void;
};

export const useMenuListNavigation = <T extends HTMLElement = HTMLDivElement>({
  itemSelector = DEFAULT_ITEM_SELECTOR,
  loop = false,
  onDismiss,
}: UseMenuListNavigationOptions = {}): UseMenuListNavigationResult<T> => {
  const containerRef = useRef<T | null>(null);
  const releaseRef = useRef<(() => void) | null>(null);
  const onDismissRef = useLatestRef(onDismiss);
  const isIframeDismissalRef = useRef(false);

  const containerRefCallback = useCallback<RefCallback<T>>(
    (node) => {
      containerRef.current = node;
      if (node) {
        isIframeDismissalRef.current = false;
        const releaseMenu = registerOpenMenu();
        const ownerWindow = node.ownerDocument.defaultView;
        let focusCheck: number | undefined;
        const onWindowBlur = () => {
          ownerWindow?.clearTimeout(focusCheck);
          focusCheck = ownerWindow?.setTimeout(() => {
            const focused = node.ownerDocument.activeElement;
            if (
              focused?.tagName === 'IFRAME' &&
              !node.contains(focused) &&
              onDismissRef.current
            ) {
              isIframeDismissalRef.current = true;
              onDismissRef.current();
            }
          });
        };
        ownerWindow?.addEventListener('blur', onWindowBlur);
        releaseRef.current = () => {
          ownerWindow?.removeEventListener('blur', onWindowBlur);
          ownerWindow?.clearTimeout(focusCheck);
          releaseMenu();
        };
      } else {
        releaseRef.current?.();
        releaseRef.current = null;
      }
    },
    [onDismissRef],
  );

  const onCloseAutoFocus = (event: Event) => {
    if (isIframeDismissalRef.current) event.preventDefault();
  };

  const onKeyDown = useCallback(
    (event: KeyboardEvent<T>) => {
      const { key } = event;
      if (event.defaultPrevented) return;
      if (
        key !== 'ArrowDown' &&
        key !== 'ArrowUp' &&
        key !== 'Home' &&
        key !== 'End'
      ) {
        return;
      }
      const container = containerRef.current;
      if (!container) return;
      const items = Array.from(
        container.querySelectorAll<HTMLElement>(itemSelector),
      );
      if (items.length === 0) return;

      event.preventDefault();
      event.stopPropagation();

      const currentIndex = items.indexOf(document.activeElement as HTMLElement);
      const lastIndex = items.length - 1;

      const step = (delta: 1 | -1): number => {
        if (currentIndex === -1) return delta === 1 ? 0 : lastIndex;
        const raw = currentIndex + delta;
        if (loop) return (raw + items.length) % items.length;
        return Math.min(Math.max(raw, 0), lastIndex);
      };

      let nextIndex: number;
      if (key === 'Home') {
        nextIndex = 0;
      } else if (key === 'End') {
        nextIndex = lastIndex;
      } else if (key === 'ArrowDown') {
        nextIndex = step(1);
      } else {
        nextIndex = step(-1);
      }
      items[nextIndex]?.focus();
    },
    [itemSelector, loop],
  );

  return { containerRef: containerRefCallback, onKeyDown, onCloseAutoFocus };
};
