import { useAtomValue, useSetAtom } from 'jotai';
import { useCallback, useMemo, useRef } from 'react';
import { usePostHog } from 'posthog-js/react';
import { X } from '@phosphor-icons/react';
import Button from '@/components/Button';
import {
  agentApplyModeAtom,
  agentVariantsSnapshotAtom,
  variantSplitViewAtom,
  type VariantSplitPreviewSource,
} from '@/store/atoms';
import type { PreviewTarget } from '@/types';
import { stopHistoryReplayTarget } from '@/utils/historyReplayCleanup';
import { resolvePreviewSrc } from '@/utils/previewOrigin';
import { resolveVariantPreviewUrl } from '@/utils/variantPreviewUrl';
import { buildVariantComparisonTelemetryEvent } from '@/utils/variantComparisonTelemetry';
import PreviewSurface from './PreviewSurface';
import Tooltip from './Tooltip';

export function SecondaryVariantIframe({
  side,
  sessionId,
  variantId,
  url,
  label,
  source,
  isFallback = false,
}: {
  side: 'left' | 'right';
  sessionId: string;
  variantId: string;
  url: string;
  label: string;
  source: VariantSplitPreviewSource;
  isFallback?: boolean;
}) {
  const split = useAtomValue(variantSplitViewAtom);
  const setSplit = useSetAtom(variantSplitViewAtom);
  const posthog = usePostHog();
  const variantsSnapshot = useAtomValue(agentVariantsSnapshotAtom);
  const agentApplyMode = useAtomValue(agentApplyModeAtom);
  const hasStoppedHistoryReplayRef = useRef(false);
  const stopHistoryReplay = useCallback(() => {
    if (hasStoppedHistoryReplayRef.current) return;
    hasStoppedHistoryReplayRef.current = true;
    stopHistoryReplayTarget({ source, sessionId, variantId });
  }, [source, sessionId, variantId]);
  const onCollapse = useCallback(() => {
    if (isFallback) {
      setSplit(null);
      const telemetryEvent = buildVariantComparisonTelemetryEvent(
        'ended',
        split,
      );
      posthog?.capture(telemetryEvent.event, telemetryEvent.properties);
      return;
    }
    stopHistoryReplay();
    const remainingSplit = { ...split };
    delete remainingSplit[side];
    const nextSplit =
      remainingSplit.left || remainingSplit.right ? remainingSplit : null;
    setSplit(nextSplit);
    const telemetryEvent = buildVariantComparisonTelemetryEvent(
      nextSplit ? 'updated' : 'ended',
      nextSplit ?? split,
    );
    posthog?.capture(telemetryEvent.event, telemetryEvent.properties);
  }, [isFallback, posthog, setSplit, side, split, stopHistoryReplay]);

  const target = useMemo<PreviewTarget>(
    () => ({ kind: 'variant', sessionId, variantId }),
    [sessionId, variantId],
  );
  const matchingVariant = useMemo(() => {
    if (!variantsSnapshot.active || variantsSnapshot.sessionId !== sessionId) {
      return null;
    }
    return (
      variantsSnapshot.variants.find(
        (variant) => variant.workItemId === variantId,
      ) ?? null
    );
  }, [sessionId, variantId, variantsSnapshot]);
  const effectiveUrl = useMemo(() => {
    let previewUrl = url;
    if (
      matchingVariant?.preview?.kind === 'static_artifact' &&
      matchingVariant.refinement?.status === 'succeeded'
    ) {
      if (matchingVariant.previewRoutes?.length)
        return resolvePreviewSrc({
          agentApplyMode,
          url:
            resolveVariantPreviewUrl({
              sessionId,
              variant: matchingVariant,
              projectContext: null,
            }) ?? url,
        });
      const separator = matchingVariant.preview.url.includes('?') ? '&' : '?';
      previewUrl = `${matchingVariant.preview.url}${separator}refinement=${encodeURIComponent(
        matchingVariant.refinement.workItemId,
      )}`;
    }
    return resolvePreviewSrc({ agentApplyMode, url: previewUrl });
  }, [agentApplyMode, matchingVariant, sessionId, url]);
  const remountKey =
    matchingVariant?.refinement?.status === 'succeeded'
      ? `${variantId}:${matchingVariant.refinement.workItemId}`
      : variantId;

  return (
    <div
      className="variant-split-secondary"
      data-cy="variant-split-pane"
      data-variant-id={variantId}
    >
      <div className="variant-split-secondary-toolbar">
        <span className="variant-split-secondary-label" title={label}>
          {label}
        </span>
        <Tooltip label="Collapse">
          <Button
            variant="ghost"
            size="icon-compact"
            onClick={onCollapse}
            aria-label="Collapse split view"
          >
            <X weight="bold" aria-hidden />
          </Button>
        </Tooltip>
      </div>
      <div className="variant-split-secondary-body relative min-h-0 flex-1">
        <PreviewSurface
          target={target}
          src={effectiveUrl}
          framework="static"
          remountKey={remountKey}
        />
      </div>
    </div>
  );
}

export default SecondaryVariantIframe;
