import { useCallback, useState } from 'react';
import { useQueryClient, type QueryKey } from '@tanstack/react-query';
import { useLatestRef } from '@/hooks/useLatestRef';

type ImmediateOverlay<Data> = {
  base: Data | undefined;
  value: Data;
};

export const useImmediateQueryData = <Data>({
  queryKey,
  data,
}: {
  queryKey: QueryKey;
  data: Data | undefined;
}) => {
  const queryClient = useQueryClient();
  const [overlay, setOverlay] = useState<ImmediateOverlay<Data> | null>(null);
  const visible =
    overlay !== null && overlay.base === data ? overlay.value : data;
  const latestRef = useLatestRef({ queryKey, data, visible });

  const updateData = useCallback(
    (update: (current: Data | undefined) => Data): Data => {
      const latest = latestRef.current;
      const next = update(
        queryClient.getQueryData<Data>(latest.queryKey) ?? latest.visible,
      );
      queryClient.setQueryData(latest.queryKey, next);
      latestRef.current = { ...latest, visible: next };
      setOverlay({ base: latest.data, value: next });
      return next;
    },
    [queryClient, latestRef],
  );

  return { data: visible, updateData };
};
