import { useState } from 'react';
import PreviewSurface, {
  type PreviewSurfaceProps,
} from '@/components/PreviewSurface';
import { previewTargetKey } from '@/types';

type RetainedFrame = {
  key: string;
  props: PreviewSurfaceProps;
  lastSelected: number;
};

type RetainedFrames = {
  selectedKey: string;
  remountKey: PreviewSurfaceProps['remountKey'];
  selection: number;
  frames: RetainedFrame[];
};

const MAX_RETAINED_PREVIEWS = 7;

const RetainedPreviewSurface = (props: PreviewSurfaceProps) => {
  const targetKey = previewTargetKey(props.target);
  const selectedKey = `${targetKey}:${props.src}`;
  const isBlank = props.src === 'about:blank';
  const [retained, setRetained] = useState<RetainedFrames>(() => ({
    selectedKey,
    remountKey: props.remountKey,
    selection: 0,
    frames: isBlank ? [] : [{ key: selectedKey, props, lastSelected: 0 }],
  }));

  if (
    retained.selectedKey !== selectedKey ||
    retained.remountKey !== props.remountKey
  ) {
    const selection = retained.selection + 1;
    const isRefresh = retained.remountKey !== props.remountKey;
    let frames = retained.frames.filter(
      (frame) =>
        !isRefresh || previewTargetKey(frame.props.target) !== targetKey,
    );
    if (!isBlank) {
      const existing = frames.find((frame) => frame.key === selectedKey);
      if (existing) {
        frames = frames.map((frame) =>
          frame === existing ? { ...frame, lastSelected: selection } : frame,
        );
      } else {
        frames = [
          ...frames,
          { key: selectedKey, props, lastSelected: selection },
        ];
      }
      if (frames.length > MAX_RETAINED_PREVIEWS) {
        const leastRecent = frames.reduce((least, frame) =>
          frame.lastSelected < least.lastSelected ? frame : least,
        );
        frames = frames.filter((frame) => frame !== leastRecent);
      }
    }
    setRetained({
      selectedKey,
      remountKey: props.remountKey,
      selection,
      frames,
    });
  }

  return (
    <div className="relative h-full w-full">
      {retained.frames.map((frame) => {
        const isActive = !isBlank && frame.key === selectedKey;
        return (
          <div
            key={`${frame.key}:${frame.props.remountKey ?? ''}`}
            className="absolute inset-0"
            style={{
              visibility: isActive ? 'visible' : 'hidden',
              pointerEvents: isActive ? 'auto' : 'none',
            }}
            aria-hidden={!isActive}
          >
            <PreviewSurface {...frame.props} isActive={isActive} />
          </div>
        );
      })}
      {isBlank ? <PreviewSurface {...props} /> : null}
    </div>
  );
};

export default RetainedPreviewSurface;
