export const FLAG_DEFINITIONS = {
  resize: { default: false },
  variants: { default: false },
  designSystemEditor: { default: false },
  branchDiff: { default: false },
  gitUi: { default: true },
  createProject: { default: false },
  share: { default: false },
  deployPrototype: { default: false },
  canvasShare: { default: false },
  generativeControls: { default: false },
  refineMode: { default: false },
  inspectorUndoRedo: { default: false },
} as const satisfies Record<string, { default: boolean }>;

export type FlagKey = keyof typeof FLAG_DEFINITIONS;
export type FeatureFlag = { isEnabled: boolean };
export type FeatureFlags = Record<FlagKey, FeatureFlag>;

export const DEFAULT_FEATURE_FLAGS: FeatureFlags = Object.fromEntries(
  Object.entries(FLAG_DEFINITIONS).map(([key, def]) => [
    key,
    { isEnabled: def.default },
  ]),
) as FeatureFlags;
